!
IP = 1
DO I = 1,M
   IB(I) = IP
   do 10 J = 1,N
      IF (A(I,J) .EQ. 0.D0) GO TO 10
      IF (IP .GT. NUM) GO TO 20
      B(IP) = A(I,J)
      JB(IP) = J
      IP = IP + 1
10 CONTINUE
END DO
!
!                 COMPLETE THE SETUP
!
IB(M + 1) = IP
IERR = 0
RETURN
!
!                   ERROR RETURN
!
20 IERR = I
RETURN
END SUBROUTINE CVDS

SUBROUTINE CVCS (A, KA, M, N, B, IB, JB, NUM, IERR)
IMPLICIT NONE
INTENT(IN) A, KA, M, N, NUM
INTENT(INOUT) B, IB, IERR, JB
INTEGER IERR, KA, M, N, NUM
INTEGER I, IP, J
COMPLEX A(KA,N), B(*), ZERO
INTEGER IB(*), JB(*)
DATA ZERO /(0.0,0.0)/
!
!                 STORE THE I-TH ROW
!
IP = 1
DO I = 1,M
   IB(I) = IP
   do 10 J = 1,N
      IF (A(I,J) .EQ. ZERO) GO TO 10
      IF (IP .GT. NUM) GO TO 20
      B(IP) = A(I,J)
      JB(IP) = J
      IP = IP + 1
10 CONTINUE
END DO
!
!                 COMPLETE THE SETUP
!
IB(M + 1) = IP
IERR = 0
RETURN
!
!                   ERROR RETURN
!
20 IERR = I
RETURN
END SUBROUTINE CVCS

SUBROUTINE CVSR (A, IA, JA, B, KB, M, N)
IMPLICIT NONE
INTENT(IN) A, IA, JA, KB, M, N
INTENT(INOUT) B
INTEGER KB, M, N
INTEGER I, IP, IPMAX, IPMIN, J
REAL A(*), B(KB,N)
INTEGER IA(*), JA(*)
!
do 30 I = 1,M
!
!                 CLEAR THE I-TH ROW
!
   DO J = 1,N
      B(I,J) = 0.0
   END DO
!
!                 STORE THE I-TH ROW
!
   IPMIN = IA(I)
   IPMAX = IA(I+1) - 1
   IF (IPMIN .GT. IPMAX) GO TO 30
   DO IP = IPMIN,IPMAX
      J = JA(IP)
      B(I,J) = A(IP)
   END DO
!
30 CONTINUE
RETURN
END SUBROUTINE CVSR

SUBROUTINE CVSD (A, IA, JA, B, KB, M, N)
IMPLICIT NONE
INTENT(IN) A, IA, JA, KB, M, N
INTENT(INOUT) B
INTEGER KB, M, N
INTEGER I, IP, IPMAX, IPMIN, J
DOUBLE PRECISION A(*), B(KB,N)
INTEGER IA(*), JA(*)
!
do 30 I = 1,M
!
!                 CLEAR THE I-TH ROW
!
   DO J = 1,N
      B(I,J) = 0.D0
   END DO
!
!                 STORE THE I-TH ROW
!
   IPMIN = IA(I)
   IPMAX = IA(I+1) - 1
   IF (IPMIN .GT. IPMAX) GO TO 30
   DO IP = IPMIN,IPMAX
      J = JA(IP)
      B(I,J) = A(IP)
   END DO
!
30 CONTINUE
RETURN
END SUBROUTINE CVSD

SUBROUTINE CVSC (A, IA, JA, B, KB, M, N)
IMPLICIT NONE
INTENT(IN) A, IA, JA, KB, M, N
INTENT(INOUT) B
INTEGER KB, M, N
INTEGER I, IP, IPMAX, IPMIN, J
COMPLEX A(*), B(KB,N)
INTEGER IA(*), JA(*)
!
do 30 I = 1,M
!
!                 CLEAR THE I-TH ROW
!
   DO J = 1,N
      B(I,J) = (0.0,0.0)
   END DO
!
!                 STORE THE I-TH ROW
!
   IPMIN = IA(I)
   IPMAX = IA(I+1) - 1
   IF (IPMIN .GT. IPMAX) GO TO 30
   DO IP = IPMIN,IPMAX
      J = JA(IP)
      B(I,J) = A(IP)
   END DO
!
30 CONTINUE
RETURN
END SUBROUTINE CVSC

SUBROUTINE SCVRD (A, IA, JA, B, IB, JB, M)
IMPLICIT NONE
INTENT(IN) A, IA, JA, M
INTENT(INOUT) B, IB, JB
INTEGER M
INTEGER I, IBEG, IEND, IP, L
REAL A(*)
DOUBLE PRECISION B(*)
INTEGER IA(*), JA(*), IB(*), JB(*)
!
L = 1
do 20 I = 1,M
   IB(I) = L
   IBEG = IA(I)
   IEND = IA(I+1) - 1
   IF (IBEG .GT. IEND) GO TO 20
   do 10 IP = IBEG,IEND
      IF (A(IP) .EQ. 0.0) GO TO 10
      B(L) = A(IP)
      JB(L) = JA(IP)
      L = L + 1
10 CONTINUE
20 CONTINUE
IB(M + 1) = L
RETURN
END SUBROUTINE SCVRD

SUBROUTINE SCVDR (A, IA, JA, B, IB, JB, M)
IMPLICIT NONE
INTENT(IN) A, IA, JA, M
INTENT(INOUT) B, IB, JB
INTEGER M
INTEGER I, IBEG, IEND, IP, L
DOUBLE PRECISION A(*)
REAL B(*)
INTEGER IA(*), JA(*), IB(*), JB(*)
!
L = 1
do 20 I = 1,M
   IB(I) = L
   IBEG = IA(I)
   IEND = IA(I+1) - 1
   IF (IBEG .GT. IEND) GO TO 20
   do 10 IP = IBEG,IEND
      IF (A(IP) .EQ. 0.D0) GO TO 10
      B(L) = A(IP)
      JB(L) = JA(IP)
      L = L + 1
10 CONTINUE
20 CONTINUE
IB(M + 1) = L
RETURN
END SUBROUTINE SCVDR

SUBROUTINE CSREAL (A, IA, JA, B, IB, JB, M)
IMPLICIT NONE
INTENT(IN) A, IA, JA, M
INTENT(INOUT) B, IB, JB
INTEGER M
INTEGER I, IBEG, IEND, IP, L
REAL T
!-----------------------------------------------------------------------
!              REAL PART OF A SPARSE COMPLEX MATRIX
!-----------------------------------------------------------------------
COMPLEX A(*)
REAL B(*)
INTEGER IA(*), JA(*), IB(*), JB(*)
!
L = 1
do 20 I = 1,M
   IB(I) = L
   IBEG = IA(I)
   IEND = IA(I+1) - 1
   IF (IBEG .GT. IEND) GO TO 20
   do 10 IP = IBEG,IEND
      T = REAL(A(IP))
      IF (T .EQ. 0.0) GO TO 10
      B(L) = T
      JB(L) = JA(IP)
      L = L + 1
10 CONTINUE
20 CONTINUE
IB(M + 1) = L
RETURN
END SUBROUTINE CSREAL

SUBROUTINE CSIMAG (A, IA, JA, B, IB, JB, M)
IMPLICIT NONE
INTENT(IN) A, IA, JA, M
INTENT(INOUT) B, IB, JB
INTEGER M
INTEGER I, IBEG, IEND, IP, L
REAL T
!-----------------------------------------------------------------------
!            IMAGINARY PART OF A SPARSE COMPLEX MATRIX
!-----------------------------------------------------------------------
COMPLEX A(*)
REAL B(*)
INTEGER IA(*), JA(*), IB(*), JB(*)
!
L = 1
do 20 I = 1,M
   IB(I) = L
   IBEG = IA(I)
   IEND = IA(I+1) - 1
   IF (IBEG .GT. IEND) GO TO 20
   do 10 IP = IBEG,IEND
      T = AIMAG(A(IP))
      IF (T .EQ. 0.0) GO TO 10
      B(L) = T
      JB(L) = JA(IP)
      L = L + 1
10 CONTINUE
20 CONTINUE
IB(M + 1) = L
RETURN
END SUBROUTINE CSIMAG

SUBROUTINE SCVRC (A,IA,JA,B,IB,JB,C,IC,JC,M,N,NUM,WK,IERR)
IMPLICIT NONE
INTENT(IN) A, B, IA, IB, JA, JB, M, N, NUM
INTENT(INOUT) C, IC, IERR, JC, WK
INTEGER IERR, M, N, NUM
INTEGER I, IP, J, L, MAXA, MAXB, MINA, MINB
!-----------------------------------------------------------------------
!       COMPUTE A + BI FOR THE SPARSE REAL MATRICES A AND B
!-----------------------------------------------------------------------
REAL A(*), B(*), WK(N)
COMPLEX C(*), T
INTEGER IA(*), JA(*), IB(*), JB(*), IC(*), JC(*)
!-------------------------
DO J = 1,N
   WK(J) = 0.0
END DO
!
!                  COMPUTE THE I-TH ROW OF C
!
IP = 1
do 42 I = 1,M
   IC(I) = IP
   MINA = IA(I)
   MAXA = IA(I+1) - 1
   IF (MINA .GT. MAXA) GO TO 30
   DO L = MINA,MAXA
      J = JA(L)
      WK(J) = A(L)
   END DO
!
30 MINB = IB(I)
   MAXB = IB(I+1) - 1
   IF (MINB .GT. MAXB) GO TO 40
   do 31 L = MINB,MAXB
      IF (B(L) .EQ. 0.0) GO TO 31
      J = JB(L)
      T = CMPLX (WK(J), B(L))
      WK(J) = 0.0
      IF (IP .GT. NUM) GO TO 50
      C(IP) = T
      JC(IP) = J
      IP = IP + 1
31 CONTINUE
!
40 IF (MINA .GT. MAXA) GO TO 42
   do 41 L = MINA,MAXA
      J = JA(L)
      IF (WK(J) .EQ. 0.0) GO TO 41
      IF (IP .GT. NUM) GO TO 50
      C(IP) = CMPLX (WK(J), 0.0)
      WK(J) = 0.0
      JC(IP) = J
      IP = IP + 1
41 CONTINUE
42 CONTINUE
IC(M + 1) = IP
IERR = 0
RETURN
!
!                        ERROR RETURN
!
50 IERR = I
RETURN
END SUBROUTINE SCVRC

SUBROUTINE RSCOPY (A, IA, JA, B, IB, JB, M)
IMPLICIT NONE
INTENT(IN) A, IA, JA, M
INTENT(INOUT) B, IB, JB
INTEGER M
INTEGER I, IBEG, IEND, IP, L
!-----------------------------------------------------------------------
!                  COPYING A SPARSE REAL MATRIX
!-----------------------------------------------------------------------
REAL A(*), B(*)
INTEGER IA(*), JA(*), IB(*), JB(*)
!
L = 1
do 20 I = 1,M
   IB(I) = L
   IBEG = IA(I)
   IEND = IA(I+1) - 1
   IF (IBEG .GT. IEND) GO TO 20
   do 10 IP = IBEG,IEND
      IF (A(IP) .EQ. 0.0) GO TO 10
      B(L) = A(IP)
      JB(L) = JA(IP)
      L = L + 1
10 CONTINUE
20 CONTINUE
IB(M + 1) = L
RETURN
END SUBROUTINE RSCOPY

SUBROUTINE DSCOPY (A, IA, JA, B, IB, JB, M)
