SUBROUTINE CSCOPY (A, IA, JA, B, IB, JB, M)
IMPLICIT NONE
INTENT(IN) A, IA, JA, M
INTENT(INOUT) B, IB, JB
INTEGER M
INTEGER I, IBEG, IEND, IP, L
!-----------------------------------------------------------------------
!                 COPYING A SPARSE COMPLEX MATRIX
!-----------------------------------------------------------------------
COMPLEX A(*), B(*), ZERO
INTEGER IA(*), JA(*), IB(*), JB(*)
DATA ZERO /(0.0,0.0)/
!
L = 1
do 20 I = 1,M
   IB(I) = L
   IBEG = IA(I)
   IEND = IA(I+1) - 1
   IF (IBEG .GT. IEND) GO TO 20
   do 10 IP = IBEG,IEND
      IF (A(IP) .EQ. ZERO) GO TO 10
      B(L) = A(IP)
      JB(L) = JA(IP)
      L = L + 1
10 CONTINUE
20 CONTINUE
IB(M + 1) = L
RETURN
END SUBROUTINE CSCOPY

SUBROUTINE SCONJ (A, IA, JA, B, IB, JB, M)
IMPLICIT NONE
INTENT(IN) A, IA, JA, M
INTENT(INOUT) B, IB, JB
INTEGER M
INTEGER I, IBEG, IEND, IP, L, MP1
!-----------------------------------------------------------------------
!     COMPUTATION OF THE CONJUGATE OF A SPARSE COMPLEX MATRIX
!-----------------------------------------------------------------------
COMPLEX A(*), B(*)
INTEGER IA(*), JA(*), IB(*), JB(*)
!
MP1 = M + 1
L = IA(1) - 1
DO I = 1,MP1
   IB(I) = IA(I) - L
END DO
!
IBEG = IA(1)
IEND = IA(MP1) - 1
IF (IBEG .GT. IEND) RETURN
L = 1
DO IP = IBEG,IEND
   B(L) = CONJG(A(IP))
   JB(L) = JA(IP)
   L = L + 1
END DO
RETURN
END SUBROUTINE SCONJ

SUBROUTINE RPOSE (A, IA, JA, B, IB, JB, M, N)
IMPLICIT NONE
INTENT(IN) A, IA, JA, M, N
INTENT(INOUT) B, IB, JB
INTEGER M, N
INTEGER I, IP, IPMAX, IPMIN, J, JJ, JP, NP1, NUM
!-----------------------------------------------------------------------
!                 TRANSPOSING A SPARSE REAL MATRIX
!-----------------------------------------------------------------------
REAL A(*), B(*)
INTEGER IA(*), JA(*), IB(*), JB(*)
!
!           COMPUTE THE NUMBER OF ELEMENTS IN EACH COLUMN
!                 OF A AND STORE THE RESULTS IN IB
!
IPMIN = IA(1)
IPMAX = IA(M+1) - 1
IF (IPMIN .GT. IPMAX) GO TO 40
DO J = 1,N
   IB(J) = 0
END DO
DO IP = IPMIN,IPMAX
   J = JA(IP)
   IB(J) = IB(J) + 1
END DO
!
!          COMPUTE THE ROW POINTERS OF THE TRANSPOSE MATRIX
!                AND STORE THEM IN IB(2),...,IB(N+1)
!
NUM = IA(M+1) - IA(1) + 1
J = N
DO JJ = 1,N
   NUM = NUM - IB(J)
   IB(J+1) = NUM
   J = J - 1
END DO
!
!                STORE THE I-TH ROW OF A IN B AND JB
!                  AND UPDATE THE POINTERS IN IB
!
do 31 I = 1,M
   IPMIN = IA(I)
   IPMAX = IA(I+1) - 1
   IF (IPMIN .GT. IPMAX) GO TO 31
   DO IP = IPMIN,IPMAX
      J = JA(IP)
      JP = IB(J+1)
      JB(JP) = I
      B(JP) = A(IP)
      IB(J+1) = JP + 1
   END DO
31 CONTINUE
IB(1) = 1
RETURN
!
!                    TRANSPOSE A ZERO MATRIX A
!
40 NP1 = N + 1
DO J = 1,NP1
   IB(J) = 1
END DO
RETURN
END SUBROUTINE RPOSE

