!-----------------------------------------------------------------------
REAL A(*), B(*), C(*), WK(N), T
INTEGER IA(*), JA(*), IB(*), JB(*), IC(*), JC(*)
!-------------------------
DO J = 1,N
   WK(J) = 0.0
