!
!                  COMPUTE THE I-TH ROW OF C
!
IP = 1
do 42 I = 1,M
   IC(I) = IP
   MINA = IA(I)
   MAXA = IA(I+1) - 1
   IF (MINA .GT. MAXA) GO TO 30
   DO L = MINA,MAXA
      J = JA(L)
      WK(J) = A(L)
   END DO
!
30 MINB = IB(I)
   MAXB = IB(I+1) - 1
   IF (MINB .GT. MAXB) GO TO 40
   do 31 L = MINB,MAXB
      J = JB(L)
      T = WK(J) - B(L)
      WK(J) = 0.0
      IF (T .EQ. 0.0) GO TO 31
      IF (IP .GT. NUM) GO TO 50
      C(IP) = T
      JC(IP) = J
      IP = IP + 1
31 CONTINUE
!
40 IF (MINA .GT. MAXA) GO TO 42
   do 41 L = MINA,MAXA
      J = JA(L)
      IF (WK(J) .EQ. 0.0) GO TO 41
      IF (IP .GT. NUM) GO TO 50
      C(IP) = WK(J)
      WK(J) = 0.0
      JC(IP) = J
      IP = IP + 1
41 CONTINUE
42 CONTINUE
IC(M + 1) = IP
IERR = 0
RETURN
!
!                        ERROR RETURN
!
50 IERR = I
RETURN
END SUBROUTINE SSUBT

