REAL function SNRM (A, IA, JA, M, N)
IMPLICIT NONE
INTENT(IN) A, IA, JA, M, N
INTEGER M, N
INTEGER I, IP, IPMAX, IPMIN
REAL SUM
!-----------------------------------------------------------------------
!             COMPUTATION OF THE L-INFINITY NORM OF A
!                      REAL SPARSE MATRIX A
!-----------------------------------------------------------------------
REAL A(*)
INTEGER IA(*), JA(*)
!
SNRM = 0.0
do 20 I = 1,M
   IPMIN = IA(I)
   IPMAX = IA(I + 1) - 1
   IF (IPMIN .GT. IPMAX) GO TO 20
   SUM = 0.0
   DO IP = IPMIN,IPMAX
      SUM = SUM + ABS(A(IP))
   END DO
   SNRM = AMAX1(SNRM, SUM)
20 CONTINUE
RETURN
END FUNCTION SNRM

SUBROUTINE S1NRM (A, IA, JA, M, N, ANORM, WK)
IMPLICIT NONE
INTENT(IN) A, IA, JA, M, N
INTENT(OUT) ANORM
INTENT(INOUT) WK
INTEGER M, N
REAL ANORM
INTEGER IP, IPMAX, IPMIN, J
!-----------------------------------------------------------------------
!        COMPUTATION OF THE L1 NORM OF A REAL SPARSE MATRIX A
!-----------------------------------------------------------------------
REAL A(*), WK(N)
INTEGER IA(*), JA(*)
!
ANORM = 0.0
IPMIN = IA(1)
IPMAX = IA(M + 1) - 1
IF (IPMIN .GT. IPMAX) RETURN
!
!     COMPUTE THE L1 NORM OF A
!
DO J = 1,N
   WK(J) = 0.0
END DO
!
DO IP = IPMIN,IPMAX
   J = JA(IP)
   WK(J) = WK(J) + ABS(A(IP))
END DO
!
DO J = 1,N
   ANORM = AMAX1(ANORM,WK(J))
END DO
RETURN
END SUBROUTINE S1NRM

double precision function DSNRM (A, IA, JA, M, N)
IMPLICIT NONE
INTENT(IN) A, IA, JA, M, N
INTEGER M, N
INTEGER I, IP, IPMAX, IPMIN
!-----------------------------------------------------------------------
!             COMPUTATION OF THE L-INFINITY NORM OF A
!                DOUBLE PRECISION SPARSE MATRIX A
!-----------------------------------------------------------------------
DOUBLE PRECISION A(*), SUM
INTEGER IA(*), JA(*)
!
DSNRM = 0.D0
do 20 I = 1,M
   IPMIN = IA(I)
   IPMAX = IA(I + 1) - 1
   IF (IPMIN .GT. IPMAX) GO TO 20
   SUM = 0.D0
   DO IP = IPMIN,IPMAX
      SUM = SUM + DABS(A(IP))
   END DO
   DSNRM = DMAX1(DSNRM, SUM)
20 CONTINUE
RETURN
END FUNCTION DSNRM

SUBROUTINE DS1NRM (A, IA, JA, M, N, ANORM, WK)
IMPLICIT NONE
INTENT(IN) A, IA, JA, M, N
INTENT(OUT) ANORM
INTENT(INOUT) WK
INTEGER M, N
INTEGER IP, IPMAX, IPMIN, J
!-----------------------------------------------------------------------
!               COMPUTATION OF THE L1 NORM OF A SPARSE
!                     DOUBLE PRECISION MATRIX A
!-----------------------------------------------------------------------
DOUBLE PRECISION A(*), ANORM, WK(N)
INTEGER IA(*), JA(*)
!
ANORM = 0.D0
IPMIN = IA(1)
IPMAX = IA(M + 1) - 1
IF (IPMIN .GT. IPMAX) RETURN
!
!     COMPUTE THE L1 NORM OF A
!
DO J = 1,N
   WK(J) = 0.D0
END DO
!
DO IP = IPMIN,IPMAX
   J = JA(IP)
   WK(J) = WK(J) + DABS(A(IP))
END DO
!
DO J = 1,N
   ANORM = DMAX1(ANORM,WK(J))
END DO
RETURN
END SUBROUTINE DS1NRM

SUBROUTINE SPORD (M, N, IA, R, IWK)
IMPLICIT NONE
INTENT(IN) IA, M, N
INTENT(INOUT) IWK, R
INTEGER M, N
INTEGER I, II, K, L, NP1, NUM
!-----------------------------------------------------------------------
!        SPORD ORDERS THE ROWS OF AN MXN SPARSE MATRIX A,IA,JA
!        BY INCREASING LENGTH. THE ROW ORDERING IS GIVEN IN R.
!-----------------------------------------------------------------------
!     IWK IS A WORK SPACE OF DIMENSION M + N + 1.
!----------------------
INTEGER IA(*), R(M), IWK(*)
!
NP1 = N + 1
DO I = 1,NP1
   IWK(I) = 0
END DO
!
I = M
DO II = 1,M
   NUM = IA(I+1) - IA(I) + 1
   L = NP1 + I
   IWK(L) = IWK(NUM)
   IWK(NUM) = I
   I = I - 1
END DO
!
NUM = 1
K = IWK(NUM)
DO I = 1,M
30 IF (K .NE. 0) GO TO 31
      NUM = NUM + 1
      K = IWK(NUM)
      GO TO 30
31 R(I) = K
   L = NP1 + K
   K = IWK(L)
END DO
RETURN
END SUBROUTINE SPORD

SUBROUTINE BLKORD (N, IA, JA, R, C, IB, NUM, IWK, IERR)
IMPLICIT NONE
INTENT(IN) IA, JA
INTENT(INOUT) C, IB, IERR, IWK, NUM, R
INTEGER IERR, N, NUM
INTEGER I, LENGTH, LI, NP1, NPI
!-----------------------------------------------------------------------
!        REORDERING A SPARSE MATRIX INTO BLOCK TRIANGULAR FORM
!-----------------------------------------------------------------------
INTEGER IA(*), JA(*), R(N), C(N), IB(N)
!     INTEGER IWK(5*N)
INTEGER IWK(*)
!
NP1 = N + 1
LENGTH = IA(NP1) - IA(1)
DO I = 1,N
   IWK(I) = IA(I+1) - IA(I)
END DO
CALL MC21A(N,JA,LENGTH,IA,IWK(1),R,NUM,IWK(NP1))
IERR = N - NUM
IF (IERR .NE. 0) RETURN
!
DO I = 1,N
   LI = R(I)
   IWK(I) = IA(LI)
   NPI = N + I
   IWK(NPI) = IA(LI+1) - IA(LI)
END DO
CALL MC13D(N,JA,LENGTH,IWK(1),IWK(NP1),C,IB,NUM,IWK(2*N+1))
!
DO I = 1,N
   LI = C(I)
   IWK(I) = R(LI)
END DO
DO I = 1,N
   R(I) = IWK(I)
END DO
RETURN
END SUBROUTINE BLKORD

SUBROUTINE MC21A (N,ICN,LICN,IP,LENR,IPERM,NUMNZ,IW)
IMPLICIT NONE
INTENT(IN) ICN, IP, LENR, LICN, N
INTENT(INOUT) IPERM, IW, NUMNZ
INTEGER LICN, N, NUMNZ
!-----------------------------------------------------------------------
! DESCRIPTION OF PARAMETERS.
! INPUT VARIABLES   N,ICN,LICN,IP,LENR
! OUTPUT VARIABLES  IPERM,NUMNZ
!
! N   ORDER OF MATRIX.
! ICN ARRAY CONTAINING THE COLUMN INDICES OF THE NON-ZEROS.  THOSE
!     BELONGING TO A SINGLE ROW MUST BE CONTIGUOUS BUT THE ORDERING
!     OF COLUMN INDICES WITHIN EACH ROW IS UNIMPORTANT AND WASTED
!     SPACE BETWEEN ROWS IS PERMITTED.
! LICN  LENGTH OF ARRAY ICN.
! IP  IP(I), I=1,2,...N, IS THE POSITION IN ARRAY ICN OF THE FIRST
!     COLUMN INDEX OF A NON-ZERO IN ROW I.
! LENR  LENR(I) IS THE NUMBER OF NON-ZEROS IN ROW I, I=1,2,..N.
! IPERM CONTAINS PERMUTATION TO MAKE DIAGONAL HAVE THE SMALLEST
!     NUMBER OF ZEROS ON IT.  ELEMENTS (IPERM(I),I) I=1, ... N ARE
!     NON-ZERO AT THE END OF THE ALGORITHM UNLESS MATRIX
!     IS STRUCTURALLY SINGULAR.  IN THIS CASE, (IPERM(I),I) WILL
!     BE ZERO FOR N-NUMNZ ENTRIES.
! NUMNZ NUMBER OF NON-ZEROS ON DIAGONAL OF PERMUTED MATRIX.
! IW  WORK ARRAY  ..  SEE LATER COMMENTS.
!-----------------------------------------------------------------------
INTEGER IP(N)
INTEGER ICN(LICN), LENR(N), IPERM(N), IW(N,4)
!
CALL MC21B (N,ICN,LICN,IP,LENR,IPERM,NUMNZ,IW(1,1),IW(1,2), &
&IW(1,3),IW(1,4))
RETURN
END SUBROUTINE MC21A

SUBROUTINE MC21B (N,ICN,LICN,IP,LENR,IPERM,NUMNZ,PR,ARP,CV,OUT)
IMPLICIT NONE
INTENT(IN) ICN, IP, LENR, LICN, N
INTENT(INOUT) ARP, CV, IPERM, NUMNZ, OUT, PR
INTEGER LICN, N, NUMNZ
INTEGER I, II, IN1, IN2, IOUTK, J, J1, JORD, K, KK
!-----------------------------------------------------------------------
!     DIVISION OF WORK ARRAY IS NOW DESCRIBED.
!
! PR(I) IS THE PREVIOUS ROW TO I IN THE DEPTH FIRST SEARCH.
! ARP(I) IS ONE LESS THAN THE NUMBER OF NON-ZEROS IN ROW I
!     WHICH HAVE NOT BEEN SCANNED WHEN LOOKING FOR A CHEAP ASSIGNMENT.
! CV(I) IS THE MOST RECENT ROW EXTENSION AT WHICH COLUMN I
!     WAS VISITED.
! OUT(I) IS ONE LESS THAN THE NUMBER OF NON-ZEROS IN ROW I
!     WHICH HAVE NOT BEEN SCANNED DURING ONE PASS THROUGH THE
!     MAIN LOOP.
!-----------------------------------------------------------------------
INTEGER IP(N), ICN(LICN), LENR(N), IPERM(N), PR(N), CV(N), &
&ARP(N), OUT(N)
!
!     INITIALIZATION OF ARRAYS
!
DO I = 1,N
   ARP(I) = LENR(I) - 1
   CV(I) = 0
   IPERM(I) = 0
END DO
NUMNZ = 0
!
!     MAIN LOOP.
!     EACH PASS ROUND THIS LOOP EITHER RESULTS IN A NEW ASSIGNMENT
!     OR GIVES A ROW WITH NO ASSIGNMENT.
!
do 130 JORD = 1,N
J = JORD
PR(J) = -1
do 100 K = 1,JORD
!
!     LOOK FOR A CHEAP ASSIGNMENT
!
IN1 = ARP(J)
IF (IN1 .LT. 0) GO TO 60
IN2 = IP(J) + LENR(J) - 1
IN1 = IN2 - IN1
DO II = IN1,IN2
   I = ICN(II)
   IF (IPERM(I) .EQ. 0) GO TO 110
END DO
!
!     NO CHEAP ASSIGNMENT IN ROW
!
ARP(J) = -1
!
!     BEGIN LOOKING FOR ASSIGNMENT CHAIN STARTING WITH ROW J
!
60 OUT(J) = LENR(J) - 1
!
!     INNER LOOP.  EXTENDS CHAIN BY ONE OR BACKTRACKS.
!
DO KK = 1,JORD
   IN1 = OUT(J)
   IF (IN1 .LT. 0) GO TO 80
   IN2 = IP(J) + LENR(J) - 1
   IN1 = IN2 - IN1
!
!        FORWARD SCAN
!
   do 70 II = IN1,IN2
      I = ICN(II)
      IF (CV(I) .EQ. JORD) GO TO 70
!
!           COLUMN I HAS NOT YET BEEN ACCESSED DURING THIS PASS
!
      J1 = J
      J = IPERM(I)
      CV(I) = JORD
      PR(J) = J1
      OUT(J1) = IN2 - II - 1
      GO TO 100
70 CONTINUE
!
!        BACKTRACKING STEP
!
80 J = PR(J)
   IF (J .EQ. -1) GO TO 130
END DO
!
100 CONTINUE
!
!     NEW ASSIGNMENT IS MADE
!
110 IPERM(I) = J
ARP(J) = IN2 - II - 1
NUMNZ = NUMNZ + 1
DO K = 1,JORD
   J = PR(J)
   IF (J .EQ. -1) GO TO 130
   II = IP(J) + LENR(J) - OUT(J) - 2
   I = ICN(II)
   IPERM(I) = J
END DO
!
130 CONTINUE
!
!     IF MATRIX IS STRUCTURALLY SINGULAR, WE NOW COMPLETE THE
!     PERMUTATION IPERM.
!
IF (NUMNZ .EQ. N) GO TO 500
DO I = 1,N
   ARP(I) = 0
END DO
K = 0
do 160 I = 1,N
   IF (IPERM(I) .NE. 0) GO TO 150
      K = K + 1
      OUT(K) = I
      GO TO 160
150 J = IPERM(I)
   ARP(J) = I
160 CONTINUE
K = 0
do 170 I = 1,N
   IF (ARP(I) .NE. 0) GO TO 170
   K = K + 1
   IOUTK = OUT(K)
   IPERM(IOUTK) = I
170 CONTINUE
500 RETURN
END SUBROUTINE MC21B

SUBROUTINE MC13D(N, ICN, LICN, IP, LENR, IOR, IB, NUM, IW)
IMPLICIT NONE
INTENT(IN) ICN, IP, LENR, LICN, N
INTENT(INOUT) IB, IOR, IW, NUM
INTEGER LICN, N, NUM
!
! DESCRIPTION OF PARAMETERS.
! INPUT VARIABLES  .... N,ICN,LICN,IP,LENR.
! OUTPUT VARIABLES  IOR,IB,NUM.
!
! N   ORDER OF THE MATRIX.
! ICN ARRAY CONTAINING THE COLUMN INDICES OF THE NON-ZEROS.  THOSE
!     BELONGING TO A SINGLE ROW MUST BE CONTIGUOUS BUT THE ORDERING
!     OF COLUMN INDICES WITHIN EACH ROW IS UNIMPORTANT AND WASTED
!     SPACE BETWEEN ROWS IS PERMITTED.
! LICN  LENGTH OF ARRAY ICN.
! IP  IP(I), I=1,2,...N, IS THE POSITION IN ARRAY ICN OF THE FIRST
!     COLUMN INDEX OF A NON-ZERO IN ROW I.
! LENR  LENR(I) IS THE NUMBER OF NON-ZEROS IN ROW I, I=1,2,...N.
! IOR  IOR(I) GIVES THE POSITION IN THE ORIGINAL ORDERING OF THE ROW
!     OR COLUMN WHICH IS IN POSITION I IN THE PERMUTED FORM, I=1,2,..N.
! IB  IB(I) IS THE ROW NUMBER IN THE PERMUTED MATRIX OF THE BEGINNING
!     OF BLOCK I, I=1,2,...NUM.
! NUM NUMBER OF BLOCKS FOUND.
! IW  WORK ARRAY OF LENGTH 3*N.
!
INTEGER IP(N)
INTEGER ICN(LICN), LENR(N), IOR(N), IB(N), IW(N,3)
!
CALL MC13E(N, ICN, LICN, IP, LENR, IOR, IB, NUM, IW(1,1), &
&IW(1,2), IW(1,3))
RETURN
END SUBROUTINE MC13D

SUBROUTINE MC13E(N, ICN, LICN, IP, LENR, ARP, IB, NUM, LOWL, &
&NUMB, PREV)
IMPLICIT NONE
INTENT(IN) ICN, IP, LENR, LICN, N
INTENT(OUT) NUM
INTENT(INOUT) ARP, IB, LOWL, NUMB, PREV
INTEGER LICN, N, NUM
INTEGER I, I1, I2, ICNT, II, ISN, IST, IST1, IV, IW, J, K, LCNT &
&, NNM1
INTEGER STP, DUMMY
INTEGER IP(N)
!
! ARP(I) IS ONE LESS THAN THE NUMBER OF UNSEARCHED EDGES LEAVING
!     NODE I.  AT THE END OF THE ALGORITHM IT IS SET TO A
!     PERMUTATION WHICH PUTS THE MATRIX IN BLOCK LOWER
!     TRIANGULAR FORM.
! IB(I) IS THE POSITION IN THE ORDERING OF THE START OF THE ITH
!     BLOCK.  IB(N+1-I) HOLDS THE NODE NUMBER OF THE ITH NODE
!     ON THE STACK.
! LOWL(I) IS THE SMALLEST STACK POSITION OF ANY NODE TO WHICH A PATH
!     FROM NODE I HAS BEEN FOUND.  IT IS SET TO N+1 WHEN NODE I
!     IS REMOVED FROM THE STACK.
! NUMB(I) IS THE POSITION OF NODE I IN THE STACK IF IT IS ON
!     IT, IS THE PERMUTED ORDER OF NODE I FOR THOSE NODES
!     WHOSE FINAL POSITION HAS BEEN FOUND AND IS OTHERWISE ZERO.
! PREV(I) IS THE NODE AT THE END OF THE PATH WHEN NODE I WAS
!     PLACED ON THE STACK.
!
INTEGER ICN(LICN), LENR(N), ARP(N), IB(N), LOWL(N), NUMB(N), &
&PREV(N)
!
!   ICNT IS THE NUMBER OF NODES WHOSE POSITIONS IN FINAL ORDERING HAVE
!     BEEN FOUND.
!
ICNT = 0
! NUM IS THE NUMBER OF BLOCKS THAT HAVE BEEN FOUND.
NUM = 0
NNM1 = N + N - 1
!
! INITIALIZATION OF ARRAYS.
!
DO J=1,N
  NUMB(J) = 0
  ARP(J) = LENR(J) - 1
END DO
!
!
do 90 ISN = 1,N
! LOOK FOR A STARTING NODE
  IF (NUMB(ISN).NE.0) GO TO 90
  IV = ISN
! IST IS THE NUMBER OF NODES ON THE STACK ... IT IS THE STACK POINTER.
  IST = 1
! PUT NODE IV AT BEGINNING OF STACK.
  LOWL(IV) = 1
  NUMB(IV) = 1
  IB(N) = IV
!
! THE BODY OF THIS LOOP PUTS A NEW NODE ON THE STACK OR BACKTRACKS.
!
  do 80 DUMMY = 1,NNM1
    I1 = ARP(IV)
! HAVE ALL EDGES LEAVING NODE IV BEEN SEARCHED.
    IF (I1.LT.0) GO TO 30
    I2 = IP(IV) + LENR(IV) - 1
    I1 = I2 - I1
!
! LOOK AT EDGES LEAVING NODE IV UNTIL ONE ENTERS A NEW NODE OR
!     ALL EDGES ARE EXHAUSTED.
!
    DO II=I1,I2
      IW = ICN(II)
! HAS NODE IW BEEN ON STACK ALREADY.
      IF (NUMB(IW).EQ.0) GO TO 70
! UPDATE VALUE OF LOWL(IV) IF NECESSARY.
      IF (LOWL(IW).LT.LOWL(IV)) LOWL(IV) = LOWL(IW)
    END DO
!
! THERE ARE NO MORE EDGES LEAVING NODE IV.
!
    ARP(IV) = -1
! IS NODE IV THE ROOT OF A BLOCK.
30 IF (LOWL(IV).LT.NUMB(IV)) GO TO 60
!
! ORDER NODES IN A BLOCK.
!
    NUM = NUM + 1
    IST1 = N + 1 - IST
    LCNT = ICNT + 1
!
! PEEL BLOCK OFF THE TOP OF THE STACK STARTING AT THE TOP AND
!     WORKING DOWN TO THE ROOT OF THE BLOCK.
!
    DO STP=IST1,N
      IW = IB(STP)
      LOWL(IW) = N + 1
      ICNT = ICNT + 1
      NUMB(IW) = ICNT
      IF (IW.EQ.IV) GO TO 50
    END DO
50 IST = N - STP
    IB(NUM) = LCNT
! ARE THERE ANY NODES LEFT ON THE STACK.
    IF (IST.NE.0) GO TO 60
! HAVE ALL THE NODES BEEN ORDERED.
    IF (ICNT.LT.N) GO TO 90
    GO TO 100
!
! BACKTRACK TO PREVIOUS NODE ON PATH.
!
60 IW = IV
    IV = PREV(IV)
! UPDATE VALUE OF LOWL(IV) IF NECESSARY.
    IF (LOWL(IW).LT.LOWL(IV)) LOWL(IV) = LOWL(IW)
    GO TO 80
!
! PUT NEW NODE ON THE STACK.
!
70 ARP(IV) = I2 - II - 1
    PREV(IW) = IV
    IV = IW
    IST = IST + 1
    LOWL(IV) = IST
    NUMB(IV) = IST
    K = N + 1 - IST
    IB(K) = IV
80 CONTINUE
!
90 CONTINUE
!
! PUT PERMUTATION IN THE REQUIRED FORM.
!
100 DO I=1,N
  II = NUMB(I)
  ARP(II) = I
END DO
RETURN
END SUBROUTINE MC13E

SUBROUTINE SPSLV (N,A,IA,JA,B,R,C,MAX,X,ITEMP,RTEMP,IERR)
IMPLICIT NONE
INTENT(IN) A, B, IA, JA, MAX, N, R
INTENT(OUT) IERR
INTENT(INOUT) C, ITEMP, RTEMP, X
INTEGER IERR, MAX, N
INTEGER K, L
!-----------------------------------------------------------------------
!                 SOLUTION OF REAL SPARSE EQUATIONS
!-----------------------------------------------------------------------
!  SPSLV CALLS NSPIV1 WHICH USES SPARSE GAUSSIAN ELIMINATION WITH
!  COLUMN INTERCHANGES TO SOLVE THE LINEAR SYSTEM A X = B.  THE
!  ELIMINATION PHASE PERFORMS ROW OPERATIONS ON A AND B TO OBTAIN
!  A UNIT UPPER TRIANGULAR MATRIX U AND A VECTOR Y.  THE SOLUTION
!  PHASE SOLVES U X = Y.
!
!  INPUT ARGUMENTS---
!
!  N      INTEGER NUMBER OF EQUATIONS AND UNKNOWNS
!
!  A      REAL ARRAY WITH ONE ENTRY PER NONZERO IN A, CONTAINING THE
!         ACTUAL NONZEROS.  (SEE MATRIX STORAGE DESCRIPTION BELOW)
!
!  IA     INTEGER ARRAY OF N+1 ENTRIES CONTAINING ROW POINTERS TO A
!         (SEE MATRIX STORAGE DESCRIPTION BELOW)
!
!  JA     INTEGER ARRAY WITH ONE ENTRY PER NONZERO IN A, CONTAINING
!         COLUMN NUMBERS OF THE NONZEROS OF A.  (SEE MATRIX STORAGE
!         DESCRIPTION BELOW)
!
!  B      REAL ARRAY OF N ENTRIES CONTAINING RIGHT HAND SIDE DATA
!
!  R      INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF THE
!         ROWS OF A (I.E., THE ELIMINATION ORDER FOR THE EQUATIONS)
!
!  C      INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF THE
!         COLUMNS OF A.  C IS ALSO AN OUTPUT ARGUMENT
!
!  MAX    INTEGER NUMBER SPECIFYING MAXIMUM NUMBER OF OFF-DIAGONAL
!         NONZERO ENTRIES OF U WHICH MAY BE STORED
!
!  ITEMP  INTEGER ARRAY OF 3*N + MAX + 2 ENTRIES, FOR INTERNAL USE
!
!  RTEMP  REAL ARRAY OF N + MAX ENTRIES FOR INTERNAL USE
!
!
!  OUTPUT ARGUMENTS---
!
!  C      INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF THE
!         COLUMNS OF U.  C IS ALSO AN INPUT ARGUMENT
!
!  X      REAL ARRAY OF N ENTRIES CONTAINING THE SOLUTION VECTOR
!
!  IERR   INTEGER NUMBER WHICH INDICATES ERROR CONDITIONS OR
!         THE ACTUAL NUMBER OF OFF-DIAGONAL ENTRIES IN U (FOR
!         SUCCESSFUL COMPLETION)
!
!         IERR VALUES ARE---
!
!         0 LT IERR             SUCCESSFUL COMPLETION. IERR=MAX(1,M)
!                               WHERE M IS THE NUMBER OF OFF-DIAGONAL
!                               NONZERO ENTRIES OF U.
!
!         IERR = 0              ERROR.  N IS LESS THAN OR EQUAL TO 0
!
!         -N LE IERR LT 0       ERROR.  ROW NUMBER IABS(IERR) OF A IS
!                               IS NULL
!
!         -2*N LE IERR LT -N    ERROR.  ROW NUMBER IABS(IERR+N) HAS A
!                               DUPLICATE ENTRY
!
!         -3*N LE IERR LT -2*N  ERROR.  ROW NUMBER IABS(IERR+2*N)
!                               HAS A ZERO PIVOT
!
!         -4*N LE IERR LT -3*N  ERROR.  ROW NUMBER IABS(IERR+3*N)
!                               EXCEEDS STORAGE
!
!
!  STORAGE OF SPARSE MATRICES---
!
!  THE SPARSE MATRIX A IS STORED USING THREE ARRAYS IA, JA, AND A.
!  THE ARRAY A CONTAINS THE NONZEROS OF THE MATRIX ROW-BY-ROW, NOT
!  NECESSARILY IN ORDER OF INCREASING COLUMN NUMBER.  THE ARRAY JA
!  CONTAINS THE COLUMN NUMBERS CORRESPONDING TO THE NONZEROS STORED
!  IN THE ARRAY A (I.E., IF THE NONZERO STORED IN A(K) IS IN
!  COLUMN J, THEN JA(K) = J).  THE ARRAY IA CONTAINS POINTERS TO THE
!  ROWS OF NONZEROS/COLUMN INDICES IN THE ARRAY A/JA (I.E.,
!  A(IA(I))/JA(IA(I)) IS THE FIRST ENTRY FOR ROW I IN THE ARRAY A/JA).
!  IA(N+1) IS SET SO THAT IA(N+1) - IA(1) = THE NUMBER OF NONZERO
!  ELEMENTS IN A.
!------------------------
REAL A(*), B(N), X(N), RTEMP(*)
INTEGER IA(*), JA(*), R(N), C(N), ITEMP(*)
INTEGER IU, JU, U, Y, P
!
IERR = 0
IF (N .LE. 0) RETURN
!
!  SET INDICES TO DIVIDE TEMPORARY STORAGE FOR NSPIV1
!
Y = 1
U = Y + N
P = N + 1
IU = P + N + 1
JU = IU + N + 1
!
!  COMPUTE THE INVERSE PERMUTATION OF C
!
DO K = 1,N
   L = C(K)
   ITEMP(L) = K
END DO
!
!  CALL NSPIV1 TO PERFORM COMPUTATIONS
!
CALL NSPIV1 (N,IA,JA,A,B,MAX,R,C,ITEMP(1),X,RTEMP(Y),ITEMP(P), &
&ITEMP(IU),ITEMP(JU),RTEMP(U),IERR)
IF (IERR .EQ. 0) IERR = 1
RETURN
END SUBROUTINE SPSLV

SUBROUTINE NSPIV1 (N,IA,JA,A,B,MAX,R,C,IC,X,Y,P,IU,JU,U,IERR)
IMPLICIT NONE
INTENT(IN) A, B, IA, JA, MAX, N, R
INTENT(INOUT) C, IC, IERR, IU, JU, P, U, X, Y
INTEGER IERR, MAX, N
INTEGER I, J, JAJ, JMAX, JMIN, JUJ, JUPTR, K, MAXC, MAXCL, NZCNT
!
!
!  NSPIV1 USES SPARSE GAUSSIAN ELIMINATION WITH
!  COLUMN INTERCHANGES TO SOLVE THE LINEAR SYSTEM A X = B.  THE
!  ELIMINATION PHASE PERFORMS ROW OPERATIONS ON A AND B TO OBTAIN
!  A UNIT UPPER TRIANGULAR MATRIX U AND A VECTOR Y.  THE SOLUTION
!  PHASE SOLVES U X = Y.
!
!
!  SEE SPSLV FOR DESCRIPTIONS OF ALL INPUT AND OUTPUT ARGUMENTS
!  OTHER THAN THOSE DESCRIBED BELOW
!
!  IC  INTEGER ARRAY OF N ENTRIES WHICH IS THE INVERSE OF C
!      (I.E., IC(C(I)) = I). IC IS BOTH AN INPUT AND OUTPUT
!      ARGUMENT.
!
!  INPUT ARGUMENTS (USED INTERNALLY ONLY)---
!
!  Y   REAL ARRAY OF N ENTRIES USED TO COMPUTE THE UPDATED
!      RIGHT HAND SIDE
!
!  P   INTEGER ARRAY OF N+1 ENTRIES USED FOR A LINKED LIST.
!      P(N+1) IS THE LIST HEADER, AND THE ENTRY FOLLOWING
!      P(K) IS IN P(P(K)).  THUS, P(N+1) IS THE FIRST DATA
!      ITEM, P(P(N+1)) IS THE SECOND, ETC.  A POINTER OF
!      N+1 MARKS THE END OF THE LIST
!
!  IU  INTEGER ARRAY OF N+1 ENTRIES USED FOR ROW POINTERS TO U
!      (SEE MATRIX STORAGE DESCRIPTION BELOW)
!
!  JU  INTEGER ARRAY OF MAX ENTRIES USED FOR COLUMN NUMBERS OF
!      THE NONZEROS IN THE STRICT UPPER TRIANGLE OF U.  (SEE
!      MATRIX STORAGE DESCRIPTION BELOW)
!
!  U   REAL ARRAY OF MAX ENTRIES USED FOR THE ACTUAL NONZEROS IN
!      THE STRICT UPPER TRIANGLE OF U.  (SEE MATRIX STORAGE
!      DESCRIPTION BELOW)
!
!
!  STORAGE OF SPARSE MATRICES---
!
!  THE SPARSE MATRIX A IS STORED USING THREE ARRAYS IA, JA, AND A.
!  THE ARRAY A CONTAINS THE NONZEROS OF THE MATRIX ROW-BY-ROW, NOT
!  NECESSARILY IN ORDER OF INCREASING COLUMN NUMBER.  THE ARRAY JA
!  CONTAINS THE COLUMN NUMBERS CORRESPONDING TO THE NONZEROS STORED
!  IN THE ARRAY A (I.E., IF THE NONZERO STORED IN A(K) IS IN
!  COLUMN J, THEN JA(K) = J).  THE ARRAY IA CONTAINS POINTERS TO THE
!  ROWS OF NONZEROS/COLUMN INDICES IN THE ARRAY A/JA (I.E.,
!  A(IA(I))/JA(IA(I)) IS THE FIRST ENTRY FOR ROW I IN THE ARRAY A/JA).
!  IA(N+1) IS SET SO THAT IA(N+1) - IA(1) = THE NUMBER OF NONZEROS IN
!  A.  IU, JU, AND U ARE USED IN A SIMILAR WAY TO STORE THE STRICT UPPER
!  TRIANGLE OF U, EXCEPT THAT JU ACTUALLY CONTAINS C(J) INSTEAD OF J
!
!
REAL A(*), B(N), U(MAX), X(N), Y(N)
REAL DK, LKI, XPV, XPVMAX, YK
INTEGER C(N), IA(*), IC(N), IU(*), JA(*), JU(MAX), P(*), R(N)
INTEGER CK, PK, PPK, PV, V, VI, VJ, VK
!
!  INITIALIZE WORK STORAGE AND POINTERS TO JU
!
DO J = 1,N
  X(J) = 0.0
END DO
IU(1) = 1
JUPTR = 0
!
!  PERFORM SYMBOLIC AND NUMERIC FACTORIZATION ROW BY ROW
!  VK (VI,VJ) IS THE GRAPH VERTEX FOR ROW K (I,J) OF U
!
do 170 K = 1,N
!
!  INITIALIZE LINKED LIST AND FREE STORAGE FOR THIS ROW
!  THE R(K)-TH ROW OF A BECOMES THE K-TH ROW OF U.
!
  P(N+1) = N+1
  VK = R(K)
!
!  SET UP ADJACENCY LIST FOR VK, ORDERED IN
!  CURRENT COLUMN ORDER OF U.  THE LOOP INDEX
!  GOES DOWNWARD TO EXPLOIT ANY COLUMNS
!  FROM A IN CORRECT RELATIVE ORDER
!
  JMIN = IA(VK)
  JMAX = IA(VK+1) - 1
  IF (JMIN .GT. JMAX)  GO TO 1002
  J = JMAX
20 JAJ = JA(J)
    VJ = IC(JAJ)
!
!  STORE A(K,J) IN WORK VECTOR
!
    X(VJ) = A(J)
!  THIS CODE INSERTS VJ INTO ADJACENCY LIST OF VK
    PPK = N+1
30 PK = PPK
    PPK = P(PK)
    IF (PPK - VJ)  30,1003,40
40 P(VJ) = PPK
    P(PK) = VJ
    J = J - 1
    IF (J .GE. JMIN) GO TO 20
!
!  THE FOLLOWING CODE COMPUTES THE K-TH ROW OF U
!
  VI = N+1
  YK = B(VK)
50 VI = P(VI)
  IF (VI .GE. K) GO TO 110
!
!  VI LT VK -- PROCESS THE L(K,I) ELEMENT AND MERGE THE
!  ADJACENCY OF VI WITH THE ORDERED ADJACENCY OF VK
!
  LKI = - X(VI)
  X(VI) = 0.0
!
!  ADJUST RIGHT HAND SIDE TO REFLECT ELIMINATION
!
  YK = YK + LKI * Y(VI)
  PPK = VI
  JMIN = IU(VI)
  JMAX = IU(VI+1) - 1
  IF (JMIN .GT. JMAX)  GO TO 50
  DO J = JMIN,JMAX
    JUJ = JU(J)
    VJ = IC(JUJ)
!
!  IF VJ IS ALREADY IN THE ADJACENCY OF VK,
!  SKIP THE INSERTION
!
    IF (X(VJ) .NE. 0.0)  GO TO 90
!
!  INSERT VJ IN ADJACENCY LIST OF VK.
!  RESET PPK TO VI IF WE HAVE PASSED THE CORRECT
!  INSERTION SPOT.  (THIS HAPPENS WHEN THE ADJACENCY OF
!  VI IS NOT IN CURRENT COLUMN ORDER DUE TO PIVOTING.)
!
    IF (VJ - PPK) 60,90,70
60 PPK = VI
70 PK = PPK
    PPK = P(PK)
    IF (PPK - VJ)  70,90,80
80 P(VJ) = PPK
    P(PK) = VJ
    PPK = VJ
!
!  COMPUTE L(K,J) = L(K,J) - L(K,I)*U(I,J) FOR L(K,I) NONZERO
!  COMPUTE U*(K,J) = U*(K,J) - L(K,I)*U(I,J) FOR U(K,J) NONZERO
!  (U*(K,J) = U(K,J)*D(K,K))
!
90 X(VJ) = X(VJ) + LKI * U(J)
  END DO
  GO TO 50
!
!  PIVOT--INTERCHANGE LARGEST ENTRY OF K-TH ROW OF U WITH
!  THE DIAGONAL ENTRY.
!
!  FIND LARGEST ENTRY, COUNTING OFF-DIAGONAL NONZEROS
!
110 IF (VI .GT. N) GO TO 1004
  XPVMAX = ABS(X(VI))
  MAXC = VI
  NZCNT = 0
  PV = VI
120 V = PV
    PV = P(PV)
    IF (PV .GT. N) GO TO 130
    NZCNT = NZCNT + 1
    XPV = ABS(X(PV))
    IF (XPV .LE. XPVMAX) GO TO 120
    XPVMAX = XPV
    MAXC = PV
    MAXCL = V
    GO TO 120
130 IF (XPVMAX .EQ. 0.0) GO TO 1004
!
!  IF VI = K, THEN THERE IS AN ENTRY FOR DIAGONAL
!  WHICH MUST BE DELETED.  OTHERWISE, DELETE THE
!  ENTRY WHICH WILL BECOME THE DIAGONAL ENTRY
!
  IF (VI .EQ. K) GO TO 140
  IF (VI .EQ. MAXC) GO TO 140
  P(MAXCL) = P(MAXC)
  GO TO 150
140 VI = P(VI)
!
!  COMPUTE D(K) = 1/L(K,K) AND PERFORM INTERCHANGE.
!
150 DK = 1.0 / X(MAXC)
  X(MAXC) = X(K)
  I = C(K)
  C(K) = C(MAXC)
  C(MAXC) = I
  CK = C(K)
  IC(CK) = K
  IC(I) = MAXC
  X(K) = 0.0
!
!  UPDATE RIGHT HAND SIDE.
!
  Y(K) = YK * DK
!
!  COMPUTE VALUE FOR IU(K+1) AND CHECK FOR STORAGE OVERFLOW
!
  IU(K+1) = IU(K) + NZCNT
  IF (IU(K+1) .GT. MAX+1) GO TO 1005
!
!  MOVE COLUMN INDICES FROM LINKED LIST TO JU.
!  COLUMNS ARE STORED IN CURRENT ORDER WITH ORIGINAL
!  COLUMN NUMBER (C(J)) STORED FOR CURRENT COLUMN J
!
  IF (VI .GT. N)  GO TO 170
  J = VI
160 JUPTR = JUPTR + 1
    JU(JUPTR) = C(J)
    U(JUPTR) = X(J) * DK
    X(J) = 0.0
    J = P(J)
    IF (J .LE. N) GO TO 160
170 CONTINUE
!
!  BACKSOLVE U X = Y, AND REORDER X TO CORRESPOND WITH A
!
K = N
DO I = 1,N
  YK = Y(K)
  JMIN = IU(K)
  JMAX = IU(K+1) - 1
  IF (JMIN .GT. JMAX)  GO TO 190
  DO J = JMIN,JMAX
    JUJ = JU(J)
    JUJ = IC(JUJ)
    YK = YK - U(J) * Y(JUJ)
  END DO
190 Y(K) = YK
  CK = C(K)
  X(CK) = YK
  K = K - 1
END DO
!
!  RETURN WITH IERR = NUMBER OF OFF-DIAGONAL NONZEROS IN U
!
IERR = IU(N+1) - IU(1)
RETURN
!
!  ERROR RETURNS
!
!  ROW K OF A IS NULL
!
1002 IERR = -K
RETURN
!
!  ROW K OF A HAS A DUPLICATE ENTRY
!
1003 IERR = -(N+K)
RETURN
!
!  ZERO PIVOT IN ROW K
!
1004 IERR = -(2*N+K)
RETURN
!
!  STORAGE FOR U EXCEEDED ON ROW K
!
1005 IERR = -(3*N+K)
RETURN
END SUBROUTINE NSPIV1

SUBROUTINE RSLV (M0,N,A,IA,JA,B,R,C,MAX,X,IWK,WK,IERR)
IMPLICIT NONE
INTENT(IN) A, B, IA, JA, M0, MAX, N, R
INTENT(INOUT) C, IERR, IWK, WK, X
INTEGER IERR, M0, MAX, N
INTEGER IT, IU, JT, K, L
!-----------------------------------------------------------------------
!                 SOLUTION OF REAL SPARSE EQUATIONS
!-----------------------------------------------------------------------
!     RSLV EMPLOYS GAUSSIAN ELIMINATION WITH COLUMN INTERCHANGES TO
!     SOLVE THE NXN LINEAR SYSTEM AX = B. THE ARGUMENT M0 SPECIFIES
!     IF RSLV IS BEING CALLED FOR THE FIRST TIME, OR IF IT IS BEING
!     RECALLED WHERE A IS THE SAME MATRIX BUT B HAS BEEN MODIFIED.
!     ON AN INITIAL CALL TO THE ROUTINE (WHEN M0=0) THE LU DECOMPO-
!     SITION OF A IS OBTAINED WHERE U IS A UNIT UPPER TRIANGULAR
!     MATRIX. THEN THE EQUATIONS ARE SOLVED. ON SUBSEQUENT CALLS
!     (WHEN M0.NE.0) THE EQUATIONS ARE SOLVED USING THE DECOMPOSITION
!     OBTAINED ON THE INITIAL CALL TO RSLV.
!
!
!     INPUT ARGUMENTS WHEN M0=0 ---
!
!     N        NUMBER OF EQUATIONS AND UNKNOWNS.
!
!     A,IA,JA  THE MATRIX A STORED IN SPARSE FORM.
!
!     B        ARRAY OF N ENTRIES CONTAINING THE RIGHT HAND SIDE DATA.
!
!     R        INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF
!              THE ROWS OF A.
!
!     C        INTEGER ARRAY OF N ENTRIES SPECIFYING A SUGGESTED
!              ORDER OF THE COLUMNS. C IS ALSO AN OUTPUT ARGUMENT.
!
!     MAX      INTEGER SPECIFYING THE MAXIMUM NUMBER OF OFF-DIAGONAL
!              NONZERO ENTRIES OF L AND U WHICH MAY BE STORED.
!
!
!     OUTPUT ARGUMENTS WHEN M0=0 ---
!
!     C        INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF
!              THE COLUMNS THAT WAS SELECTED BY THE ROUTINE.
!
!     X        REAL ARRAY OF N ENTRIES CONTAINING THE SOLUTION.
!              B AND X MAY SHARE THE SAME STORAGE AREA.
!
!     IERR     INTEGER SPECIFYING THE STATUS OF THE RESULTS. IF THE
!              SOLUTION OF AX = B IS OBTAINED THEN IERR = MAX(1,M)
!              WHERE M IS THE TOTAL NUMBER OF OFF-DIAGONAL NONZERO
!              ENTRIES OF L AND U. OTHERWISE IERR.LE.0.
!
!
!     GENERAL STORAGE AREAS ---
!
!     IWK      INTEGER ARRAY OF DIMENSION 4*N + MAX + 2.
!
!     WK       REAL ARRAY OF DIMENSION 2*N + MAX.
!
!
!     AFTER AN INITIAL CALL TO RSLV, THE ROUTINE MAY BE RECALLED WITH
!     M0.NE.0 FOR A NEW B. WHEN M0.NE.0 IT IS ASSUMED THAT N,A,IA,JA,
!     R,C,IWK,WK HAVE NOT BEEN MODIFIED. THE ROUTINE RETRIEVES THE LU
!     DECOMPOSITION WHICH WAS OBTAINED ON THE INITIAL CALL TO RSLV
!     AND SOLVES THE NEW EQUATIONS AX = B. IN THIS CASE A,IA,JA,MAX,
!     AND IERR ARE NOT REFERENCED.
!-----------------------------------------------------------------------
REAL A(*), B(N), X(N), WK(*)
INTEGER IA(*), JA(*), IWK(*)
INTEGER R(N), C(N), Y, T, P
!
!     SET INDICES TO DIVIDE TEMPORARY STORAGE
!
Y = N + 1
T = Y + N
P = N + 1
IT = P + N + 1
IU = IT + N + 1
JT = IU + N
IF (M0 .NE. 0) GO TO 20
!
!     COMPUTE THE INVERSE PERMUTATION OF C
!
IERR = 0
IF (N .LE. 0) RETURN
DO K = 1,N
   L = C(K)
   IWK(L) = K
END DO
!
!     OBTAIN THE LU DECOMPOSITION OF A
!
CALL SPLU (A,IA,JA,R,C,IWK(1),N,MAX,WK(1),WK(T),IWK(IT),IWK(JT), &
&IWK(IU),WK(Y),IWK(P),IERR)
IF (IERR .LT. 0) RETURN
IERR = MAX0(1,IERR)
!
!     SOLVE THE SYSTEM OF EQUATIONS
!
20 CALL RSLV1 (N,R,C,IWK(1),WK(1),WK(T),IWK(IT),IWK(JT),IWK(IU), &
&B,X,WK(Y))
RETURN
END SUBROUTINE RSLV

SUBROUTINE RSLV1 (N,R,C,IC,D,T,IT,JT,IU,B,X,Y)
IMPLICIT NONE
INTENT(IN) B, C, D, IC, IT, IU, JT, N, R, T
INTENT(INOUT) X, Y
INTEGER N
INTEGER I, J, JJ, JMAX, JMIN, K, LJ, LK
INTEGER R(N), C(N), IC(N)
INTEGER IT(*), JT(*), IU(N)
REAL B(N), D(N), T(*), X(N), Y(N), SUM
!
!            SOLVE LY = B BY FORWARD SUBSTITUTION
!
do 11 K = 1,N
   LK = R(K)
   SUM = B(LK)
   JMIN = IT(K)
   JMAX = IU(K) - 1
   IF (JMIN .GT. JMAX) GO TO 11
   DO JJ = JMIN,JMAX
      LJ = JT(JJ)
      J = IC(LJ)
      SUM = SUM - T(JJ)*Y(J)
   END DO
11 Y(K) = SUM/D(K)
!
!            SOLVE UX = B BY BACKWARD SUBSTITUTION
!             AND REORDER X TO CORRESPOND WITH A
!
K = N
DO I = 1,N
   SUM = Y(K)
   JMIN = IU(K)
   JMAX = IT(K+1) - 1
   IF (JMIN .GT. JMAX) GO TO 21
   DO JJ = JMIN,JMAX
      LJ = JT(JJ)
      J = IC(LJ)
      SUM = SUM - T(JJ)*Y(J)
   END DO
21 Y(K) = SUM
   LK = C(K)
   X(LK) = Y(K)
   K = K - 1
END DO
RETURN
END SUBROUTINE RSLV1

SUBROUTINE TSLV (M0,N,A,IA,JA,B,R,C,MAX,X,IWK,WK,IERR)
IMPLICIT NONE
INTENT(IN) A, B, IA, JA, M0, MAX, N, R
INTENT(INOUT) C, IERR, IWK, WK, X
INTEGER IERR, M0, MAX, N
INTEGER IT, IU, JT, K, L
!-----------------------------------------------------------------------
!                 SOLUTION OF REAL SPARSE EQUATIONS
!-----------------------------------------------------------------------
!     TSLV EMPLOYS GAUSSIAN ELIMINATION WITH COLUMN INTERCHANGES TO
!     SOLVE THE NXN LINEAR SYSTEM XA = B. THE ARGUMENT M0 SPECIFIES
!     IF TSLV IS BEING CALLED FOR THE FIRST TIME, OR IF IT IS BEING
!     RECALLED WHERE A IS THE SAME MATRIX BUT B HAS BEEN MODIFIED.
!     ON AN INITIAL CALL TO THE ROUTINE (WHEN M0=0) THE LU DECOMPO-
!     SITION OF A IS OBTAINED WHERE U IS A UNIT UPPER TRIANGULAR
!     MATRIX. THEN THE EQUATIONS ARE SOLVED. ON SUBSEQUENT CALLS
!     (WHEN M0.NE.0) THE EQUATIONS ARE SOLVED USING THE DECOMPOSITION
!     OBTAINED ON THE INITIAL CALL TO TSLV.
!
!
!     INPUT ARGUMENTS WHEN M0=0 ---
!
!     N        NUMBER OF EQUATIONS AND UNKNOWNS.
!
!     A,IA,JA  THE MATRIX A STORED IN SPARSE FORM.
!
!     B        ARRAY OF N ENTRIES CONTAINING THE RIGHT HAND SIDE DATA.
!
!     R        INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF
!              THE ROWS OF A.
!
!     C        INTEGER ARRAY OF N ENTRIES SPECIFYING A SUGGESTED
!              ORDER OF THE COLUMNS. C IS ALSO AN OUTPUT ARGUMENT.
!
!     MAX      INTEGER SPECIFYING THE MAXIMUM NUMBER OF OFF-DIAGONAL
!              NONZERO ENTRIES OF L AND U WHICH MAY BE STORED.
!
!
!     OUTPUT ARGUMENTS WHEN M0=0 ---
!
!     C        INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF
!              THE COLUMNS THAT WAS SELECTED BY THE ROUTINE.
!
!     X        REAL ARRAY OF N ENTRIES CONTAINING THE SOLUTION.
!              B AND X MAY SHARE THE SAME STORAGE AREA.
!
!     IERR     INTEGER SPECIFYING THE STATUS OF THE RESULTS. IF THE
!              SOLUTION OF AX = B IS OBTAINED THEN IERR = MAX(1,M)
!              WHERE M IS THE TOTAL NUMBER OF OFF-DIAGONAL NONZERO
!              ENTRIES OF L AND U. OTHERWISE IERR.LE.0.
!
!
!     GENERAL STORAGE AREAS ---
!
!     IWK      INTEGER ARRAY OF DIMENSION 4*N + MAX + 2.
!
!     WK       REAL ARRAY OF DIMENSION 2*N + MAX.
!
!
!     AFTER AN INITIAL CALL TO TSLV, THE ROUTINE MAY BE RECALLED WITH
!     M0.NE.0 FOR A NEW B. WHEN M0.NE.0 IT IS ASSUMED THAT N,A,IA,JA,
!     R,C,IWK,WK HAVE NOT BEEN MODIFIED. THE ROUTINE RETRIEVES THE LU
!     DECOMPOSITION WHICH WAS OBTAINED ON THE INITIAL CALL TO TSLV
!     AND SOLVES THE NEW EQUATIONS XA = B. IN THIS CASE A,IA,JA,MAX,
!     AND IERR ARE NOT REFERENCED.
!-----------------------------------------------------------------------
REAL A(*), B(N), X(N), WK(*)
INTEGER IA(*), JA(*), IWK(*)
INTEGER R(N), C(N), Y, T, P
!
!     SET INDICES TO DIVIDE TEMPORARY STORAGE
!
Y = N + 1
T = Y + N
P = N + 1
IT = P + N + 1
IU = IT + N + 1
JT = IU + N
IF (M0 .NE. 0) GO TO 20
!
!     COMPUTE THE INVERSE PERMUTATION OF C
!
IERR = 0
IF (N .LE. 0) RETURN
DO K = 1,N
   L = C(K)
   IWK(L) = K
END DO
!
!     OBTAIN THE LU DECOMPOSITION OF A
!
CALL SPLU (A,IA,JA,R,C,IWK(1),N,MAX,WK(1),WK(T),IWK(IT),IWK(JT), &
&IWK(IU),WK(Y),IWK(P),IERR)
IF (IERR .LT. 0) RETURN
IERR = MAX0(1,IERR)
!
!     SOLVE THE SYSTEM OF EQUATIONS
!
20 CALL TSLV1 (N,R,C,IWK(1),WK(1),WK(T),IWK(IT),IWK(JT),IWK(IU), &
&B,X,WK(Y))
RETURN
END SUBROUTINE TSLV

SUBROUTINE TSLV1 (N,R,C,IC,D,T,IT,JT,IU,B,X,Y)
IMPLICIT NONE
INTENT(IN) B, C, D, IC, IT, IU, JT, N, R, T
INTENT(INOUT) X, Y
INTEGER N
INTEGER I, J, JJ, JMAX, JMIN, K, LJ, LK
INTEGER R(N), C(N), IC(N)
INTEGER IT(*), JT(*), IU(N)
REAL B(N), D(N), T(*), X(N), Y(N)
!
!            SOLVE YU = B BY FORWARD SUBSTITUTION
!
DO K = 1,N
   LK = C(K)
   Y(K) = B(LK)
END DO
!
do 21 K = 1,N
   IF (Y(K) .EQ. 0.0) GO TO 21
   JMIN = IU(K)
   JMAX = IT(K+1) - 1
   IF (JMIN .GT. JMAX) GO TO 21
   DO JJ = JMIN,JMAX
      LJ = JT(JJ)
      J = IC(LJ)
      Y(J) = Y(J) - T(JJ)*Y(K)
   END DO
21 CONTINUE
!
!            SOLVE XL = Y BY BACKWARD SUBSTITUTION
!
X(N) = Y(N)/D(N)
IF (N .EQ. 1) RETURN
!
K = N
Y(N) = X(N)
DO I = 2,N
   JMIN = IT(K)
   JMAX = IU(K) - 1
   IF (JMIN .GT. JMAX) GO TO 31
   DO JJ = JMIN,JMAX
      LJ = JT(JJ)
      J = IC(LJ)
      Y(J) = Y(J) - T(JJ)*Y(K)
   END DO
31 K = K - 1
   Y(K) = Y(K)/D(K)
END DO
!
DO K = 1,N
   LK = R(K)
   X(LK) = Y(K)
END DO
RETURN
END SUBROUTINE TSLV1

SUBROUTINE SPLU (A,IA,JA,R,C,IC,N,MAX,D,T,IT,JT,IU,W,P,IERR)
IMPLICIT NONE
INTENT(IN) A, IA, JA, MAX, N, R
INTENT(INOUT) C, D, IC, IERR, IT, IU, JT, P, T, W
INTEGER IERR, MAX, N
INTEGER I, J, JJ, JMAX, JMIN, JPTR, K, LJ, LK, LL, M, MAXI, MAXIL
!-----------------------------------------------------------------------
!     SPLU EMPLOYS GAUSSIAN ELIMINATION WITH COLUMN INTERCHANGES
!     TO PERFORM THE LU DECOMPOSITION OF A REAL SPARSE MATRIX.
!     U IS A UNIT UPPER TRIANGULAR MATRIX.
!
!
!     INPUT ARGUMENTS ---
!
!     A,IA,JA  THE SPARSE MATRIX TO BE DECOMPOSED.
!
!     R        INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF
!              THE ROWS OF A.
!
!     C        INTEGER ARRAY OF N ENTRIES SPECIFYING A SUGGESTED
!              ORDER OF THE COLUMNS. C IS ALSO AN OUTPUT ARGUMENT.
!
!     IC       INTEGER ARRAY OF N ENTRIES WHICH IS THE INVERSE OF C
!              (I.E., IC(C(I)) = I). IC IS ALSO AN OUTPUT ARGUMENT.
!
!     N        ORDER OF THE MATRIX A.
!
!     MAX      INTEGER SPECIFYING THE MAXIMUM NUMBER OF OFF-DIAGONAL
!              NONZERO ENTRIES OF L AND U WHICH MAY BE STORED.
!
!
!     OUTPUT ARGUMENTS ---
!
!     C        INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF
!              THE COLUMNS THAT WAS SELECTED BY THE ROUTINE.
!
!     IC       INTEGER ARRAY OF N ENTRIES WHICH IS THE INVERSE OF C.
!
!     D        REAL ARRAY CONTAINING THE N DIAGONAL ELEMENTS OF L.
!
!     T,IT,IU  T CONTAINS THE OFF-DIAGONAL NONZERO ELEMENTS OF L AND
!              U. FOR I = 1,...,N THE OFF-DIAGONAL NONZERO ELEMENTS
!              OF THE I-TH ROW OF L ARE STORED IN LOCATIONS
!              IT(I),...,IU(I)-1 OF T, AND THE OFF-DIAGONAL NONZERO
!              ELEMENTS OF THE I-TH ROW OF U ARE STORED IN LOCATIONS
!              IU(I),...,IT(I+1)-1 OF T.
!
!     JT       INTEGER ARRAY CONTAINING THE COLUMN INDICES (ACCORDING
!              TO THE ORGINAL COLUMN ORDERING) OF THE ELEMENTS OF T
!              (I.E., FOR EACH L(I,J) AND U(I,J) IN T, C(J) IS THE
!              CORRESPONDING COLUMN INDEX IN JT).
!
!     IERR     INTEGER SPECIFYING THE STATUS OF THE RESULTS. IF THE
!              LU DECOMPOSITION IS OBTAINED THEN IERR = THE NUMBER
!              OF OFF-DIAGONAL ENTRIES OF L AND U WHICH WERE STORED
!              IN T. OTHERWISE IERR IS ASSIGNED A NEGATIVE VALUE.
!
!
!     WORK SPACES ---
!
!     W        REAL ARRAY OF DIMENSION N.
!
!     P        INTEGER ARRAY OF DIMENSION N+1.
!-----------------------------------------------------------------------
REAL A(*), D(N), T(MAX), W(N)
INTEGER IA(*), JA(*)
INTEGER R(N), C(N), IC(N)
INTEGER IT(*), JT(MAX), IU(N)
INTEGER P(*), PM
REAL CONST, WI, WMAX
!
JPTR = 0
IT(1) = 1
DO J = 1,N
   W(J) = 0.0
END DO
!
!     PERFORM THE LU FACTORIZATION OF THE R(K)-TH ROW OF A
!
do 100 K = 1,N
LK = R(K)
JMIN = IA(LK)
JMAX = IA(LK+1) - 1
IF (JMIN .GT. JMAX) GO TO 200
!
!     SET P TO THE REORDERED ROW OF A
!
P(N+1) = N + 1
JJ = JMAX
20 LJ = JA(JJ)
J = IC(LJ)
W(J) = A(JJ)
PM = N + 1
21 M = PM
PM = P(M)
IF (PM - J) 21,210,22
22 P(M) = J
P(J) = PM
JJ = JJ - 1
IF (JJ .GE. JMIN) GO TO 20
!
!     PROCESS THE ENTRIES IN THE LOWER TRIANGLE OF A
!
I = N + 1
30 I = P(I)
IF (I .GE. K) GO TO 50
IF (W(I) .EQ. 0.0) GO TO 30
!
!     L(K,I) IS NONZERO. THEREFORE STORE IT IN L.
!
JPTR = JPTR + 1
IF (JPTR .GT. MAX) GO TO 230
CONST = W(I)
T(JPTR) = CONST
JT(JPTR) = C(I)
W(I) = 0.0
!
!     PERFORM ELIMINATION USING THE I-TH ROW OF U
!
JMIN = IU(I)
JMAX = IT(I+1) - 1
IF (JMIN .GT. JMAX) GO TO 30
PM = I
do 43 JJ = JMIN,JMAX
   LJ = JT(JJ)
   J = IC(LJ)
   IF (W(J) .NE. 0.0) GO TO 43
   IF (J - PM) 40,43,41
40 PM = I
41 M = PM
      PM = P(M)
      IF (PM - J) 41,43,42
42 P(M) = J
      P(J) = PM
      PM = J
43 W(J) = W(J) - CONST*T(JJ)
GO TO 30
!
!     SEARCH FOR THE K-TH PIVOT ELEMENT
!
50 IF (I .GT. N) GO TO 220
WMAX = ABS(W(I))
MAXI = I
PM = I
51 M = PM
PM = P(M)
IF (PM .GT. N) GO TO 60
WI = ABS(W(PM))
IF (WI .LE. WMAX) GO TO 51
   WMAX = WI
   MAXI = PM
   MAXIL = M
   GO TO 51
!
!     STORE THE PIVOT IN D
!
60 IF (WMAX .EQ. 0.0) GO TO 220
D(K) = W(MAXI)
!
!     PERFORM THE COLUMN INTERCHANGE
!
IF (I .EQ. K) GO TO 70
IF (I .EQ. MAXI) GO TO 70
   P(MAXIL) = P(MAXI)
   GO TO 80
70 I = P(I)
!
80 W(MAXI) = W(K)
W(K) = 0.0
LK = C(K)
LL = C(MAXI)
C(K) = LL
C(MAXI) = LK
IC(LK) = MAXI
IC(LL) = K
!
!     THE REMAINING ELEMENTS OF P FORM THE K-TH ROW OF U
!
IU(K) = JPTR + 1
90 IF (I .GT. N) GO TO 100
IF (W(I) .EQ. 0.0) GO TO 91
   JPTR = JPTR + 1
   IF (JPTR .GT. MAX) GO TO 230
   T(JPTR) = W(I)/D(K)
   JT(JPTR) = C(I)
   W(I) = 0.0
91 I = P(I)
GO TO 90
!
!     PREPARE FOR THE NEXT ROW
!
100 IT(K+1) = JPTR + 1
!
IERR = JPTR
RETURN
!
!     -------------------- ERROR RETURN --------------------
!
!     ROW R(K) IS NULL
!
200 IERR = -K
RETURN
!
!     ROW R(K) HAS A DUPLICATE ENTRY
!
210 IERR = -(N + K)
RETURN
!
!     ZERO PIVOT IN ROW R(K)
!
220 IERR = -(2*N + K)
RETURN
!
!     STORAGE FOR L AND U EXCEEDED ON ROW R(K)
!
230 IERR = -(3*N + K)
RETURN
END SUBROUTINE SPLU

SUBROUTINE DSPSLV (N,A,IA,JA,B,R,C,MAX,X,ITEMP,RTEMP,IERR)
IMPLICIT NONE
INTENT(IN) A, B, IA, JA, MAX, N, R
INTENT(OUT) IERR
INTENT(INOUT) C, ITEMP, RTEMP, X
INTEGER IERR, MAX, N
INTEGER K, L
!-----------------------------------------------------------------------
!          SOLUTION OF DOUBLE PRECISION SPARSE EQUATIONS
!-----------------------------------------------------------------------
!  DSPSLV CALLS DNSPIV WHICH USES SPARSE GAUSSIAN ELIMINATION WITH
!  COLUMN INTERCHANGES TO SOLVE THE LINEAR SYSTEM A X = B.  THE
!  ELIMINATION PHASE PERFORMS ROW OPERATIONS ON A AND B TO OBTAIN
!  A UNIT UPPER TRIANGULAR MATRIX U AND A VECTOR Y.  THE SOLUTION
!  PHASE SOLVES U X = Y.
!
!  INPUT ARGUMENTS---
!
!  N      INTEGER NUMBER OF EQUATIONS AND UNKNOWNS
!
!  A      DOUBLE PRECISION ARRAY WITH ONE ENTRY PER NONZERO IN A,
!         CONTAINING THE ACTUAL NONZEROS. (SEE THE MATRIX STORAGE
!         DESCRIPTION BELOW)
!
!  IA     INTEGER ARRAY OF N+1 ENTRIES CONTAINING ROW POINTERS TO A
!         (SEE MATRIX STORAGE DESCRIPTION BELOW)
!
!  JA     INTEGER ARRAY WITH ONE ENTRY PER NONZERO IN A, CONTAINING
!         COLUMN NUMBERS OF THE NONZEROS OF A.  (SEE MATRIX STORAGE
!         DESCRIPTION BELOW)
!
!  B      DOUBLE PRECISION ARRAY OF N ENTRIES CONTAINING THE RIGHT
!         HAND SIDE DATA
!
!  R      INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF THE
!         ROWS OF A (I.E., THE ELIMINATION ORDER FOR THE EQUATIONS)
!
!  C      INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF THE
!         COLUMNS OF A.  C IS ALSO AN OUTPUT ARGUMENT
!
!  MAX    INTEGER NUMBER SPECIFYING MAXIMUM NUMBER OF OFF-DIAGONAL
!         NONZERO ENTRIES OF U WHICH MAY BE STORED
!
!  ITEMP  INTEGER ARRAY OF 3*N + MAX + 2 ENTRIES, FOR INTERNAL USE
!
!  RTEMP  DOUBLE PRECISION ARRAY OF N + MAX ENTRIES FOR INTERNAL USE
!
!
!  OUTPUT ARGUMENTS---
!
!  C      INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF THE
!         COLUMNS OF U.  C IS ALSO AN INPUT ARGUMENT
!
!  X      DOUBLE PRECISION ARRAY OF N ENTRIES CONTAINING THE
!         SOLUTION VECTOR
!
!  IERR   INTEGER NUMBER WHICH INDICATES ERROR CONDITIONS OR
!         THE ACTUAL NUMBER OF OFF-DIAGONAL ENTRIES IN U (FOR
!         SUCCESSFUL COMPLETION)
!
!         IERR VALUES ARE---
!
!         0 LT IERR             SUCCESSFUL COMPLETION. IERR=MAX(1,M)
!                               WHERE M IS THE NUMBER OF OFF-DIAGONAL
!                               NONZERO ENTRIES OF U.
!
!         IERR = 0              ERROR.  N IS LESS THAN OR EQUAL TO 0
!
!         -N LE IERR LT 0       ERROR.  ROW NUMBER IABS(IERR) OF A IS
!                               IS NULL
!
!         -2*N LE IERR LT -N    ERROR.  ROW NUMBER IABS(IERR+N) HAS A
!                               DUPLICATE ENTRY
!
!         -3*N LE IERR LT -2*N  ERROR.  ROW NUMBER IABS(IERR+2*N)
!                               HAS A ZERO PIVOT
!
!         -4*N LE IERR LT -3*N  ERROR.  ROW NUMBER IABS(IERR+3*N)
!                               EXCEEDS STORAGE
!
!
!  STORAGE OF SPARSE MATRICES---
!
!  THE SPARSE MATRIX A IS STORED USING THREE ARRAYS IA, JA, AND A.
!  THE ARRAY A CONTAINS THE NONZEROS OF THE MATRIX ROW-BY-ROW, NOT
!  NECESSARILY IN ORDER OF INCREASING COLUMN NUMBER.  THE ARRAY JA
!  CONTAINS THE COLUMN NUMBERS CORRESPONDING TO THE NONZEROS STORED
!  IN THE ARRAY A (I.E., IF THE NONZERO STORED IN A(K) IS IN
!  COLUMN J, THEN JA(K) = J).  THE ARRAY IA CONTAINS POINTERS TO THE
!  ROWS OF NONZEROS/COLUMN INDICES IN THE ARRAY A/JA (I.E.,
!  A(IA(I))/JA(IA(I)) IS THE FIRST ENTRY FOR ROW I IN THE ARRAY A/JA).
!  IA(N+1) IS SET SO THAT IA(N+1) - IA(1) = THE NUMBER OF NONZERO
!  ELEMENTS IN A.
!------------------------
DOUBLE PRECISION A(*), B(N), X(N), RTEMP(*)
INTEGER IA(*), JA(*), R(N), C(N), ITEMP(*)
INTEGER IU, JU, U, Y, P
!
IERR = 0
IF (N .LE. 0) RETURN
!
!  SET INDICES TO DIVIDE TEMPORARY STORAGE FOR DNSPIV
!
Y = 1
U = Y + N
P = N + 1
IU = P + N + 1
JU = IU + N + 1
!
!  COMPUTE THE INVERSE PERMUTATION OF C
!
DO K = 1,N
   L = C(K)
   ITEMP(L) = K
END DO
!
!  CALL DNSPIV TO PERFORM COMPUTATIONS
!
CALL DNSPIV (N,IA,JA,A,B,MAX,R,C,ITEMP(1),X,RTEMP(Y),ITEMP(P), &
&ITEMP(IU),ITEMP(JU),RTEMP(U),IERR)
IF (IERR .EQ. 0) IERR = 1
RETURN
END SUBROUTINE DSPSLV

SUBROUTINE DNSPIV (N,IA,JA,A,B,MAX,R,C,IC,X,Y,P,IU,JU,U,IERR)
IMPLICIT NONE
INTENT(IN) A, B, IA, JA, MAX, N, R
INTENT(INOUT) C, IC, IERR, IU, JU, P, U, X, Y
INTEGER IERR, MAX, N
INTEGER I, J, JAJ, JMAX, JMIN, JUJ, JUPTR, K, MAXC, MAXCL, NZCNT
!
!
!  DNSPIV USES SPARSE GAUSSIAN ELIMINATION WITH
!  COLUMN INTERCHANGES TO SOLVE THE LINEAR SYSTEM A X = B.  THE
!  ELIMINATION PHASE PERFORMS ROW OPERATIONS ON A AND B TO OBTAIN
!  A UNIT UPPER TRIANGULAR MATRIX U AND A VECTOR Y.  THE SOLUTION
!  PHASE SOLVES U X = Y.
!
!
!  SEE DSPSLV FOR DESCRIPTIONS OF ALL INPUT AND OUTPUT ARGUMENTS
!  OTHER THAN THOSE DESCRIBED BELOW
!
!  IC  INTEGER ARRAY OF N ENTRIES WHICH IS THE INVERSE OF C
!      (I.E., IC(C(I)) = I). IC IS BOTH AN INPUT AND OUTPUT
!      ARGUMENT.
!
!  INPUT ARGUMENTS (USED INTERNALLY ONLY)---
!
!  Y   DOUBLE PRECISION ARRAY OF N ENTRIES USED TO COMPUTE
!      THE UPDATED RIGHT HAND SIDE
!
!  P   INTEGER ARRAY OF N+1 ENTRIES USED FOR A LINKED LIST.
!      P(N+1) IS THE LIST HEADER, AND THE ENTRY FOLLOWING
!      P(K) IS IN P(P(K)).  THUS, P(N+1) IS THE FIRST DATA
!      ITEM, P(P(N+1)) IS THE SECOND, ETC.  A POINTER OF
!      N+1 MARKS THE END OF THE LIST
!
!  IU  INTEGER ARRAY OF N+1 ENTRIES USED FOR ROW POINTERS TO U
!      (SEE MATRIX STORAGE DESCRIPTION BELOW)
!
!  JU  INTEGER ARRAY OF MAX ENTRIES USED FOR COLUMN NUMBERS OF
!      THE NONZEROS IN THE STRICT UPPER TRIANGLE OF U.  (SEE
!      MATRIX STORAGE DESCRIPTION BELOW)
!
!  U   DOUBLE PRECISION ARRAY OF MAX ENTRIES USED FOR THE ACTUAL
!      NONZEROS IN THE STRICT UPPER TRIANGLE OF U. (SEE MATRIX
!      STORAGE DESCRIPTION BELOW)
!
!
!  STORAGE OF SPARSE MATRICES---
!
!  THE SPARSE MATRIX A IS STORED USING THREE ARRAYS IA, JA, AND A.
!  THE ARRAY A CONTAINS THE NONZEROS OF THE MATRIX ROW-BY-ROW, NOT
!  NECESSARILY IN ORDER OF INCREASING COLUMN NUMBER.  THE ARRAY JA
!  CONTAINS THE COLUMN NUMBERS CORRESPONDING TO THE NONZEROS STORED
!  IN THE ARRAY A (I.E., IF THE NONZERO STORED IN A(K) IS IN
!  COLUMN J, THEN JA(K) = J).  THE ARRAY IA CONTAINS POINTERS TO THE
!  ROWS OF NONZEROS/COLUMN INDICES IN THE ARRAY A/JA (I.E.,
!  A(IA(I))/JA(IA(I)) IS THE FIRST ENTRY FOR ROW I IN THE ARRAY A/JA).
!  IA(N+1) IS SET SO THAT IA(N+1) - IA(1) = THE NUMBER OF NONZEROS IN
!  A.  IU, JU, AND U ARE USED IN A SIMILAR WAY TO STORE THE STRICT UPPER
!  TRIANGLE OF U, EXCEPT THAT JU ACTUALLY CONTAINS C(J) INSTEAD OF J
!
!
DOUBLE PRECISION A(*), B(N), U(MAX), X(N), Y(N)
DOUBLE PRECISION DK, LKI, XPV, XPVMAX, YK
INTEGER C(N), IA(*), IC(N), IU(*), JA(*), JU(MAX), P(*), R(N)
INTEGER CK, PK, PPK, PV, V, VI, VJ, VK
!
!  INITIALIZE WORK STORAGE AND POINTERS TO JU
!
DO J = 1,N
  X(J) = 0.D0
END DO
IU(1) = 1
JUPTR = 0
!
!  PERFORM SYMBOLIC AND NUMERIC FACTORIZATION ROW BY ROW
!  VK (VI,VJ) IS THE GRAPH VERTEX FOR ROW K (I,J) OF U
!
do 170 K = 1,N
!
!  INITIALIZE LINKED LIST AND FREE STORAGE FOR THIS ROW
!  THE R(K)-TH ROW OF A BECOMES THE K-TH ROW OF U.
!
  P(N+1) = N+1
  VK = R(K)
!
!  SET UP ADJACENCY LIST FOR VK, ORDERED IN
!  CURRENT COLUMN ORDER OF U.  THE LOOP INDEX
!  GOES DOWNWARD TO EXPLOIT ANY COLUMNS
!  FROM A IN CORRECT RELATIVE ORDER
!
  JMIN = IA(VK)
  JMAX = IA(VK+1) - 1
  IF (JMIN .GT. JMAX)  GO TO 1002
  J = JMAX
20 JAJ = JA(J)
    VJ = IC(JAJ)
!
!  STORE A(K,J) IN WORK VECTOR
!
    X(VJ) = A(J)
!  THIS CODE INSERTS VJ INTO ADJACENCY LIST OF VK
    PPK = N+1
30 PK = PPK
    PPK = P(PK)
    IF (PPK - VJ)  30,1003,40
40 P(VJ) = PPK
    P(PK) = VJ
    J = J - 1
    IF (J .GE. JMIN) GO TO 20
!
!  THE FOLLOWING CODE COMPUTES THE K-TH ROW OF U
!
  VI = N+1
  YK = B(VK)
50 VI = P(VI)
  IF (VI .GE. K) GO TO 110
!
!  VI LT VK -- PROCESS THE L(K,I) ELEMENT AND MERGE THE
!  ADJACENCY OF VI WITH THE ORDERED ADJACENCY OF VK
!
  LKI = - X(VI)
  X(VI) = 0.D0
!
!  ADJUST RIGHT HAND SIDE TO REFLECT ELIMINATION
!
  YK = YK + LKI * Y(VI)
  PPK = VI
  JMIN = IU(VI)
  JMAX = IU(VI+1) - 1
  IF (JMIN .GT. JMAX)  GO TO 50
  DO J = JMIN,JMAX
    JUJ = JU(J)
    VJ = IC(JUJ)
!
!  IF VJ IS ALREADY IN THE ADJACENCY OF VK,
!  SKIP THE INSERTION
!
    IF (X(VJ) .NE. 0.D0)  GO TO 90
!
!  INSERT VJ IN ADJACENCY LIST OF VK.
!  RESET PPK TO VI IF WE HAVE PASSED THE CORRECT
!  INSERTION SPOT.  (THIS HAPPENS WHEN THE ADJACENCY OF
!  VI IS NOT IN CURRENT COLUMN ORDER DUE TO PIVOTING.)
!
    IF (VJ - PPK) 60,90,70
60 PPK = VI
70 PK = PPK
    PPK = P(PK)
    IF (PPK - VJ)  70,90,80
80 P(VJ) = PPK
    P(PK) = VJ
    PPK = VJ
!
!  COMPUTE L(K,J) = L(K,J) - L(K,I)*U(I,J) FOR L(K,I) NONZERO
!  COMPUTE U*(K,J) = U*(K,J) - L(K,I)*U(I,J) FOR U(K,J) NONZERO
!  (U*(K,J) = U(K,J)*D(K,K))
!
90 X(VJ) = X(VJ) + LKI * U(J)
  END DO
  GO TO 50
!
!  PIVOT--INTERCHANGE LARGEST ENTRY OF K-TH ROW OF U WITH
!  THE DIAGONAL ENTRY.
!
!  FIND LARGEST ENTRY, COUNTING OFF-DIAGONAL NONZEROS
!
110 IF (VI .GT. N) GO TO 1004
  XPVMAX = DABS(X(VI))
  MAXC = VI
  NZCNT = 0
  PV = VI
120 V = PV
    PV = P(PV)
    IF (PV .GT. N) GO TO 130
    NZCNT = NZCNT + 1
    XPV = DABS(X(PV))
    IF (XPV .LE. XPVMAX) GO TO 120
    XPVMAX = XPV
    MAXC = PV
    MAXCL = V
    GO TO 120
130 IF (XPVMAX .EQ. 0.D0) GO TO 1004
!
!  IF VI = K, THEN THERE IS AN ENTRY FOR DIAGONAL
!  WHICH MUST BE DELETED.  OTHERWISE, DELETE THE
!  ENTRY WHICH WILL BECOME THE DIAGONAL ENTRY
!
  IF (VI .EQ. K) GO TO 140
  IF (VI .EQ. MAXC) GO TO 140
  P(MAXCL) = P(MAXC)
  GO TO 150
140 VI = P(VI)
!
!  COMPUTE D(K) = 1/L(K,K) AND PERFORM INTERCHANGE.
!
150 DK = 1.D0 / X(MAXC)
  X(MAXC) = X(K)
  I = C(K)
  C(K) = C(MAXC)
  C(MAXC) = I
  CK = C(K)
  IC(CK) = K
  IC(I) = MAXC
  X(K) = 0.D0
!
!  UPDATE RIGHT HAND SIDE.
!
  Y(K) = YK * DK
!
!  COMPUTE VALUE FOR IU(K+1) AND CHECK FOR STORAGE OVERFLOW
!
  IU(K+1) = IU(K) + NZCNT
  IF (IU(K+1) .GT. MAX+1) GO TO 1005
!
!  MOVE COLUMN INDICES FROM LINKED LIST TO JU.
!  COLUMNS ARE STORED IN CURRENT ORDER WITH ORIGINAL
!  COLUMN NUMBER (C(J)) STORED FOR CURRENT COLUMN J
!
  IF (VI .GT. N)  GO TO 170
  J = VI
160 JUPTR = JUPTR + 1
    JU(JUPTR) = C(J)
    U(JUPTR) = X(J) * DK
    X(J) = 0.D0
    J = P(J)
    IF (J .LE. N) GO TO 160
170 CONTINUE
!
!  BACKSOLVE U X = Y, AND REORDER X TO CORRESPOND WITH A
!
K = N
DO I = 1,N
  YK = Y(K)
  JMIN = IU(K)
  JMAX = IU(K+1) - 1
  IF (JMIN .GT. JMAX)  GO TO 190
  DO J = JMIN,JMAX
    JUJ = JU(J)
    JUJ = IC(JUJ)
    YK = YK - U(J) * Y(JUJ)
  END DO
190 Y(K) = YK
  CK = C(K)
  X(CK) = YK
  K = K - 1
END DO
!
!  RETURN WITH IERR = NUMBER OF OFF-DIAGONAL NONZEROS IN U
!
IERR = IU(N+1) - IU(1)
RETURN
!
!  ERROR RETURNS
!
!  ROW K OF A IS NULL
!
1002 IERR = -K
RETURN
!
!  ROW K OF A HAS A DUPLICATE ENTRY
!
1003 IERR = -(N+K)
RETURN
!
!  ZERO PIVOT IN ROW K
!
1004 IERR = -(2*N+K)
RETURN
!
!  STORAGE FOR U EXCEEDED ON ROW K
!
1005 IERR = -(3*N+K)
RETURN
END SUBROUTINE DNSPIV

SUBROUTINE DSLV (M0,N,A,IA,JA,B,R,C,MAX,X,IWK,WK,IERR)
IMPLICIT NONE
INTENT(IN) A, B, IA, JA, M0, MAX, N, R
INTENT(INOUT) C, IERR, IWK, WK, X
INTEGER IERR, M0, MAX, N
INTEGER IT, IU, JT, K, L
!-----------------------------------------------------------------------
!          SOLUTION OF DOUBLE PRECISION SPARSE EQUATIONS
!-----------------------------------------------------------------------
!     DSLV EMPLOYS GAUSSIAN ELIMINATION WITH COLUMN INTERCHANGES TO
!     SOLVE THE NXN LINEAR SYSTEM AX = B. THE ARGUMENT M0 SPECIFIES
!     IF DSLV IS BEING CALLED FOR THE FIRST TIME, OR IF IT IS BEING
!     RECALLED WHERE A IS THE SAME MATRIX BUT B HAS BEEN MODIFIED.
!     ON AN INITIAL CALL TO THE ROUTINE (WHEN M0=0) THE LU DECOMPO-
!     SITION OF A IS OBTAINED WHERE U IS A UNIT UPPER TRIANGULAR
!     MATRIX. THEN THE EQUATIONS ARE SOLVED. ON SUBSEQUENT CALLS
!     (WHEN M0.NE.0) THE EQUATIONS ARE SOLVED USING THE DECOMPOSITION
!     OBTAINED ON THE INITIAL CALL TO DSLV.
!
!
!     INPUT ARGUMENTS WHEN M0=0 ---
!
!     N        NUMBER OF EQUATIONS AND UNKNOWNS.
!
!     A,IA,JA  THE DOUBLE PRECISION MATRIX A STORED IN SPARSE FORM.
!
!     B        DOUBLE PRECISION ARRAY OF N ENTRIES CONTAINING THE
!              RIGHT HAND SIDE DATA.
!
!     R        INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF
!              THE ROWS OF A.
!
!     C        INTEGER ARRAY OF N ENTRIES SPECIFYING A SUGGESTED
!              ORDER OF THE COLUMNS. C IS ALSO AN OUTPUT ARGUMENT.
!
!     MAX      INTEGER SPECIFYING THE MAXIMUM NUMBER OF OFF-DIAGONAL
!              NONZERO ENTRIES OF L AND U WHICH MAY BE STORED.
!
!
!     OUTPUT ARGUMENTS WHEN M0=0 ---
!
!     C        INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF
!              THE COLUMNS THAT WAS SELECTED BY THE ROUTINE.
!
!     X        DOUBLE PRECISION ARRAY OF N ENTRIES CONTAINING THE
!              SOLUTION. B AND X MAY SHARE THE SAME STORAGE AREA.
!
!     IERR     INTEGER SPECIFYING THE STATUS OF THE RESULTS. IF THE
!              SOLUTION OF AX = B IS OBTAINED THEN IERR = MAX(1,M)
!              WHERE M IS THE TOTAL NUMBER OF OFF-DIAGONAL NONZERO
!              ENTRIES OF L AND U. OTHERWISE IERR.LE.0.
!
!
!     GENERAL STORAGE AREAS ---
!
!     IWK      INTEGER ARRAY OF DIMENSION 4*N + MAX + 2.
!
!     WK       DOUBLE PRECISION ARRAY OF DIMENSION 2*N + MAX.
!
!
!     AFTER AN INITIAL CALL TO DSLV, THE ROUTINE MAY BE RECALLED WITH
!     M0.NE.0 FOR A NEW B. WHEN M0.NE.0 IT IS ASSUMED THAT N,A,IA,JA,
!     R,C,IWK,WK HAVE NOT BEEN MODIFIED. THE ROUTINE RETRIEVES THE LU
!     DECOMPOSITION WHICH WAS OBTAINED ON THE INITIAL CALL TO DSLV
!     AND SOLVES THE NEW EQUATIONS AX = B. IN THIS CASE A,IA,JA,MAX,
!     AND IERR ARE NOT REFERENCED.
!-----------------------------------------------------------------------
DOUBLE PRECISION A(*), B(N), X(N), WK(*)
INTEGER IA(*), JA(*), IWK(*)
INTEGER R(N), C(N), Y, T, P
!
!     SET INDICES TO DIVIDE TEMPORARY STORAGE
!
Y = N + 1
T = Y + N
P = N + 1
IT = P + N + 1
IU = IT + N + 1
JT = IU + N
IF (M0 .NE. 0) GO TO 20
!
!     COMPUTE THE INVERSE PERMUTATION OF C
!
IERR = 0
IF (N .LE. 0) RETURN
DO K = 1,N
   L = C(K)
   IWK(L) = K
END DO
!
!     OBTAIN THE LU DECOMPOSITION OF A
!
CALL DSPLU (A,IA,JA,R,C,IWK(1),N,MAX,WK(1),WK(T),IWK(IT),IWK(JT), &
&IWK(IU),WK(Y),IWK(P),IERR)
IF (IERR .LT. 0) RETURN
IERR = MAX0(1,IERR)
!
!     SOLVE THE SYSTEM OF EQUATIONS
!
20 CALL DSLV1 (N,R,C,IWK(1),WK(1),WK(T),IWK(IT),IWK(JT),IWK(IU), &
&B,X,WK(Y))
RETURN
END SUBROUTINE DSLV

SUBROUTINE DSLV1 (N,R,C,IC,D,T,IT,JT,IU,B,X,Y)
IMPLICIT NONE
INTENT(IN) B, C, D, IC, IT, IU, JT, N, R, T
INTENT(INOUT) X, Y
INTEGER N
INTEGER I, J, JJ, JMAX, JMIN, K, LJ, LK
INTEGER R(N), C(N), IC(N)
INTEGER IT(*), JT(*), IU(N)
DOUBLE PRECISION B(N), D(N), T(*), X(N), Y(N), SUM
!
!            SOLVE LY = B BY FORWARD SUBSTITUTION
!
do 11 K = 1,N
   LK = R(K)
   SUM = B(LK)
   JMIN = IT(K)
   JMAX = IU(K) - 1
   IF (JMIN .GT. JMAX) GO TO 11
   DO JJ = JMIN,JMAX
      LJ = JT(JJ)
      J = IC(LJ)
      SUM = SUM - T(JJ)*Y(J)
   END DO
11 Y(K) = SUM/D(K)
!
!            SOLVE UX = B BY BACKWARD SUBSTITUTION
!             AND REORDER X TO CORRESPOND WITH A
!
K = N
DO I = 1,N
   SUM = Y(K)
   JMIN = IU(K)
   JMAX = IT(K+1) - 1
   IF (JMIN .GT. JMAX) GO TO 21
   DO JJ = JMIN,JMAX
      LJ = JT(JJ)
      J = IC(LJ)
      SUM = SUM - T(JJ)*Y(J)
   END DO
21 Y(K) = SUM
   LK = C(K)
   X(LK) = Y(K)
   K = K - 1
END DO
RETURN
END SUBROUTINE DSLV1

SUBROUTINE DTSLV (M0,N,A,IA,JA,B,R,C,MAX,X,IWK,WK,IERR)
IMPLICIT NONE
INTENT(IN) A, B, IA, JA, M0, MAX, N, R
INTENT(INOUT) C, IERR, IWK, WK, X
INTEGER IERR, M0, MAX, N
INTEGER IT, IU, JT, K, L
!-----------------------------------------------------------------------
!          SOLUTION OF DOUBLE PRECISION SPARSE EQUATIONS
!-----------------------------------------------------------------------
!     DTSLV EMPLOYS GAUSSIAN ELIMINATION WITH COLUMN INTERCHANGES TO
!     SOLVE THE NXN LINEAR SYSTEM XA = B. THE ARGUMENT M0 SPECIFIES
!     IF DTSLV IS BEING CALLED FOR THE FIRST TIME, OR IF IT IS BEING
!     RECALLED WHERE A IS THE SAME MATRIX BUT B HAS BEEN MODIFIED.
!     ON AN INITIAL CALL TO THE ROUTINE (WHEN M0=0) THE LU DECOMPO-
!     SITION OF A IS OBTAINED WHERE U IS A UNIT UPPER TRIANGULAR
!     MATRIX. THEN THE EQUATIONS ARE SOLVED. ON SUBSEQUENT CALLS
!     (WHEN M0.NE.0) THE EQUATIONS ARE SOLVED USING THE DECOMPOSITION
!     OBTAINED ON THE INITIAL CALL TO DTSLV.
!
!
!     INPUT ARGUMENTS WHEN M0=0 ---
!
!     N        NUMBER OF EQUATIONS AND UNKNOWNS.
!
!     A,IA,JA  THE DOUBLE PRECISION MATRIX A STORED IN SPARSE FORM.
!
!     B        DOUBLE PRECISION ARRAY OF N ENTRIES CONTAINING THE
!              RIGHT HAND SIDE DATA.
!
!     R        INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF
!              THE ROWS OF A.
!
!     C        INTEGER ARRAY OF N ENTRIES SPECIFYING A SUGGESTED
!              ORDER OF THE COLUMNS. C IS ALSO AN OUTPUT ARGUMENT.
!
!     MAX      INTEGER SPECIFYING THE MAXIMUM NUMBER OF OFF-DIAGONAL
!              NONZERO ENTRIES OF L AND U WHICH MAY BE STORED.
!
!
!     OUTPUT ARGUMENTS WHEN M0=0 ---
!
!     C        INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF
!              THE COLUMNS THAT WAS SELECTED BY THE ROUTINE.
!
!     X        DOUBLE PRECISION ARRAY OF N ENTRIES CONTAINING THE
!              SOLUTION. B AND X MAY SHARE THE SAME STORAGE AREA.
!
!     IERR     INTEGER SPECIFYING THE STATUS OF THE RESULTS. IF THE
!              SOLUTION OF AX = B IS OBTAINED THEN IERR = MAX(1,M)
!              WHERE M IS THE TOTAL NUMBER OF OFF-DIAGONAL NONZERO
!              ENTRIES OF L AND U. OTHERWISE IERR.LE.0.
!
!
!     GENERAL STORAGE AREAS ---
!
!     IWK      INTEGER ARRAY OF DIMENSION 4*N + MAX + 2.
!
!     WK       DOUBLE PRECISION ARRAY OF DIMENSION 2*N + MAX.
!
!
!     AFTER AN INITIAL CALL TO DTSLV, THE ROUTINE MAY BE RECALLED WITH
!     M0.NE.0 FOR A NEW B. WHEN M0.NE.0 IT IS ASSUMED THAT N,A,IA,JA,
!     R,C,IWK,WK HAVE NOT BEEN MODIFIED. THE ROUTINE RETRIEVES THE LU
!     DECOMPOSITION WHICH WAS OBTAINED ON THE INITIAL CALL TO DTSLV
!     AND SOLVES THE NEW EQUATIONS XA = B. IN THIS CASE A,IA,JA,MAX,
!     AND IERR ARE NOT REFERENCED.
!-----------------------------------------------------------------------
DOUBLE PRECISION A(*), B(N), X(N), WK(*)
INTEGER IA(*), JA(*), IWK(*)
INTEGER R(N), C(N), Y, T, P
!
!     SET INDICES TO DIVIDE TEMPORARY STORAGE
!
Y = N + 1
T = Y + N
P = N + 1
IT = P + N + 1
IU = IT + N + 1
JT = IU + N
IF (M0 .NE. 0) GO TO 20
!
!     COMPUTE THE INVERSE PERMUTATION OF C
!
IERR = 0
IF (N .LE. 0) RETURN
DO K = 1,N
   L = C(K)
   IWK(L) = K
END DO
!
!     OBTAIN THE LU DECOMPOSITION OF A
!
CALL DSPLU (A,IA,JA,R,C,IWK(1),N,MAX,WK(1),WK(T),IWK(IT),IWK(JT), &
&IWK(IU),WK(Y),IWK(P),IERR)
IF (IERR .LT. 0) RETURN
IERR = MAX0(1,IERR)
!
!     SOLVE THE SYSTEM OF EQUATIONS
!
20 CALL DTSLV1 (N,R,C,IWK(1),WK(1),WK(T),IWK(IT),IWK(JT),IWK(IU), &
&B,X,WK(Y))
RETURN
END SUBROUTINE DTSLV

SUBROUTINE DTSLV1 (N,R,C,IC,D,T,IT,JT,IU,B,X,Y)
IMPLICIT NONE
INTENT(IN) B, C, D, IC, IT, IU, JT, N, R, T
INTENT(INOUT) X, Y
INTEGER N
INTEGER I, J, JJ, JMAX, JMIN, K, LJ, LK
INTEGER R(N), C(N), IC(N)
INTEGER IT(*), JT(*), IU(N)
DOUBLE PRECISION B(N), D(N), T(*), X(N), Y(N)
!
!            SOLVE YU = B BY FORWARD SUBSTITUTION
!
DO K = 1,N
   LK = C(K)
   Y(K) = B(LK)
END DO
!
do 21 K = 1,N
   IF (Y(K) .EQ. 0.D0) GO TO 21
   JMIN = IU(K)
   JMAX = IT(K+1) - 1
   IF (JMIN .GT. JMAX) GO TO 21
   DO JJ = JMIN,JMAX
      LJ = JT(JJ)
      J = IC(LJ)
      Y(J) = Y(J) - T(JJ)*Y(K)
   END DO
21 CONTINUE
!
!            SOLVE XL = Y BY BACKWARD SUBSTITUTION
!
X(N) = Y(N)/D(N)
IF (N .EQ. 1) RETURN
!
K = N
Y(N) = X(N)
DO I = 2,N
   JMIN = IT(K)
   JMAX = IU(K) - 1
   IF (JMIN .GT. JMAX) GO TO 31
   DO JJ = JMIN,JMAX
      LJ = JT(JJ)
      J = IC(LJ)
      Y(J) = Y(J) - T(JJ)*Y(K)
   END DO
31 K = K - 1
   Y(K) = Y(K)/D(K)
END DO
!
DO K = 1,N
   LK = R(K)
   X(LK) = Y(K)
END DO
RETURN
END SUBROUTINE DTSLV1

SUBROUTINE DSPLU (A,IA,JA,R,C,IC,N,MAX,D,T,IT,JT,IU,W,P,IERR)
IMPLICIT NONE
INTENT(IN) A, IA, JA, MAX, N, R
INTENT(INOUT) C, D, IC, IERR, IT, IU, JT, P, T, W
INTEGER IERR, MAX, N
INTEGER I, J, JJ, JMAX, JMIN, JPTR, K, LJ, LK, LL, M, MAXI, MAXIL
!-----------------------------------------------------------------------
!     DSPLU EMPLOYS GAUSSIAN ELIMINATION WITH COLUMN INTERCHANGES
!     TO PERFORM THE LU DECOMPOSITION OF A DOUBLE PRECISION SPARSE
!     MATRIX. U IS A UNIT UPPER TRIANGULAR MATRIX.
!
!
!     INPUT ARGUMENTS ---
!
!     A,IA,JA  THE SPARSE MATRIX TO BE DECOMPOSED.
!
!     R        INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF
!              THE ROWS OF A.
!
!     C        INTEGER ARRAY OF N ENTRIES SPECIFYING A SUGGESTED
!              ORDER OF THE COLUMNS. C IS ALSO AN OUTPUT ARGUMENT.
!
!     IC       INTEGER ARRAY OF N ENTRIES WHICH IS THE INVERSE OF C
!              (I.E., IC(C(I)) = I). IC IS ALSO AN OUTPUT ARGUMENT.
!
!     N        ORDER OF THE MATRIX A.
!
!     MAX      INTEGER SPECIFYING THE MAXIMUM NUMBER OF OFF-DIAGONAL
!              NONZERO ENTRIES OF L AND U WHICH MAY BE STORED.
!
!
!     OUTPUT ARGUMENTS ---
!
!     C        INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF
!              THE COLUMNS THAT WAS SELECTED BY THE ROUTINE.
!
!     IC       INTEGER ARRAY OF N ENTRIES WHICH IS THE INVERSE OF C.
!
!     D        DOUBLE PRECISION ARRAY CONTAINING THE N DIAGONAL
!              ELEMENTS OF L.
!
!     T,IT,IU  T CONTAINS THE OFF-DIAGONAL NONZERO ELEMENTS OF L AND
!              U. FOR I = 1,...,N THE OFF-DIAGONAL NONZERO ELEMENTS
!              OF THE I-TH ROW OF L ARE STORED IN LOCATIONS
!              IT(I),...,IU(I)-1 OF T, AND THE OFF-DIAGONAL NONZERO
!              ELEMENTS OF THE I-TH ROW OF U ARE STORED IN LOCATIONS
!              IU(I),...,IT(I+1)-1 OF T.
!
!     JT       INTEGER ARRAY CONTAINING THE COLUMN INDICES (ACCORDING
!              TO THE ORGINAL COLUMN ORDERING) OF THE ELEMENTS OF T
!              (I.E., FOR EACH L(I,J) AND U(I,J) IN T, C(J) IS THE
!              CORRESPONDING COLUMN INDEX IN JT).
!
!     IERR     INTEGER SPECIFYING THE STATUS OF THE RESULTS. IF THE
!              LU DECOMPOSITION IS OBTAINED THEN IERR = THE NUMBER
!              OF OFF-DIAGONAL ENTRIES OF L AND U WHICH WERE STORED
!              IN T. OTHERWISE IERR IS ASSIGNED A NEGATIVE VALUE.
!
!
!     WORK SPACES ---
!
!     W        DOUBLE PRECISION ARRAY OF DIMENSION N.
!
!     P        INTEGER ARRAY OF DIMENSION N+1.
!-----------------------------------------------------------------------
DOUBLE PRECISION A(*), D(N), T(MAX), W(N)
INTEGER IA(*), JA(*)
INTEGER R(N), C(N), IC(N)
INTEGER IT(*), JT(MAX), IU(N)
INTEGER P(*), PM
DOUBLE PRECISION CONST, WI, WMAX
!
JPTR = 0
IT(1) = 1
DO J = 1,N
   W(J) = 0.D0
END DO
!
!     PERFORM THE LU FACTORIZATION OF THE R(K)-TH ROW OF A
!
do 100 K = 1,N
LK = R(K)
JMIN = IA(LK)
JMAX = IA(LK+1) - 1
IF (JMIN .GT. JMAX) GO TO 200
!
!     SET P TO THE REORDERED ROW OF A
!
P(N+1) = N + 1
JJ = JMAX
20 LJ = JA(JJ)
J = IC(LJ)
W(J) = A(JJ)
PM = N + 1
21 M = PM
PM = P(M)
IF (PM - J) 21,210,22
22 P(M) = J
P(J) = PM
JJ = JJ - 1
IF (JJ .GE. JMIN) GO TO 20
!
!     PROCESS THE ENTRIES IN THE LOWER TRIANGLE OF A
!
I = N + 1
30 I = P(I)
IF (I .GE. K) GO TO 50
IF (W(I) .EQ. 0.D0) GO TO 30
!
!     L(K,I) IS NONZERO. THEREFORE STORE IT IN L.
!
JPTR = JPTR + 1
IF (JPTR .GT. MAX) GO TO 230
CONST = W(I)
T(JPTR) = CONST
JT(JPTR) = C(I)
W(I) = 0.D0
!
!     PERFORM ELIMINATION USING THE I-TH ROW OF U
!
JMIN = IU(I)
JMAX = IT(I+1) - 1
IF (JMIN .GT. JMAX) GO TO 30
PM = I
do 43 JJ = JMIN,JMAX
   LJ = JT(JJ)
   J = IC(LJ)
   IF (W(J) .NE. 0.D0) GO TO 43
   IF (J - PM) 40,43,41
40 PM = I
41 M = PM
      PM = P(M)
      IF (PM - J) 41,43,42
42 P(M) = J
      P(J) = PM
      PM = J
43 W(J) = W(J) - CONST*T(JJ)
GO TO 30
!
!     SEARCH FOR THE K-TH PIVOT ELEMENT
!
50 IF (I .GT. N) GO TO 220
WMAX = DABS(W(I))
MAXI = I
PM = I
51 M = PM
PM = P(M)
IF (PM .GT. N) GO TO 60
WI = DABS(W(PM))
IF (WI .LE. WMAX) GO TO 51
   WMAX = WI
   MAXI = PM
   MAXIL = M
   GO TO 51
!
!     STORE THE PIVOT IN D
!
60 IF (WMAX .EQ. 0.D0) GO TO 220
D(K) = W(MAXI)
!
!     PERFORM THE COLUMN INTERCHANGE
!
IF (I .EQ. K) GO TO 70
IF (I .EQ. MAXI) GO TO 70
   P(MAXIL) = P(MAXI)
   GO TO 80
70 I = P(I)
!
80 W(MAXI) = W(K)
W(K) = 0.D0
LK = C(K)
LL = C(MAXI)
C(K) = LL
C(MAXI) = LK
IC(LK) = MAXI
IC(LL) = K
!
!     THE REMAINING ELEMENTS OF P FORM THE K-TH ROW OF U
!
IU(K) = JPTR + 1
90 IF (I .GT. N) GO TO 100
IF (W(I) .EQ. 0.D0) GO TO 91
   JPTR = JPTR + 1
   IF (JPTR .GT. MAX) GO TO 230
   T(JPTR) = W(I)/D(K)
   JT(JPTR) = C(I)
   W(I) = 0.D0
91 I = P(I)
GO TO 90
!
!     PREPARE FOR THE NEXT ROW
!
100 IT(K+1) = JPTR + 1
!
IERR = JPTR
RETURN
!
!     -------------------- ERROR RETURN --------------------
!
!     ROW R(K) IS NULL
!
200 IERR = -K
RETURN
!
!     ROW R(K) HAS A DUPLICATE ENTRY
!
210 IERR = -(N + K)
RETURN
!
!     ZERO PIVOT IN ROW R(K)
!
220 IERR = -(2*N + K)
RETURN
!
!     STORAGE FOR L AND U EXCEEDED ON ROW R(K)
!
230 IERR = -(3*N + K)
RETURN
END SUBROUTINE DSPLU

SUBROUTINE S1CND (N, A, IA, JA, R, C, MAX, COND, IWK, WK, IERR)
IMPLICIT NONE
INTENT(IN) A, IA, JA, MAX, N, R
INTENT(OUT) COND
INTENT(INOUT) C, IERR, IWK, WK
INTEGER IERR, MAX, N
REAL COND
INTEGER ISGN, ITER, IV, IX, J, JUMP, KASE
REAL AINORM, ANORM
!-----------------------------------------------------------------------
!              COMPUTATION OF THE L1 CONDITION NUMBER
!                       OF A SPARSE MATRIX A
!-----------------------------------------------------------------------
REAL A(*), WK(*)
INTEGER IA(*), JA(*), R(N), C(N), IWK(*)
!-----------------------
!     REAL WK(4*N + MAX)
!     INTEGER IWK(5*N + MAX + 2)
!-----------------------
COND = 0.0
CALL S1NRM (A, IA, JA, N, N, ANORM, WK)
IF (ANORM .EQ. 0.0) GO TO 50
!
IX = 2*N + MAX + 1
IV = IX + N
ISGN = 4*N + MAX + 3
!
KASE = 0
AINORM = 0.0
CALL SONEST (N, WK(IV), WK(IX), IWK(ISGN), AINORM, KASE, &
&ITER, J, JUMP)
CALL RSLV (0, N, A, IA, JA, WK(IX), R, C, MAX, WK(IX), &
&IWK(1), WK(1), IERR)
!
!     CHECK IF A IS SINGULAR OR IF THERE ARE ERRORS
!
IF (IERR .GT. 0) GO TO 20
IF (IABS(IERR) .LE. N) GO TO 50
IERR = IERR + N
IF (IABS(IERR) .LE. N) RETURN
IERR = IERR + N
IF (IABS(IERR) .LE. N) GO TO 50
RETURN
!
!     GENERAL LOOP TO ESTIMATE THE NORM  AINORM
!     OF THE INVERSE OF A
!
20 CALL SONEST (N, WK(IV), WK(IX), IWK(ISGN), AINORM, KASE, &
&ITER, J, JUMP)
IF (KASE .EQ. 0) GO TO 40
IF (KASE .NE. 1) GO TO 30
   CALL RSLV (1, N, A, IA, JA, WK(IX), R, C, MAX, WK(IX), &
&IWK(1), WK(1), IERR)
   GO TO 20
30 CALL TSLV (1, N, A, IA, JA, WK(IX), R, C, MAX, WK(IX), &
&IWK(1), WK(1), IERR)
GO TO 20
!
!     COMPUTE THE VALUE OF COND
!
40 COND = ANORM*AINORM
RETURN
!
!     SINGULAR CASE
!
50 IERR = 0
RETURN
END SUBROUTINE S1CND

SUBROUTINE DS1CND (N, A, IA, JA, R, C, MAX, COND, IWK, WK, IERR)
IMPLICIT NONE
INTENT(IN) A, IA, JA, MAX, N, R
INTENT(OUT) COND
INTENT(INOUT) C, IERR, IWK, WK
INTEGER IERR, MAX, N
INTEGER ISGN, ITER, IV, IX, J, JUMP, KASE
!-----------------------------------------------------------------------
!              COMPUTATION OF THE L1 CONDITION NUMBER
!                       OF A SPARSE MATRIX A
!-----------------------------------------------------------------------
DOUBLE PRECISION A(*), COND, WK(*), ANORM, AINORM
INTEGER IA(*), JA(*), R(N), C(N), IWK(*)
!-----------------------
!     DOUBLE PRECISION WK(4*N + MAX)
!     INTEGER IWK(5*N + MAX + 2)
!-----------------------
COND = 0.D0
CALL DS1NRM (A, IA, JA, N, N, ANORM, WK)
IF (ANORM .EQ. 0.D0) GO TO 50
!
IX = 2*N + MAX + 1
IV = IX + N
ISGN = 4*N + MAX + 3
!
KASE = 0
AINORM = 0.D0
CALL DONEST (N, WK(IV), WK(IX), IWK(ISGN), AINORM, KASE, &
&ITER, J, JUMP)
CALL DSLV (0, N, A, IA, JA, WK(IX), R, C, MAX, WK(IX), &
&IWK(1), WK(1), IERR)
!
!     CHECK IF A IS SINGULAR OR IF THERE ARE ERRORS
!
IF (IERR .GT. 0) GO TO 20
IF (IABS(IERR) .LE. N) GO TO 50
IERR = IERR + N
IF (IABS(IERR) .LE. N) RETURN
IERR = IERR + N
IF (IABS(IERR) .LE. N) GO TO 50
RETURN
!
!     GENERAL LOOP TO ESTIMATE THE NORM  AINORM
!     OF THE INVERSE OF A
!
20 CALL DONEST (N, WK(IV), WK(IX), IWK(ISGN), AINORM, KASE, &
&ITER, J, JUMP)
IF (KASE .EQ. 0) GO TO 40
IF (KASE .NE. 1) GO TO 30
   CALL DSLV (1, N, A, IA, JA, WK(IX), R, C, MAX, WK(IX), &
&IWK(1), WK(1), IERR)
   GO TO 20
30 CALL DTSLV (1, N, A, IA, JA, WK(IX), R, C, MAX, WK(IX), &
&IWK(1), WK(1), IERR)
GO TO 20
!
!     COMPUTE THE VALUE OF COND
!
40 COND = ANORM*AINORM
RETURN
!
!     SINGULAR CASE
!
50 IERR = 0
RETURN
END SUBROUTINE DS1CND

SUBROUTINE SONEST (N, V, X, ISGN, ANORM, KASE, ITER, J, JUMP)
IMPLICIT NONE
INTENT(IN) N
INTENT(INOUT) ANORM, ISGN, ITER, J, JUMP, KASE, V, X
INTEGER ITER, J, JUMP, KASE, N
REAL ANORM
INTEGER I, ITMAX, JLAST, L
REAL ALTSGN, ANRM, T
INTEGER ISAMAX
REAL SASUM
REAL V(N), X(N)
INTEGER ISGN(N)
!-----------------------------------------------------------------------
!
!     SONEST ESTIMATES THE 1-NORM OF A SQUARE, REAL MATRIX  A.
!     REVERSE COMMUNICATION IS USED FOR EVALUATING
!     MATRIX-VECTOR PRODUCTS.
!
!     ON ENTRY
!
!        N       THE ORDER OF THE MATRIX.  N .GE. 1.
!
!        KASE    INTEGER  (= 0).
!
!     ON INTERMEDIATE RETURNS
!
!        KASE    = 1 OR 2.
!
!        X       MUST BE OVERWRITTEN BY
!
!                     A*X,             IF KASE = 1,
!                     TRANSPOSE(A)*X,  IF KASE = 2,
!
!                AND SONEST MUST BE RE-CALLED, WITH ALL THE OTHER
!                PARAMETERS UNCHANGED.
!
!        ITER    NUMBER OF THE CURRENT ITERATION.
!
!     ON FINAL RETURN
!
!        KASE    = 0.
!
!        ANORM   CONTAINS AN ESTIMATE (A LOWER BOUND) FOR NORM(A).
!
!        V       = A*W,   WHERE  ANORM = NORM(V)/NORM(W)
!                         (W  IS NOT RETURNED).
!
!        ITER    NUMBER OF INTERATIONS TAKEN.
!
!        WRITTEN BY NICK HIGHAM, UNIVERSITY OF MANCHESTER. MODIFIED
!        BY A.H. MORRIS (NSWC).
!
!     REFERENCE
!     N.J. HIGHAM (1987) FORTRAN CODES FOR ESTIMATING
!     THE 1-NORM OF A REAL OR COMPLEX MATRIX, WITH APPLICATIONS
!     TO CONDITION  ESTIMATION, NUMERICAL ANALYSIS REPORT NO. 135,
!     UNIVERSITY OF MANCHESTER, MANCHESTER M13 9PL, ENGLAND.
!
!-----------------------------------------------------------------------
DATA ITMAX /5/
!
IF (KASE .NE. 0) GO TO 20
   T = 1.0/FLOAT(N)
   DO I = 1,N
      X(I) = T
   END DO
   ITER = 0
   KASE = 1
   JUMP = 1
   RETURN
20 GO TO (100, 200, 300, 400, 500), JUMP
!
!     ................ ENTRY   (JUMP = 1)
!     FIRST ITERATION.  X HAS BEEN OVERWRITTEN BY A*X.
!
100 ITER = 1
IF (N .GT. 1) GO TO 110
   V(1) = X(1)
   ANORM = ABS(V(1))
   GO TO 510
!
110 ANORM = SASUM(N,X,1)
DO I = 1,N
   ISGN(I) = 1
   IF (X(I) .LT. 0.0) ISGN(I) = -1
   X(I) = ISGN(I)
END DO
KASE = 2
JUMP = 2
RETURN
!
!     ................ ENTRY   (JUMP = 2)
!     FIRST ITERATION.  X HAS BEEN OVERWRITTEN BY TRANSPOSE(A)*X.
!
200 ITER = 2
J = ISAMAX(N,X,1)
!
!     MAIN LOOP - ITERATIONS 2,3,...,ITMAX.
!
210 DO I = 1,N
   X(I) = 0.0
END DO
X(J) = 1.0
KASE = 1
JUMP = 3
RETURN
!
!     ................ ENTRY   (JUMP = 3)
!     X HAS BEEN OVERWRITTEN BY A*X.
!
300 CALL SCOPY (N,X,1,V,1)
ANRM = ANORM
ANORM = SASUM(N,V,1)
DO I = 1,N
   L = 1
   IF (X(I) .LT. 0.0) L = -1
   IF (L .NE. ISGN(I)) GO TO 320
END DO
!     REPEATED SIGN VECTOR DETECTED, HENCE ALGORITHM HAS CONVERGED.
GO TO 410
!
!     TEST FOR CYCLING.
!
320 IF (ANORM .LE. ANRM) GO TO 410
!
DO I = 1,N
   ISGN(I) = 1
   IF (X(I) .LT. 0.0) ISGN(I) = -1
   X(I) = ISGN(I)
END DO
KASE = 2
JUMP = 4
RETURN
!
!     ................ ENTRY   (JUMP = 4)
!     X HAS BEEN OVERWRITTEN BY TRANSPOSE(A)*X.
!
400 JLAST = J
J = ISAMAX(N,X,1)
IF (X(JLAST) .EQ. ABS(X(J)) .OR. &
&ITER .GE. ITMAX) GO TO 410
ITER = ITER + 1
GO TO 210
!
!     ITERATION COMPLETE.  FINAL STAGE.
!
410 ALTSGN = 1.0
DO I = 1,N
   X(I) = ALTSGN * (1.0 + FLOAT(I-1)/FLOAT(N-1))
   ALTSGN = -ALTSGN
END DO
KASE = 1
JUMP = 5
RETURN
!
!     ................ ENTRY   (JUMP = 5)
!     X HAS BEEN OVERWRITTEN BY A*X.
!
500 ANRM = 2.0*SASUM(N,X,1)/FLOAT(3*N)
IF (ANRM .LE. ANORM) GO TO 510
   CALL SCOPY (N,X,1,V,1)
   ANORM = ANRM
510 KASE = 0
RETURN
END SUBROUTINE SONEST

SUBROUTINE DONEST (N, V, X, ISGN, ANORM, KASE, ITER, J, JUMP)
IMPLICIT NONE
INTENT(IN) N
INTENT(INOUT) ANORM, ISGN, ITER, J, JUMP, KASE, V, X
INTEGER ITER, J, JUMP, KASE, N
INTEGER I, ITMAX, JLAST, L
INTEGER IDAMAX
DOUBLE PRECISION ANORM, V(N), X(N)
INTEGER ISGN(N)
DOUBLE PRECISION ALTSGN, AN, ANM1, ANRM, T
DOUBLE PRECISION DASUM
!-----------------------------------------------------------------------
!
!     DONEST ESTIMATES THE 1-NORM OF A SQUARE, REAL MATRIX  A.
!     REVERSE COMMUNICATION IS USED FOR EVALUATING
!     MATRIX-VECTOR PRODUCTS.
!
!     ON ENTRY
!
!        N       THE ORDER OF THE MATRIX.  N .GE. 1.
!
!        KASE    INTEGER  (= 0).
!
!     ON INTERMEDIATE RETURNS
!
!        KASE    = 1 OR 2.
!
!        X       MUST BE OVERWRITTEN BY
!
!                     A*X,             IF KASE = 1,
!                     TRANSPOSE(A)*X,  IF KASE = 2,
!
!                AND DONEST MUST BE RE-CALLED, WITH ALL THE OTHER
!                PARAMETERS UNCHANGED.
!
!        ITER    NUMBER OF THE CURRENT ITERATION.
!
!     ON FINAL RETURN
!
!        KASE    = 0.
!
!        ANORM   CONTAINS AN ESTIMATE (A LOWER BOUND) FOR NORM(A).
!
!        V       = A*W,   WHERE  ANORM = NORM(V)/NORM(W)
!                         (W  IS NOT RETURNED).
!
!        ITER    NUMBER OF INTERATIONS TAKEN.
!
!        WRITTEN BY NICK HIGHAM, UNIVERSITY OF MANCHESTER. MODIFIED
!        BY A.H. MORRIS (NSWC).
!
!     REFERENCE
!     N.J. HIGHAM (1987) FORTRAN CODES FOR ESTIMATING
!     THE 1-NORM OF A REAL OR COMPLEX MATRIX, WITH APPLICATIONS
!     TO CONDITION  ESTIMATION, NUMERICAL ANALYSIS REPORT NO. 135,
!     UNIVERSITY OF MANCHESTER, MANCHESTER M13 9PL, ENGLAND.
!
!-----------------------------------------------------------------------
DATA ITMAX /5/
!
AN = N
ANM1 = N - 1
IF (KASE .NE. 0) GO TO 20
   T = 1.D0/AN
   DO I = 1,N
      X(I) = T
   END DO
   ITER = 0
   KASE = 1
   JUMP = 1
   RETURN
20 GO TO (100, 200, 300, 400, 500), JUMP
!
!     ................ ENTRY   (JUMP = 1)
!     FIRST ITERATION.  X HAS BEEN OVERWRITTEN BY A*X.
!
100 ITER = 1
IF (N .GT. 1) GO TO 110
   V(1) = X(1)
   ANORM = DABS(V(1))
   GO TO 510
!
110 ANORM = DASUM(N,X,1)
DO I = 1,N
   ISGN(I) = 1
   IF (X(I) .LT. 0.D0) ISGN(I) = -1
   X(I) = ISGN(I)
END DO
KASE = 2
JUMP = 2
RETURN
!
!     ................ ENTRY   (JUMP = 2)
!     FIRST ITERATION.  X HAS BEEN OVERWRITTEN BY TRANSPOSE(A)*X.
!
200 ITER = 2
J = IDAMAX(N,X,1)
!
!     MAIN LOOP - ITERATIONS 2,3,...,ITMAX.
!
210 DO I = 1,N
   X(I) = 0.D0
END DO
X(J) = 1.D0
KASE = 1
JUMP = 3
RETURN
!
!     ................ ENTRY   (JUMP = 3)
!     X HAS BEEN OVERWRITTEN BY A*X.
!
300 CALL DCOPY (N,X,1,V,1)
ANRM = ANORM
ANORM = DASUM(N,V,1)
DO I = 1,N
   L = 1
   IF (X(I) .LT. 0.D0) L = -1
   IF (L .NE. ISGN(I)) GO TO 320
END DO
!     REPEATED SIGN VECTOR DETECTED, HENCE ALGORITHM HAS CONVERGED.
GO TO 410
!
!     TEST FOR CYCLING.
!
320 IF (ANORM .LE. ANRM) GO TO 410
!
DO I = 1,N
   ISGN(I) = 1
   IF (X(I) .LT. 0.D0) ISGN(I) = -1
   X(I) = ISGN(I)
END DO
KASE = 2
JUMP = 4
RETURN
!
!     ................ ENTRY   (JUMP = 4)
!     X HAS BEEN OVERWRITTEN BY TRANSPOSE(A)*X.
!
400 JLAST = J
J = IDAMAX(N,X,1)
IF (X(JLAST) .EQ. DABS(X(J)) .OR. &
&ITER .GE. ITMAX) GO TO 410
ITER = ITER + 1
GO TO 210
!
!     ITERATION COMPLETE.  FINAL STAGE.
!
410 ALTSGN = 1.D0
DO I = 1,N
   T = I - 1
   X(I) = ALTSGN * (1.D0 + T/ANM1)
   ALTSGN = -ALTSGN
END DO
KASE = 1
JUMP = 5
RETURN
!
!     ................ ENTRY   (JUMP = 5)
!     X HAS BEEN OVERWRITTEN BY A*X.
!
500 ANRM = 2.D0*DASUM(N,X,1)/(3.D0*AN)
IF (ANRM .LE. ANORM) GO TO 510
   CALL DCOPY (N,X,1,V,1)
   ANORM = ANRM
510 KASE = 0
RETURN
END SUBROUTINE DONEST

SUBROUTINE CSPSLV (N,A,IA,JA,B,R,C,MAX,X,ITEMP,RTEMP,IERR)
IMPLICIT NONE
INTENT(IN) A, B, IA, JA, MAX, N, R
INTENT(OUT) IERR
INTENT(INOUT) C, ITEMP, RTEMP, X
INTEGER IERR, MAX, N
INTEGER K, L
!-----------------------------------------------------------------------
!                 SOLUTION OF COMPLEX SPARSE MATRICES
!-----------------------------------------------------------------------
!  SPSLV CALLS CNSPIV WHICH USES SPARSE GAUSSIAN ELIMINATION WITH
!  COLUMN INTERCHANGES TO SOLVE THE LINEAR SYSTEM A X = B.  THE
!  ELIMINATION PHASE PERFORMS ROW OPERATIONS ON A AND B TO OBTAIN
!  A UNIT UPPER TRIANGULAR MATRIX U AND A VECTOR Y.  THE SOLUTION
!  PHASE SOLVES U X = Y.
!
!  INPUT ARGUMENTS---
!
!  N      INTEGER NUMBER OF EQUATIONS AND UNKNOWNS
!
!  A      COMPLEX ARRAY WITH ONE ENTRY PER NONZERO IN A, CONTAINING
!         THE ACTUAL NONZEROS.  (SEE STORAGE DESCRIPTION BELOW)
!
!  IA     INTEGER ARRAY OF N+1 ENTRIES CONTAINING ROW POINTERS TO A
!         (SEE MATRIX STORAGE DESCRIPTION BELOW)
!
!  JA     INTEGER ARRAY WITH ONE ENTRY PER NONZERO IN A, CONTAINING
!         COLUMN NUMBERS OF THE NONZEROS OF A.  (SEE MATRIX STORAGE
!         DESCRIPTION BELOW)
!
!  B      COMPLEX ARRAY OF N ENTRIES CONTAINING RIGHT HAND SIDE DATA
!
!  R      INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF THE
!         ROWS OF A (I.E., THE ELIMINATION ORDER FOR THE EQUATIONS)
!
!  C      INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF THE
!         COLUMNS OF A.  C IS ALSO AN OUTPUT ARGUMENT
!
!  MAX    INTEGER NUMBER SPECIFYING MAXIMUM NUMBER OF OFF-DIAGONAL
!         NONZERO ENTRIES OF U WHICH MAY BE STORED
!
!  ITEMP  INTEGER ARRAY OF 3*N + MAX + 2 ENTRIES, FOR INTERNAL USE
!
!  RTEMP  COMPLEX ARRAY OF N + MAX ENTRIES FOR INTERNAL USE
!
!
!  OUTPUT ARGUMENTS---
!
!  C      INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF THE
!         COLUMNS OF U.  C IS ALSO AN INPUT ARGUMENT
!
!  X      COMPLEX ARRAY OF N ENTRIES CONTAINING THE SOLUTION VECTOR
!
!  IERR   INTEGER NUMBER WHICH INDICATES ERROR CONDITIONS OR
!         THE ACTUAL NUMBER OF OFF-DIAGONAL ENTRIES IN U (FOR
!         SUCCESSFUL COMPLETION)
!
!         IERR VALUES ARE---
!
!         0 LT IERR             SUCCESSFUL COMPLETION. IERR=MAX(1,M)
!                               WHERE M IS THE NUMBER OF OFF-DIAGONAL
!                               NONZERO ENTRIES OF U.
!
!         IERR = 0              ERROR.  N IS LESS THAN OR EQUAL TO 0
!
!         -N LE IERR LT 0       ERROR.  ROW NUMBER IABS(IERR) OF A IS
!                               IS NULL
!
!         -2*N LE IERR LT -N    ERROR.  ROW NUMBER IABS(IERR+N) HAS A
!                               DUPLICATE ENTRY
!
!         -3*N LE IERR LT -2*N  ERROR.  ROW NUMBER IABS(IERR+2*N)
!                               HAS A ZERO PIVOT
!
!         -4*N LE IERR LT -3*N  ERROR.  ROW NUMBER IABS(IERR+3*N)
!                               EXCEEDS STORAGE
!
!
!  STORAGE OF SPARSE MATRICES---
!
!  THE SPARSE MATRIX A IS STORED USING THREE ARRAYS IA, JA, AND A.
!  THE ARRAY A CONTAINS THE NONZEROS OF THE MATRIX ROW-BY-ROW, NOT
!  NECESSARILY IN ORDER OF INCREASING COLUMN NUMBER.  THE ARRAY JA
!  CONTAINS THE COLUMN NUMBERS CORRESPONDING TO THE NONZEROS STORED
!  IN THE ARRAY A (I.E., IF THE NONZERO STORED IN A(K) IS IN
!  COLUMN J, THEN JA(K) = J).  THE ARRAY IA CONTAINS POINTERS TO THE
!  ROWS OF NONZEROS/COLUMN INDICES IN THE ARRAY A/JA (I.E.,
!  A(IA(I))/JA(IA(I)) IS THE FIRST ENTRY FOR ROW I IN THE ARRAY A/JA).
!  IA(N+1) IS SET SO THAT IA(N+1) - IA(1) = THE NUMBER OF NONZERO
!  ELEMENTS IN A.
!------------------------
COMPLEX A(*), B(N), X(N), RTEMP(*)
INTEGER IA(*), JA(*), R(N), C(N), ITEMP(*)
INTEGER IU, JU, U, Y, P
!
IERR = 0
IF (N .LE. 0) RETURN
!
!  SET INDICES TO DIVIDE TEMPORARY STORAGE FOR CNSPIV
!
Y = 1
U = Y + N
P = N + 1
IU = P + N + 1
JU = IU + N + 1
!
!  COMPUTE THE INVERSE PERMUTATION OF C
!
DO K = 1,N
   L = C(K)
   ITEMP(L) = K
END DO
!
!  CALL CNSPIV TO PERFORM COMPUTATIONS
!
CALL CNSPIV (N,IA,JA,A,B,MAX,R,C,ITEMP(1),X,RTEMP(Y),ITEMP(P), &
&ITEMP(IU),ITEMP(JU),RTEMP(U),IERR)
IF (IERR .EQ. 0) IERR = 1
RETURN
END SUBROUTINE CSPSLV

SUBROUTINE CNSPIV (N,IA,JA,A,B,MAX,R,C,IC,X,Y,P,IU,JU,U,IERR)
IMPLICIT NONE
INTENT(IN) A, B, IA, JA, MAX, N, R
INTENT(INOUT) C, IC, IERR, IU, JU, P, U, X, Y
INTEGER IERR, MAX, N
INTEGER I, J, JAJ, JMAX, JMIN, JUJ, JUPTR, K, MAXC, MAXCL, NZCNT
!
!
!  CNSPIV USES SPARSE GAUSSIAN ELIMINATION WITH
!  COLUMN INTERCHANGES TO SOLVE THE LINEAR SYSTEM A X = B.  THE
!  ELIMINATION PHASE PERFORMS ROW OPERATIONS ON A AND B TO OBTAIN
!  A UNIT UPPER TRIANGULAR MATRIX U AND A VECTOR Y.  THE SOLUTION
!  PHASE SOLVES U X = Y.
!
!
!  SEE CSPSLV FOR DESCRIPTIONS OF ALL INPUT AND OUTPUT ARGUMENTS
!  OTHER THAN THOSE DESCRIBED BELOW
!
!  IC  INTEGER ARRAY OF N ENTRIES WHICH IS THE INVERSE OF C
!      (I.E., IC(C(I)) = I). IC IS BOTH AN INPUT AND OUTPUT
!      ARGUMENT.
!
!  INPUT ARGUMENTS (USED INTERNALLY ONLY)---
!
!  Y   COMPLEX ARRAY OF N ENTRIES USED TO COMPUTE THE UPDATED
!      RIGHT HAND SIDE
!
!  P   INTEGER ARRAY OF N+1 ENTRIES USED FOR A LINKED LIST.
!      P(N+1) IS THE LIST HEADER, AND THE ENTRY FOLLOWING
!      P(K) IS IN P(P(K)).  THUS, P(N+1) IS THE FIRST DATA
!      ITEM, P(P(N+1)) IS THE SECOND, ETC.  A POINTER OF
!      N+1 MARKS THE END OF THE LIST
!
!  IU  INTEGER ARRAY OF N+1 ENTRIES USED FOR ROW POINTERS TO U
!      (SEE MATRIX STORAGE DESCRIPTION BELOW)
!
!  JU  INTEGER ARRAY OF MAX ENTRIES USED FOR COLUMN NUMBERS OF
!      THE NONZEROS IN THE STRICT UPPER TRIANGLE OF U.  (SEE
!      MATRIX STORAGE DESCRIPTION BELOW)
!
!  U   COMPLEX ARRAY OF MAX ENTRIES USED FOR THE ACTUAL NONZEROS IN
!      THE STRICT UPPER TRIANGLE OF U.  (SEE MATRIX STORAGE
!      DESCRIPTION BELOW)
!
!
!  STORAGE OF SPARSE MATRICES---
!
!  THE SPARSE MATRIX A IS STORED USING THREE ARRAYS IA, JA, AND A.
!  THE ARRAY A CONTAINS THE NONZEROS OF THE MATRIX ROW-BY-ROW, NOT
!  NECESSARILY IN ORDER OF INCREASING COLUMN NUMBER.  THE ARRAY JA
!  CONTAINS THE COLUMN NUMBERS CORRESPONDING TO THE NONZEROS STORED
!  IN THE ARRAY A (I.E., IF THE NONZERO STORED IN A(K) IS IN
!  COLUMN J, THEN JA(K) = J).  THE ARRAY IA CONTAINS POINTERS TO THE
!  ROWS OF NONZEROS/COLUMN INDICES IN THE ARRAY A/JA (I.E.,
!  A(IA(I))/JA(IA(I)) IS THE FIRST ENTRY FOR ROW I IN THE ARRAY A/JA).
!  IA(N+1) IS SET SO THAT IA(N+1) - IA(1) = THE NUMBER OF NONZEROS IN
!  A.  IU, JU, AND U ARE USED IN A SIMILAR WAY TO STORE THE STRICT UPPER
!  TRIANGLE OF U, EXCEPT THAT JU ACTUALLY CONTAINS C(J) INSTEAD OF J
!
!
COMPLEX A(*), B(N), U(MAX), X(N), Y(N)
COMPLEX DK, LKI, ONE, YK, ZERO
REAL XPV, XPVMAX
INTEGER C(N), IA(*), IC(N), IU(*), JA(*), JU(MAX), P(*), R(N)
INTEGER CK, PK, PPK, PV, V, VI, VJ, VK
!
ONE = (1.0,0.0)
ZERO = (0.0,0.0)
!
!  INITIALIZE WORK STORAGE AND POINTERS TO JU
!
DO J = 1,N
  X(J) = ZERO
END DO
IU(1) = 1
JUPTR = 0
!
!  PERFORM SYMBOLIC AND NUMERIC FACTORIZATION ROW BY ROW
!  VK (VI,VJ) IS THE GRAPH VERTEX FOR ROW K (I,J) OF U
!
do 170 K = 1,N
!
!  INITIALIZE LINKED LIST AND FREE STORAGE FOR THIS ROW
!  THE R(K)-TH ROW OF A BECOMES THE K-TH ROW OF U.
!
  P(N+1) = N+1
  VK = R(K)
!
!  SET UP ADJACENCY LIST FOR VK, ORDERED IN
!  CURRENT COLUMN ORDER OF U.  THE LOOP INDEX
!  GOES DOWNWARD TO EXPLOIT ANY COLUMNS
!  FROM A IN CORRECT RELATIVE ORDER
!
  JMIN = IA(VK)
  JMAX = IA(VK+1) - 1
  IF (JMIN .GT. JMAX)  GO TO 1002
  J = JMAX
20 JAJ = JA(J)
    VJ = IC(JAJ)
!
!  STORE A(K,J) IN WORK VECTOR
!
    X(VJ) = A(J)
!  THIS CODE INSERTS VJ INTO ADJACENCY LIST OF VK
    PPK = N+1
30 PK = PPK
    PPK = P(PK)
    IF (PPK - VJ)  30,1003,40
40 P(VJ) = PPK
    P(PK) = VJ
    J = J - 1
    IF (J .GE. JMIN) GO TO 20
!
!  THE FOLLOWING CODE COMPUTES THE K-TH ROW OF U
!
  VI = N+1
  YK = B(VK)
50 VI = P(VI)
  IF (VI .GE. K) GO TO 110
!
!  VI LT VK -- PROCESS THE L(K,I) ELEMENT AND MERGE THE
!  ADJACENCY OF VI WITH THE ORDERED ADJACENCY OF VK
!
  LKI = - X(VI)
  X(VI) = ZERO
!
!  ADJUST RIGHT HAND SIDE TO REFLECT ELIMINATION
!
  YK = YK + LKI * Y(VI)
  PPK = VI
  JMIN = IU(VI)
  JMAX = IU(VI+1) - 1
  IF (JMIN .GT. JMAX)  GO TO 50
  DO J = JMIN,JMAX
    JUJ = JU(J)
    VJ = IC(JUJ)
!
!  IF VJ IS ALREADY IN THE ADJACENCY OF VK,
!  SKIP THE INSERTION
!
    IF (X(VJ) .NE. ZERO)  GO TO 90
!
!  INSERT VJ IN ADJACENCY LIST OF VK.
!  RESET PPK TO VI IF WE HAVE PASSED THE CORRECT
!  INSERTION SPOT.  (THIS HAPPENS WHEN THE ADJACENCY OF
!  VI IS NOT IN CURRENT COLUMN ORDER DUE TO PIVOTING.)
!
    IF (VJ - PPK) 60,90,70
60 PPK = VI
70 PK = PPK
    PPK = P(PK)
    IF (PPK - VJ)  70,90,80
80 P(VJ) = PPK
    P(PK) = VJ
    PPK = VJ
!
!  COMPUTE L(K,J) = L(K,J) - L(K,I)*U(I,J) FOR L(K,I) NONZERO
!  COMPUTE U*(K,J) = U*(K,J) - L(K,I)*U(I,J) FOR U(K,J) NONZERO
!  (U*(K,J) = U(K,J)*D(K,K))
!
90 X(VJ) = X(VJ) + LKI * U(J)
  END DO
  GO TO 50
!
!  PIVOT--INTERCHANGE LARGEST ENTRY OF K-TH ROW OF U WITH
!  THE DIAGONAL ENTRY.
!
!  FIND LARGEST ENTRY, COUNTING OFF-DIAGONAL NONZEROS
!
110 IF (VI .GT. N) GO TO 1004
  XPVMAX = ABS(REAL(X(VI))) + ABS(AIMAG(X(VI)))
  MAXC = VI
  NZCNT = 0
  PV = VI
120 V = PV
    PV = P(PV)
    IF (PV .GT. N) GO TO 130
    NZCNT = NZCNT + 1
    XPV = ABS(REAL(X(PV))) + ABS(AIMAG(X(PV)))
    IF (XPV .LE. XPVMAX) GO TO 120
    XPVMAX = XPV
    MAXC = PV
    MAXCL = V
    GO TO 120
130 IF (XPVMAX .EQ. 0.0) GO TO 1004
!
!  IF VI = K, THEN THERE IS AN ENTRY FOR DIAGONAL
!  WHICH MUST BE DELETED.  OTHERWISE, DELETE THE
!  ENTRY WHICH WILL BECOME THE DIAGONAL ENTRY
!
  IF (VI .EQ. K) GO TO 140
  IF (VI .EQ. MAXC) GO TO 140
  P(MAXCL) = P(MAXC)
  GO TO 150
140 VI = P(VI)
!
!  COMPUTE D(K) = 1/L(K,K) AND PERFORM INTERCHANGE.
!
150 DK = ONE / X(MAXC)
  X(MAXC) = X(K)
  I = C(K)
  C(K) = C(MAXC)
  C(MAXC) = I
  CK = C(K)
  IC(CK) = K
  IC(I) = MAXC
  X(K) = ZERO
!
!  UPDATE RIGHT HAND SIDE.
!
  Y(K) = YK * DK
!
!  COMPUTE VALUE FOR IU(K+1) AND CHECK FOR STORAGE OVERFLOW
!
  IU(K+1) = IU(K) + NZCNT
  IF (IU(K+1) .GT. MAX+1) GO TO 1005
!
!  MOVE COLUMN INDICES FROM LINKED LIST TO JU.
!  COLUMNS ARE STORED IN CURRENT ORDER WITH ORIGINAL
!  COLUMN NUMBER (C(J)) STORED FOR CURRENT COLUMN J
!
  IF (VI .GT. N)  GO TO 170
  J = VI
160 JUPTR = JUPTR + 1
    JU(JUPTR) = C(J)
    U(JUPTR) = X(J) * DK
    X(J) = ZERO
    J = P(J)
    IF (J .LE. N) GO TO 160
170 CONTINUE
!
!  BACKSOLVE U X = Y, AND REORDER X TO CORRESPOND WITH A
!
K = N
DO I = 1,N
  YK = Y(K)
  JMIN = IU(K)
  JMAX = IU(K+1) - 1
  IF (JMIN .GT. JMAX)  GO TO 190
  DO J = JMIN,JMAX
    JUJ = JU(J)
    JUJ = IC(JUJ)
    YK = YK - U(J) * Y(JUJ)
  END DO
190 Y(K) = YK
  CK = C(K)
  X(CK) = YK
  K = K - 1
END DO
!
!  RETURN WITH IERR = NUMBER OF OFF-DIAGONAL NONZEROS IN U
!
IERR = IU(N+1) - IU(1)
RETURN
!
!  ERROR RETURNS
!
!  ROW K OF A IS NULL
!
1002 IERR = -K
RETURN
!
!  ROW K OF A HAS A DUPLICATE ENTRY
!
1003 IERR = -(N+K)
RETURN
!
!  ZERO PIVOT IN ROW K
!
1004 IERR = -(2*N+K)
RETURN
!
!  STORAGE FOR U EXCEEDED ON ROW K
!
1005 IERR = -(3*N+K)
RETURN
END SUBROUTINE CNSPIV

SUBROUTINE CSLV (M0,N,A,IA,JA,B,R,C,MAX,X,IWK,WK,IERR)
IMPLICIT NONE
INTENT(IN) A, B, IA, JA, M0, MAX, N, R
INTENT(INOUT) C, IERR, IWK, WK, X
INTEGER IERR, M0, MAX, N
INTEGER IT, IU, JT, K, L
!-----------------------------------------------------------------------
!                 SOLUTION OF COMPLEX SPARSE MATRICES
!-----------------------------------------------------------------------
!     CSLV EMPLOYS GAUSSIAN ELIMINATION WITH COLUMN INTERCHANGES TO
!     SOLVE THE NXN COMPLEX SYSTEM AX = B. THE ARGUMENT M0 SPECIFIES
!     IF CSLV IS BEING CALLED FOR THE FIRST TIME, OR IF IT IS BEING
!     RECALLED WHERE A IS THE SAME MATRIX BUT B HAS BEEN MODIFIED.
!     ON AN INITIAL CALL TO THE ROUTINE (WHEN M0=0) THE LU DECOMPO-
!     SITION OF A IS OBTAINED WHERE U IS A UNIT UPPER TRIANGULAR
!     MATRIX. THEN THE EQUATIONS ARE SOLVED. ON SUBSEQUENT CALLS
!     (WHEN M0.NE.0) THE EQUATIONS ARE SOLVED USING THE DECOMPOSITION
!     OBTAINED ON THE INITIAL CALL TO CSLV.
!
!
!     INPUT ARGUMENTS WHEN M0=0 ---
!
!     N        NUMBER OF EQUATIONS AND UNKNOWNS.
!
!     A,IA,JA  THE COMPLEX MATRIX A STORED IN SPARSE FORM.
!
!     B        COMPLEX ARRAY OF N ENTRIES CONTAINING THE RIGHT HAND
!              SIDE DATA.
!
!     R        INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF
!              THE ROWS OF A.
!
!     C        INTEGER ARRAY OF N ENTRIES SPECIFYING A SUGGESTED
!              ORDER OF THE COLUMNS. C IS ALSO AN OUTPUT ARGUMENT.
!
!     MAX      INTEGER SPECIFYING THE MAXIMUM NUMBER OF OFF-DIAGONAL
!              NONZERO ENTRIES OF L AND U WHICH MAY BE STORED.
!
!
!     OUTPUT ARGUMENTS WHEN M0=0 ---
!
!     C        INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF
!              THE COLUMNS THAT WAS SELECTED BY THE ROUTINE.
!
!     X        COMPLEX ARRAY OF N ENTRIES CONTAINING THE SOLUTION.
!              B AND X MAY SHARE THE SAME STORAGE AREA.
!
!     IERR     INTEGER SPECIFYING THE STATUS OF THE RESULTS. IF THE
!              SOLUTION OF AX = B IS OBTAINED THEN IERR = MAX(1,M)
!              WHERE M IS THE TOTAL NUMBER OF OFF-DIAGONAL NONZERO
!              ENTRIES OF L AND U. OTHERWISE IERR.LE.0.
!
!
!     GENERAL STORAGE AREAS ---
!
!     IWK      INTEGER ARRAY OF DIMENSION 4*N + MAX + 2.
!
!     WK       COMPLEX ARRAY OF DIMENSION 2*N + MAX.
!
!
!     AFTER AN INITIAL CALL TO CSLV, THE ROUTINE MAY BE RECALLED WITH
!     M0.NE.0 FOR A NEW B. WHEN M0.NE.0 IT IS ASSUMED THAT N,A,IA,JA,
!     R,C,IWK,WK HAVE NOT BEEN MODIFIED. THE ROUTINE RETRIEVES THE LU
!     DECOMPOSITION WHICH WAS OBTAINED ON THE INITIAL CALL TO CSLV
!     AND SOLVES THE NEW EQUATIONS AX = B. IN THIS CASE A,IA,JA,MAX,
!     AND IERR ARE NOT REFERENCED.
!-----------------------------------------------------------------------
COMPLEX A(*), B(N), X(N), WK(*)
INTEGER IA(*), JA(*), IWK(*)
INTEGER R(N), C(N), Y, T, P
!
!     SET INDICES TO DIVIDE TEMPORARY STORAGE
!
Y = N + 1
T = Y + N
P = N + 1
IT = P + N + 1
IU = IT + N + 1
JT = IU + N
IF (M0 .NE. 0) GO TO 20
!
!     COMPUTE THE INVERSE PERMUTATION OF C
!
IERR = 0
IF (N .LE. 0) RETURN
DO K = 1,N
   L = C(K)
   IWK(L) = K
END DO
!
!     OBTAIN THE LU DECOMPOSITION OF A
!
CALL CSPLU (A,IA,JA,R,C,IWK(1),N,MAX,WK(1),WK(T),IWK(IT),IWK(JT), &
&IWK(IU),WK(Y),IWK(P),IERR)
IF (IERR .LT. 0) RETURN
IERR = MAX0(1,IERR)
!
!     SOLVE THE SYSTEM OF EQUATIONS
!
20 CALL CSLV1 (N,R,C,IWK(1),WK(1),WK(T),IWK(IT),IWK(JT),IWK(IU), &
&B,X,WK(Y))
RETURN
END SUBROUTINE CSLV

SUBROUTINE CSLV1 (N,R,C,IC,D,T,IT,JT,IU,B,X,Y)
IMPLICIT NONE
INTENT(IN) B, C, D, IC, IT, IU, JT, N, R, T
INTENT(INOUT) X, Y
INTEGER N
INTEGER I, J, JJ, JMAX, JMIN, K, LJ, LK
INTEGER R(N), C(N), IC(N)
INTEGER IT(*), JT(*), IU(N)
COMPLEX B(N), D(N), T(*), X(N), Y(N), SUM
!
!            SOLVE LY = B BY FORWARD SUBSTITUTION
!
do 11 K = 1,N
   LK = R(K)
   SUM = B(LK)
   JMIN = IT(K)
   JMAX = IU(K) - 1
   IF (JMIN .GT. JMAX) GO TO 11
   DO JJ = JMIN,JMAX
      LJ = JT(JJ)
      J = IC(LJ)
      SUM = SUM - T(JJ)*Y(J)
   END DO
11 Y(K) = SUM/D(K)
!
!            SOLVE UX = B BY BACKWARD SUBSTITUTION
!             AND REORDER X TO CORRESPOND WITH A
!
K = N
DO I = 1,N
   SUM = Y(K)
   JMIN = IU(K)
   JMAX = IT(K+1) - 1
   IF (JMIN .GT. JMAX) GO TO 21
   DO JJ = JMIN,JMAX
      LJ = JT(JJ)
      J = IC(LJ)
      SUM = SUM - T(JJ)*Y(J)
   END DO
21 Y(K) = SUM
   LK = C(K)
   X(LK) = Y(K)
   K = K - 1
END DO
RETURN
END SUBROUTINE CSLV1

SUBROUTINE CTSLV (M0,N,A,IA,JA,B,R,C,MAX,X,IWK,WK,IERR)
IMPLICIT NONE
INTENT(IN) A, B, IA, JA, M0, MAX, N, R
INTENT(INOUT) C, IERR, IWK, WK, X
INTEGER IERR, M0, MAX, N
INTEGER IT, IU, JT, K, L
!-----------------------------------------------------------------------
!                 SOLUTION OF COMPLEX SPARSE MATRICES
!-----------------------------------------------------------------------
!     CTSLV EMPLOYS GAUSSIAN ELIMINATION WITH COLUMN INTERCHANGES TO
!     SOLVE THE NXN COMPLEX SYSTEM XA = B. THE ARGUMENT M0 SPECIFIES
!     IF CTSLV IS BEING CALLED FOR THE FIRST TIME, OR IF IT IS BEING
!     RECALLED WHERE A IS THE SAME MATRIX BUT B HAS BEEN MODIFIED.
!     ON AN INITIAL CALL TO THE ROUTINE (WHEN M0=0) THE LU DECOMPO-
!     SITION OF A IS OBTAINED WHERE U IS A UNIT UPPER TRIANGULAR
!     MATRIX. THEN THE EQUATIONS ARE SOLVED. ON SUBSEQUENT CALLS
!     (WHEN M0.NE.0) THE EQUATIONS ARE SOLVED USING THE DECOMPOSITION
!     OBTAINED ON THE INITIAL CALL TO CTSLV.
!
!
!     INPUT ARGUMENTS WHEN M0=0 ---
!
!     N        NUMBER OF EQUATIONS AND UNKNOWNS.
!
!     A,IA,JA  THE COMPLEX MATRIX A STORED IN SPARSE FORM.
!
!     B        COMPLEX ARRAY OF N ENTRIES CONTAINING THE RIGHT HAND
!              SIDE DATA.
!
!     R        INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF
!              THE ROWS OF A.
!
!     C        INTEGER ARRAY OF N ENTRIES SPECIFYING A SUGGESTED
!              ORDER OF THE COLUMNS. C IS ALSO AN OUTPUT ARGUMENT.
!
!     MAX      INTEGER SPECIFYING THE MAXIMUM NUMBER OF OFF-DIAGONAL
!              NONZERO ENTRIES OF L AND U WHICH MAY BE STORED.
!
!
!     OUTPUT ARGUMENTS WHEN M0=0 ---
!
!     C        INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF
!              THE COLUMNS THAT WAS SELECTED BY THE ROUTINE.
!
!     X        COMPLEX ARRAY OF N ENTRIES CONTAINING THE SOLUTION.
!              B AND X MAY SHARE THE SAME STORAGE AREA.
!
!     IERR     INTEGER SPECIFYING THE STATUS OF THE RESULTS. IF THE
!              SOLUTION OF AX = B IS OBTAINED THEN IERR = MAX(1,M)
!              WHERE M IS THE TOTAL NUMBER OF OFF-DIAGONAL NONZERO
!              ENTRIES OF L AND U. OTHERWISE IERR.LE.0.
!
!
!     GENERAL STORAGE AREAS ---
!
!     IWK      INTEGER ARRAY OF DIMENSION 4*N + MAX + 2.
!
!     WK       COMPLEX ARRAY OF DIMENSION 2*N + MAX.
!
!
!     AFTER AN INITIAL CALL TO CTSLV, THE ROUTINE MAY BE RECALLED WITH
!     M0.NE.0 FOR A NEW B. WHEN M0.NE.0 IT IS ASSUMED THAT N,A,IA,JA,
!     R,C,IWK,WK HAVE NOT BEEN MODIFIED. THE ROUTINE RETRIEVES THE LU
!     DECOMPOSITION WHICH WAS OBTAINED ON THE INITIAL CALL TO CTSLV
!     AND SOLVES THE NEW EQUATIONS XA = B. IN THIS CASE A,IA,JA,MAX,
!     AND IERR ARE NOT REFERENCED.
!-----------------------------------------------------------------------
COMPLEX A(*), B(N), X(N), WK(*)
INTEGER IA(*), JA(*), IWK(*)
INTEGER R(N), C(N), Y, T, P
!
!     SET INDICES TO DIVIDE TEMPORARY STORAGE
!
Y = N + 1
T = Y + N
P = N + 1
IT = P + N + 1
IU = IT + N + 1
JT = IU + N
IF (M0 .NE. 0) GO TO 20
!
!     COMPUTE THE INVERSE PERMUTATION OF C
!
IERR = 0
IF (N .LE. 0) RETURN
DO K = 1,N
   L = C(K)
   IWK(L) = K
END DO
!
!     OBTAIN THE LU DECOMPOSITION OF A
!
CALL CSPLU (A,IA,JA,R,C,IWK(1),N,MAX,WK(1),WK(T),IWK(IT),IWK(JT), &
&IWK(IU),WK(Y),IWK(P),IERR)
IF (IERR .LT. 0) RETURN
IERR = MAX0(1,IERR)
!
!     SOLVE THE SYSTEM OF EQUATIONS
!
20 CALL CTSLV1 (N,R,C,IWK(1),WK(1),WK(T),IWK(IT),IWK(JT),IWK(IU), &
&B,X,WK(Y))
RETURN
END SUBROUTINE CTSLV

SUBROUTINE CTSLV1 (N,R,C,IC,D,T,IT,JT,IU,B,X,Y)
IMPLICIT NONE
INTENT(IN) B, C, D, IC, IT, IU, JT, N, R, T
INTENT(INOUT) X, Y
INTEGER N
INTEGER I, J, JJ, JMAX, JMIN, K, LJ, LK
INTEGER R(N), C(N), IC(N)
INTEGER IT(*), JT(*), IU(N)
COMPLEX B(N), D(N), T(*), X(N), Y(N)
!
!            SOLVE YU = B BY FORWARD SUBSTITUTION
!
DO K = 1,N
   LK = C(K)
   Y(K) = B(LK)
END DO
!
do 21 K = 1,N
   IF (Y(K) .EQ. (0.0, 0.0)) GO TO 21
   JMIN = IU(K)
   JMAX = IT(K+1) - 1
   IF (JMIN .GT. JMAX) GO TO 21
   DO JJ = JMIN,JMAX
      LJ = JT(JJ)
      J = IC(LJ)
      Y(J) = Y(J) - T(JJ)*Y(K)
   END DO
21 CONTINUE
!
!            SOLVE XL = Y BY BACKWARD SUBSTITUTION
!
X(N) = Y(N)/D(N)
IF (N .EQ. 1) RETURN
!
K = N
Y(N) = X(N)
DO I = 2,N
   JMIN = IT(K)
   JMAX = IU(K) - 1
   IF (JMIN .GT. JMAX) GO TO 31
   DO JJ = JMIN,JMAX
      LJ = JT(JJ)
      J = IC(LJ)
      Y(J) = Y(J) - T(JJ)*Y(K)
   END DO
31 K = K - 1
   Y(K) = Y(K)/D(K)
END DO
!
DO K = 1,N
   LK = R(K)
   X(LK) = Y(K)
END DO
RETURN
END SUBROUTINE CTSLV1

SUBROUTINE CSPLU (A,IA,JA,R,C,IC,N,MAX,D,T,IT,JT,IU,W,P,IERR)
IMPLICIT NONE
INTENT(IN) A, IA, JA, MAX, N, R
INTENT(INOUT) C, D, IC, IERR, IT, IU, JT, P, T, W
INTEGER IERR, MAX, N
INTEGER I, J, JJ, JMAX, JMIN, JPTR, K, LJ, LK, LL, M, MAXI, MAXIL
!-----------------------------------------------------------------------
!     CSPLU EMPLOYS GAUSSIAN ELIMINATION WITH COLUMN INTERCHANGES
!     TO PERFORM THE LU DECOMPOSITION OF A COMPLEX SPARSE MATRIX.
!     U IS A UNIT UPPER TRIANGULAR MATRIX.
!
!
!     INPUT ARGUMENTS ---
!
!     A,IA,JA  THE COMPLEX SPARSE MATRIX TO BE DECOMPOSED.
!
!     R        INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF
!              THE ROWS OF A.
!
!     C        INTEGER ARRAY OF N ENTRIES SPECIFYING A SUGGESTED
!              ORDER OF THE COLUMNS. C IS ALSO AN OUTPUT ARGUMENT.
!
!     IC       INTEGER ARRAY OF N ENTRIES WHICH IS THE INVERSE OF C
!              (I.E., IC(C(I)) = I). IC IS ALSO AN OUTPUT ARGUMENT.
!
!     N        ORDER OF THE MATRIX A.
!
!     MAX      INTEGER SPECIFYING THE MAXIMUM NUMBER OF OFF-DIAGONAL
!              NONZERO ENTRIES OF L AND U WHICH MAY BE STORED.
!
!
!     OUTPUT ARGUMENTS ---
!
!     C        INTEGER ARRAY OF N ENTRIES SPECIFYING THE ORDER OF
!              THE COLUMNS THAT WAS SELECTED BY THE ROUTINE.
!
!     IC       INTEGER ARRAY OF N ENTRIES WHICH IS THE INVERSE OF C.
!
!     D        COMPLEX ARRAY CONTAINING THE N DIAGONAL ELEMENTS OF L.
!
!     T,IT,IU  T CONTAINS THE OFF-DIAGONAL NONZERO ELEMENTS OF L AND
!              U. FOR I = 1,...,N THE OFF-DIAGONAL NONZERO ELEMENTS
!              OF THE I-TH ROW OF L ARE STORED IN LOCATIONS
!              IT(I),...,IU(I)-1 OF T, AND THE OFF-DIAGONAL NONZERO
!              ELEMENTS OF THE I-TH ROW OF U ARE STORED IN LOCATIONS
!              IU(I),...,IT(I+1)-1 OF T. T IS A COMPLEX ARRAY.
!
!     JT       INTEGER ARRAY CONTAINING THE COLUMN INDICES (ACCORDING
!              TO THE ORGINAL COLUMN ORDERING) OF THE ELEMENTS OF T
!              (I.E., FOR EACH L(I,J) AND U(I,J) IN T, C(J) IS THE
!              CORRESPONDING COLUMN INDEX IN JT).
!
!     IERR     INTEGER SPECIFYING THE STATUS OF THE RESULTS. IF THE
!              LU DECOMPOSITION IS OBTAINED THEN IERR = THE NUMBER
!              OF OFF-DIAGONAL ENTRIES OF L AND U WHICH WERE STORED
!              IN T. OTHERWISE IERR IS ASSIGNED A NEGATIVE VALUE.
!
!
!     WORK SPACES ---
!
!     W        COMPLEX ARRAY OF DIMENSION N.
!
!     P        INTEGER ARRAY OF DIMENSION N+1.
!-----------------------------------------------------------------------
COMPLEX A(*), D(N), T(MAX), W(N)
INTEGER IA(*), JA(*)
INTEGER R(N), C(N), IC(N)
INTEGER IT(*), JT(MAX), IU(N)
INTEGER P(*), PM
COMPLEX CONST, ZERO
REAL WI, WMAX
!--------------------
DATA ZERO /(0.0, 0.0)/
!--------------------
JPTR = 0
IT(1) = 1
DO J = 1,N
   W(J) = ZERO
END DO
!
!     PERFORM THE LU FACTORIZATION OF THE R(K)-TH ROW OF A
!
do 100 K = 1,N
LK = R(K)
JMIN = IA(LK)
JMAX = IA(LK+1) - 1
IF (JMIN .GT. JMAX) GO TO 200
!
!     SET P TO THE REORDERED ROW OF A
!
P(N+1) = N + 1
JJ = JMAX
20 LJ = JA(JJ)
J = IC(LJ)
W(J) = A(JJ)
PM = N + 1
21 M = PM
PM = P(M)
IF (PM - J) 21,210,22
22 P(M) = J
P(J) = PM
JJ = JJ - 1
IF (JJ .GE. JMIN) GO TO 20
!
!     PROCESS THE ENTRIES IN THE LOWER TRIANGLE OF A
!
I = N + 1
30 I = P(I)
IF (I .GE. K) GO TO 50
IF (W(I) .EQ. ZERO) GO TO 30
!
!     L(K,I) IS NONZERO. THEREFORE STORE IT IN L.
!
JPTR = JPTR + 1
IF (JPTR .GT. MAX) GO TO 230
CONST = W(I)
T(JPTR) = CONST
JT(JPTR) = C(I)
W(I) = ZERO
!
!     PERFORM ELIMINATION USING THE I-TH ROW OF U
!
JMIN = IU(I)
JMAX = IT(I+1) - 1
IF (JMIN .GT. JMAX) GO TO 30
PM = I
do 43 JJ = JMIN,JMAX
   LJ = JT(JJ)
   J = IC(LJ)
   IF (W(J) .NE. ZERO) GO TO 43
   IF (J - PM) 40,43,41
40 PM = I
41 M = PM
      PM = P(M)
      IF (PM - J) 41,43,42
42 P(M) = J
      P(J) = PM
      PM = J
43 W(J) = W(J) - CONST*T(JJ)
GO TO 30
!
!     SEARCH FOR THE K-TH PIVOT ELEMENT
!
50 IF (I .GT. N) GO TO 220
WMAX = ABS(REAL(W(I))) + ABS(AIMAG(W(I)))
MAXI = I
PM = I
51 M = PM
PM = P(M)
IF (PM .GT. N) GO TO 60
WI = ABS(REAL(W(PM))) + ABS(AIMAG(W(PM)))
IF (WI .LE. WMAX) GO TO 51
   WMAX = WI
   MAXI = PM
   MAXIL = M
   GO TO 51
!
!     STORE THE PIVOT IN D
!
60 IF (WMAX .EQ. 0.0) GO TO 220
D(K) = W(MAXI)
!
!     PERFORM THE COLUMN INTERCHANGE
!
IF (I .EQ. K) GO TO 70
IF (I .EQ. MAXI) GO TO 70
   P(MAXIL) = P(MAXI)
   GO TO 80
70 I = P(I)
!
80 W(MAXI) = W(K)
W(K) = ZERO
LK = C(K)
LL = C(MAXI)
C(K) = LL
C(MAXI) = LK
IC(LK) = MAXI
IC(LL) = K
!
!     THE REMAINING ELEMENTS OF P FORM THE K-TH ROW OF U
!
IU(K) = JPTR + 1
90 IF (I .GT. N) GO TO 100
IF (W(I) .EQ. ZERO) GO TO 91
   JPTR = JPTR + 1
   IF (JPTR .GT. MAX) GO TO 230
   T(JPTR) = W(I)/D(K)
   JT(JPTR) = C(I)
   W(I) = ZERO
91 I = P(I)
GO TO 90
!
!     PREPARE FOR THE NEXT ROW
!
100 IT(K+1) = JPTR + 1
!
IERR = JPTR
RETURN
!
!     -------------------- ERROR RETURN --------------------
!
!     ROW R(K) IS NULL
!
200 IERR = -K
RETURN
!
!     ROW R(K) HAS A DUPLICATE ENTRY
!
210 IERR = -(N + K)
RETURN
!
!     ZERO PIVOT IN ROW R(K)
!
220 IERR = -(2*N + K)
RETURN
!
!     STORAGE FOR L AND U EXCEEDED ON ROW R(K)
!
230 IERR = -(3*N + K)
RETURN
END SUBROUTINE CSPLU

SUBROUTINE EIG (IBAL,A,KA,N,WR,WI,IERR)
IMPLICIT NONE
INTENT(IN) IBAL, KA, N
INTENT(INOUT) A, IERR, WI, WR
INTEGER IBAL, IERR, KA, N
INTEGER IGH, LOW
!-----------------------------------------------------------------------
!                    EIGENVALUES OF REAL MATRICES
!-----------------------------------------------------------------------
REAL A(KA,N), WR(N), WI(N)
!
LOW = 1
IGH = N
IF (IBAL .NE. 0) CALL BALANC (KA,N,A,LOW,IGH,WR)
CALL ELMHS0 (KA,N,LOW,IGH,A,WR)
CALL HQR (KA,N,LOW,IGH,A,WR,WI,IERR)
RETURN
END SUBROUTINE EIG

SUBROUTINE EIG1 (IBAL,A,KA,N,WR,WI,IERR)
IMPLICIT NONE
INTENT(IN) IBAL, KA, N
INTENT(INOUT) A, IERR, WI, WR
INTEGER IBAL, IERR, KA, N
INTEGER IGH, LOW
!-----------------------------------------------------------------------
!                    EIGENVALUES OF REAL MATRICES
!-----------------------------------------------------------------------
REAL A(KA,N), WR(N), WI(N)
!
LOW = 1
IGH = N
IF (IBAL .NE. 0) CALL BALANC (KA,N,A,LOW,IGH,WR)
CALL ORTHES (KA,N,LOW,IGH,A,WR)
CALL HQR (KA,N,LOW,IGH,A,WR,WI,IERR)
RETURN
END SUBROUTINE EIG1

SUBROUTINE EIGV (IBAL,A,KA,N,WR,WI,ZR,ZI,IERR)
IMPLICIT NONE
INTENT(IN) IBAL, KA, N
INTENT(INOUT) A, IERR, WI, WR, ZI, ZR
INTEGER IBAL, IERR, KA, N
INTEGER IGH, J, K, KP1, LOW
!-----------------------------------------------------------------------
!           EIGENVALUES AND EIGENVECTORS OF REAL MATRICES
!-----------------------------------------------------------------------
REAL A(KA,N), WR(N), WI(N), ZR(KA,N), ZI(KA,N)
!
LOW = 1
IGH = N
IF (IBAL .NE. 0) CALL BALANC (KA,N,A,LOW,IGH,ZI)
CALL ELMHS0 (KA,N,LOW,IGH,A,WR)
CALL ELTRN0 (KA,N,LOW,IGH,A,WR,ZR)
CALL HQR2 (KA,N,LOW,IGH,A,WR,WI,ZR,IERR)
IF (IERR .NE. 0) RETURN
IF (IBAL .NE. 0) CALL BALBAK (KA,N,LOW,IGH,ZI,N,ZR)
!
do 30 K = 1,N
   IF (WI(K)) 30,10,20
10 do 11 J = 1,N
11 ZI(J,K) = 0.0
   GO TO 30
20 KP1 = K + 1
   do 21 J = 1,N
      ZI(J,K) = ZR(J,KP1)
      ZR(J,KP1) = ZR(J,K)
21 ZI(J,KP1) = -ZI(J,K)
30 CONTINUE
RETURN
END SUBROUTINE EIGV

SUBROUTINE EIGV1 (IBAL,A,KA,N,WR,WI,ZR,ZI,IERR)
IMPLICIT NONE
INTENT(IN) IBAL, KA, N
INTENT(INOUT) A, IERR, WI, WR, ZI, ZR
INTEGER IBAL, IERR, KA, N
INTEGER IGH, J, K, KP1, LOW
!-----------------------------------------------------------------------
!           EIGENVALUES AND EIGENVECTORS OF REAL MATRICES
!-----------------------------------------------------------------------
REAL A(KA,N), WR(N), WI(N), ZR(KA,N), ZI(KA,N)
!
LOW = 1
IGH = N
IF (IBAL .NE. 0) CALL BALANC (KA,N,A,LOW,IGH,ZI)
CALL ORTHES (KA,N,LOW,IGH,A,WR)
CALL ORTRAN (KA,N,LOW,IGH,A,WR,ZR)
CALL HQR2 (KA,N,LOW,IGH,A,WR,WI,ZR,IERR)
IF (IERR .NE. 0) RETURN
IF (IBAL .NE. 0) CALL BALBAK (KA,N,LOW,IGH,ZI,N,ZR)
!
do 30 K = 1,N
   IF (WI(K)) 30,10,20
10 do 11 J = 1,N
11 ZI(J,K) = 0.0
   GO TO 30
20 KP1 = K + 1
   do 21 J = 1,N
      ZI(J,K) = ZR(J,KP1)
      ZR(J,KP1) = ZR(J,K)
21 ZI(J,KP1) = -ZI(J,K)
30 CONTINUE
RETURN
END SUBROUTINE EIGV1

SUBROUTINE BALANC(NM,N,A,LOW,IGH,SCALE)
IMPLICIT NONE
INTENT(IN) N, NM
INTENT(INOUT) A, IGH, LOW, SCALE
!
INTEGER I,J,K,L,M,N,JJ,NM,IGH,LOW,IEXC
REAL A(NM,N),SCALE(N)
REAL C,F,G,R,S,B2,RADIX
INTEGER IPMPAR
!     REAL ABS
LOGICAL NOCONV
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE BALANCE,
!     NUM. MATH. 13, 293-304(1969) BY PARLETT AND REINSCH.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 315-326(1971).
!
!     THIS SUBROUTINE BALANCES A REAL MATRIX AND ISOLATES
!     EIGENVALUES WHENEVER POSSIBLE.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        A CONTAINS THE INPUT MATRIX TO BE BALANCED.
!
!     ON OUTPUT-
!
!        A CONTAINS THE BALANCED MATRIX,
!
!        LOW AND IGH ARE TWO INTEGERS SUCH THAT A(I,J)
!          IS EQUAL TO ZERO IF
!           (1) I IS GREATER THAN J AND
!           (2) J=1,...,LOW-1 OR I=IGH+1,...,N,
!
!        SCALE CONTAINS INFORMATION DETERMINING THE
!           PERMUTATIONS AND SCALING FACTORS USED.
!
!     SUPPOSE THAT THE PRINCIPAL SUBMATRIX IN ROWS LOW THROUGH IGH
!     HAS BEEN BALANCED, THAT P(J) DENOTES THE INDEX INTERCHANGED
!     WITH J DURING THE PERMUTATION STEP, AND THAT THE ELEMENTS
!     OF THE DIAGONAL MATRIX USED ARE DENOTED BY D(I,J).  THEN
!        SCALE(J) = P(J),    FOR J = 1,...,LOW-1
!                 = D(J,J),      J = LOW,...,IGH
!                 = P(J)         J = IGH+1,...,N.
!     THE ORDER IN WHICH THE INTERCHANGES ARE MADE IS N TO IGH+1,
!     THEN 1 TO LOW-1.
!
!     NOTE THAT 1 IS RETURNED FOR IGH IF IGH IS ZERO FORMALLY.
!
!     THE ALGOL PROCEDURE EXC CONTAINED IN BALANCE APPEARS IN
!     BALANC  IN LINE.  (NOTE THAT THE ALGOL ROLES OF IDENTIFIERS
!     K,L HAVE BEEN REVERSED.)
!
!-----------------------------------------------------------------------
!
!     ********** RADIX IS A MACHINE DEPENDENT PARAMETER SPECIFYING
!                THE BASE OF THE MACHINE FLOATING POINT REPRESENTATION.
!
           RADIX = IPMPAR(4)
!
!                **********
!
B2 = RADIX * RADIX
K = 1
L = N
GO TO 100
!     ********** IN-LINE PROCEDURE FOR ROW AND
!                COLUMN EXCHANGE **********
20 SCALE(M) = J
IF (J .EQ. M) GO TO 50
!
DO I = 1, L
   F = A(I,J)
   A(I,J) = A(I,M)
   A(I,M) = F
END DO
!
DO I = K, N
   F = A(J,I)
   A(J,I) = A(M,I)
   A(M,I) = F
END DO
!
50 GO TO (80,130), IEXC
!     ********** SEARCH FOR ROWS ISOLATING AN EIGENVALUE
!                AND PUSH THEM DOWN **********
80 IF (L .EQ. 1) GO TO 280
L = L - 1
!     ********** FOR J=L STEP -1 UNTIL 1 DO -- **********
100 do 120 JJ = 1, L
   J = L + 1 - JJ
!
   do 110 I = 1, L
      IF (I .EQ. J) GO TO 110
      IF (A(J,I) .NE. 0.0) GO TO 120
110 CONTINUE
!
   M = L
   IEXC = 1
   GO TO 20
120 CONTINUE
!
GO TO 140
!     ********** SEARCH FOR COLUMNS ISOLATING AN EIGENVALUE
!                AND PUSH THEM LEFT **********
130 K = K + 1
!
140 do 170 J = K, L
!
   do 150 I = K, L
      IF (I .EQ. J) GO TO 150
      IF (A(I,J) .NE. 0.0) GO TO 170
150 CONTINUE
!
   M = K
   IEXC = 2
   GO TO 20
170 CONTINUE
!     ********** NOW BALANCE THE SUBMATRIX IN ROWS K TO L **********
do 180 I = K, L
180 SCALE(I) = 1.0
!     ********** ITERATIVE LOOP FOR NORM REDUCTION **********
190 NOCONV = .FALSE.
!
do 270 I = K, L
   C = 0.0
   R = 0.0
!
   do 200 J = K, L
      IF (J .EQ. I) GO TO 200
      C = C + ABS(A(J,I))
      R = R + ABS(A(I,J))
200 CONTINUE
!     ********** GUARD AGAINST ZERO C OR R DUE TO UNDERFLOW **********
   IF (C .EQ. 0.0 .OR. R .EQ. 0.0) GO TO 270
   G = R / RADIX
   F = 1.0
   S = C + R
210 IF (C .GE. G) GO TO 220
   F = F * RADIX
   C = C * B2
   GO TO 210
220 G = R * RADIX
230 IF (C .LT. G) GO TO 240
   F = F / RADIX
   C = C / B2
   GO TO 230
!     ********** NOW BALANCE **********
240 IF ((C + R) / F .GE. 0.95 * S) GO TO 270
   G = 1.0 / F
   SCALE(I) = SCALE(I) * F
   NOCONV = .TRUE.
!
   do 250 J = K, N
250 A(I,J) = A(I,J) * G
!
   do 260 J = 1, L
260 A(J,I) = A(J,I) * F
!
270 CONTINUE
!
IF (NOCONV) GO TO 190
!
280 LOW = K
IGH = L
RETURN
END SUBROUTINE BALANC

SUBROUTINE BALINV (NZ,N,Z,LOW,IGH,SCALE)
IMPLICIT NONE
INTENT(IN) IGH, LOW, N, NZ, SCALE
INTENT(INOUT) Z
INTEGER I,J,K,N,II,NZ,IGH,LOW
REAL Z(NZ,N),SCALE(N)
REAL S
!-----------------------------------------------------------------------
!        GIVEN A MATRIX A OF ORDER N. BALANC TRANSFORMS A INTO
!     THE MATRIX B BY THE SIMILARITY TRANSFORMATION
!             B = D**(-1)*TRANSPOSE(P)*A*P*D
!     WHERE D IS A DIAGONAL MATRIX AND P A PERMUTATION MATRIX.
!     THE INFORMATION CONCERNING D AND P IS STORED IN IGH, LOW,
!     AND SCALE. THE ORDER IN WHICH THE INTERCHANGES WERE MADE
!     IS N TO IGH + 1, AND THEN 1 TO LOW - 1.
!
!        Z IS A MATRIX OF ORDER N. BALINV TRANSFORMS Z INTO THE
!     MATRIX W USING THE INVERSE SIMILARITY TRANSFORM
!             W = P*D*Z*D**(-1)*TRANSPOSE(P)
!
!     ON INPUT-
!
!        NZ IS THE ROW DIMENSION OF THE MATRIX Z IN THE CALLING
!          PROGRAM,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY  BALANC,
!
!        SCALE CONTAINS INFORMATION DETERMINING THE PERMUTATIONS
!          AND SCALING FACTORS USED BY  BALANC,
!
!     ON OUTPUT-
!
!        Z CONTAINS THE TRANSFORMED MATRIX W
!
!-----------------------------------------------------------------------
!
IF (IGH .EQ. LOW) GO TO 30
!
DO I = LOW, IGH
S = SCALE(I)
   do 10 J = 1, N
10 Z(I,J) = Z(I,J) * S
END DO
!
DO J = LOW, IGH
S = 1.0/SCALE(J)
   do 20 I = 1, N
20 Z(I,J) = Z(I,J) * S
END DO
!
!     ********- FOR I=LOW-1 STEP -1 UNTIL 1,
!               IGH+1 STEP 1 UNTIL N DO -- **********
!
30 do 60 II = 1, N
   I = II
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 60
   IF (I .LT. LOW) I = LOW - II
   K = SCALE(I)
   IF (K .EQ. I) GO TO 60
!
   do 40 J = 1, N
      S = Z(I,J)
      Z(I,J) = Z(K,J)
40 Z(K,J) = S
!
   do 50 J = 1, N
      S = Z(J,I)
      Z(J,I) = Z(J,K)
50 Z(J,K) = S
60 CONTINUE
RETURN
END SUBROUTINE BALINV

SUBROUTINE ELMHES(NM,N,LOW,IGH,A,INT)
IMPLICIT NONE
INTENT(IN) IGH, LOW, N, NM
INTENT(INOUT) A, INT
!
INTEGER I,J,M,N,LA,NM,IGH,KP1,LOW,MM1,MP1
REAL A(NM,N)
REAL X,Y
!     REAL ABS
INTEGER INT(IGH)
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE ELMHES,
!     NUM. MATH. 12, 349-368(1968) BY MARTIN AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 339-358(1971).
!
!     GIVEN A REAL GENERAL MATRIX, THIS SUBROUTINE
!     REDUCES A SUBMATRIX SITUATED IN ROWS AND COLUMNS
!     LOW THROUGH IGH TO UPPER HESSENBERG FORM BY
!     STABILIZED ELEMENTARY SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE  BALANC.  IF  BALANC  HAS NOT BEEN USED,
!          SET LOW=1, IGH=N,
!
!        A CONTAINS THE INPUT MATRIX.
!
!     ON OUTPUT-
!
!        A CONTAINS THE HESSENBERG MATRIX.  THE MULTIPLIERS
!          WHICH WERE USED IN THE REDUCTION ARE STORED IN THE
!          REMAINING TRIANGLE UNDER THE HESSENBERG MATRIX,
!
!        INT CONTAINS INFORMATION ON THE ROWS AND COLUMNS
!          INTERCHANGED IN THE REDUCTION.
!          ONLY ELEMENTS LOW THROUGH IGH ARE USED.
!
!-----------------------------------------------------------------------
!
LA = IGH - 1
KP1 = LOW + 1
IF (LA .LT. KP1) GO TO 200
!
do 180 M = KP1, LA
   MM1 = M - 1
   X = 0.0
   I = M
!
   do 100 J = M, IGH
      IF (ABS(A(J,MM1)) .LE. ABS(X)) GO TO 100
      X = A(J,MM1)
      I = J
100 CONTINUE
!
   INT(M) = I
   IF (I .EQ. M) GO TO 130
!    ********** INTERCHANGE ROWS AND COLUMNS OF A **********
   DO J = MM1, N
      Y = A(I,J)
      A(I,J) = A(M,J)
      A(M,J) = Y
   END DO
!
   DO J = 1, IGH
      Y = A(J,I)
      A(J,I) = A(J,M)
      A(J,M) = Y
   END DO
!    ********** END INTERCHANGE **********
130 IF (X .EQ. 0.0) GO TO 180
   MP1 = M + 1
!
   do 160 I = MP1, IGH
      Y = A(I,MM1)
      IF (Y .EQ. 0.0) GO TO 160
      Y = Y / X
      A(I,MM1) = Y
!
      do 140 J = M, N
140 A(I,J) = A(I,J) - Y * A(M,J)
!
      do 150 J = 1, IGH
150 A(J,M) = A(J,M) + Y * A(J,I)
!
160 CONTINUE
!
180 CONTINUE
!
200 RETURN
END SUBROUTINE ELMHES

SUBROUTINE ELMHS0(NM,N,LOW,IGH,A,INT)
IMPLICIT NONE
INTENT(IN) IGH, LOW, N, NM
INTENT(INOUT) A, INT
!
INTEGER I,J,M,N,LA,NM,IGH,KP1,LOW,MM1,MP1
REAL A(NM,N)
REAL X,Y
!     REAL ABS
REAL INT(IGH)
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE ELMHES,
!     NUM. MATH. 12, 349-368(1968) BY MARTIN AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 339-358(1971).
!
!     GIVEN A REAL GENERAL MATRIX, THIS SUBROUTINE
!     REDUCES A SUBMATRIX SITUATED IN ROWS AND COLUMNS
!     LOW THROUGH IGH TO UPPER HESSENBERG FORM BY
!     STABILIZED ELEMENTARY SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE  BALANC.  IF  BALANC  HAS NOT BEEN USED,
!          SET LOW=1, IGH=N,
!
!        A CONTAINS THE INPUT MATRIX.
!
!     ON OUTPUT-
!
!        A CONTAINS THE HESSENBERG MATRIX.  THE MULTIPLIERS
!          WHICH WERE USED IN THE REDUCTION ARE STORED IN THE
!          REMAINING TRIANGLE UNDER THE HESSENBERG MATRIX,
!
!        INT CONTAINS INFORMATION ON THE ROWS AND COLUMNS
!          INTERCHANGED IN THE REDUCTION.
!          ONLY ELEMENTS LOW THROUGH IGH ARE USED.
!
!-----------------------------------------------------------------------
!
LA = IGH - 1
KP1 = LOW + 1
IF (LA .LT. KP1) GO TO 200
!
do 180 M = KP1, LA
   MM1 = M - 1
   X = 0.0
   I = M
!
   do 100 J = M, IGH
      IF (ABS(A(J,MM1)) .LE. ABS(X)) GO TO 100
      X = A(J,MM1)
      I = J
100 CONTINUE
!
   INT(M) = I
   IF (I .EQ. M) GO TO 130
!    ********** INTERCHANGE ROWS AND COLUMNS OF A **********
   DO J = MM1, N
      Y = A(I,J)
      A(I,J) = A(M,J)
      A(M,J) = Y
   END DO
!
   DO J = 1, IGH
      Y = A(J,I)
      A(J,I) = A(J,M)
      A(J,M) = Y
   END DO
!    ********** END INTERCHANGE **********
130 IF (X .EQ. 0.0) GO TO 180
   MP1 = M + 1
!
   do 160 I = MP1, IGH
      Y = A(I,MM1)
      IF (Y .EQ. 0.0) GO TO 160
      Y = Y / X
      A(I,MM1) = Y
!
      do 140 J = M, N
140 A(I,J) = A(I,J) - Y * A(M,J)
!
      do 150 J = 1, IGH
150 A(J,M) = A(J,M) + Y * A(J,I)
!
160 CONTINUE
!
180 CONTINUE
!
200 RETURN
END SUBROUTINE ELMHS0

SUBROUTINE ORTHES(NM,N,LOW,IGH,A,ORT)
IMPLICIT NONE
INTENT(IN) IGH, LOW, N, NM
INTENT(INOUT) A, ORT
!
INTEGER I,J,M,N,II,JJ,LA,MP,NM,IGH,KP1,LOW
REAL A(NM,N),ORT(IGH)
REAL F,G,H,SCALE
!     REAL SQRT,ABS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE ORTHES,
!     NUM. MATH. 12, 349-368(1968) BY MARTIN AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 339-358(1971).
!
!     GIVEN A REAL GENERAL MATRIX, THIS SUBROUTINE
!     REDUCES A SUBMATRIX SITUATED IN ROWS AND COLUMNS
!     LOW THROUGH IGH TO UPPER HESSENBERG FORM BY
!     ORTHOGONAL SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE  BALANC.  IF  BALANC  HAS NOT BEEN USED,
!          SET LOW=1, IGH=N,
!
!        A CONTAINS THE INPUT MATRIX.
!
!     ON OUTPUT-
!
!        A CONTAINS THE HESSENBERG MATRIX.  INFORMATION ABOUT
!          THE ORTHOGONAL TRANSFORMATIONS USED IN THE REDUCTION
!          IS STORED IN THE REMAINING TRIANGLE UNDER THE
!          HESSENBERG MATRIX,
!
!        ORT CONTAINS FURTHER INFORMATION ABOUT THE TRANSFORMATIONS.
!          ONLY ELEMENTS LOW THROUGH IGH ARE USED.
!
!-----------------------------------------------------------------------
!
LA = IGH - 1
KP1 = LOW + 1
IF (LA .LT. KP1) GO TO 200
!
do 180 M = KP1, LA
   H = 0.0
   ORT(M) = 0.0
   SCALE = 0.0
!     ********** SCALE COLUMN (ALGOL TOL THEN NOT NEEDED) **********
   do 90 I = M, IGH
90 SCALE = SCALE + ABS(A(I,M-1))
!
   IF (SCALE .EQ. 0.0) GO TO 180
   MP = M + IGH
!     ********** FOR I=IGH STEP -1 UNTIL M DO -- **********
   DO II = M, IGH
      I = MP - II
      ORT(I) = A(I,M-1) / SCALE
      H = H + ORT(I) * ORT(I)
   END DO
!
   G = SQRT(H)
   IF (ORT(M) .GE. 0.0) G = -G
   H = H - ORT(M) * G
   ORT(M) = ORT(M) - G
!     ********** FORM (I-(U*UT)/H) * A **********
   DO J = M, N
      F = 0.0
!     ********** FOR I=IGH STEP -1 UNTIL M DO -- **********
      DO II = M, IGH
         I = MP - II
         F = F + ORT(I) * A(I,J)
      END DO
!
      F = F / H
!
      do 120 I = M, IGH
120 A(I,J) = A(I,J) - F * ORT(I)
!
   END DO
!     ********** FORM (I-(U*UT)/H)*A*(I-(U*UT)/H) **********
   DO I = 1, IGH
      F = 0.0
!     ********** FOR J=IGH STEP -1 UNTIL M DO -- **********
      DO JJ = M, IGH
         J = MP - JJ
         F = F + ORT(J) * A(I,J)
      END DO
!
      F = F / H
!
      do 150 J = M, IGH
150 A(I,J) = A(I,J) - F * ORT(J)
!
   END DO
!
   ORT(M) = SCALE * ORT(M)
   A(M,M-1) = SCALE * G
180 CONTINUE
!
200 RETURN
END SUBROUTINE ORTHES

SUBROUTINE HQR(NM,N,LOW,IGH,H,WR,WI,IERR)
IMPLICIT NONE
INTENT(IN) IGH, LOW, N, NM
INTENT(OUT) IERR
INTENT(INOUT) H, WI, WR
!
INTEGER I,J,K,L,M,N,EN,LL,MM,NA,NM,IGH,ITS,LOW,MP2,ENM2,IERR
REAL H(NM,N),WR(N),WI(N)
REAL P,Q,R,S,T,W,X,Y,ZZ,NORM,MACHEP,SPMPAR
!     REAL SQRT,ABS
!     INTEGER MIN0
LOGICAL NOTLAS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE HQR,
!     NUM. MATH. 14, 219-231(1970) BY MARTIN, PETERS, AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 359-371(1971).
!
!     THIS SUBROUTINE FINDS THE EIGENVALUES OF A REAL
!     UPPER HESSENBERG MATRIX BY THE QR METHOD.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE  BALANC.  IF  BALANC  HAS NOT BEEN USED,
!          SET LOW=1, IGH=N,
!
!        H CONTAINS THE UPPER HESSENBERG MATRIX.  INFORMATION ABOUT
!          THE TRANSFORMATIONS USED IN THE REDUCTION TO HESSENBERG
!          FORM BY  ELMHES  OR  ORTHES, IF PERFORMED, IS STORED
!          IN THE REMAINING TRIANGLE UNDER THE HESSENBERG MATRIX.
!
!     ON OUTPUT-
!
!        H HAS BEEN DESTROYED.  THEREFORE, IT MUST BE SAVED
!          BEFORE CALLING  HQR  IF SUBSEQUENT CALCULATION AND
!          BACK TRANSFORMATION OF EIGENVECTORS IS TO BE PERFORMED,
!
!        WR AND WI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE EIGENVALUES.  THE EIGENVALUES
!          ARE UNORDERED EXCEPT THAT COMPLEX CONJUGATE PAIRS
!          OF VALUES APPEAR CONSECUTIVELY WITH THE EIGENVALUE
!          HAVING THE POSITIVE IMAGINARY PART FIRST.  IF AN
!          ERROR EXIT IS MADE, THE EIGENVALUES SHOULD BE CORRECT
!          FOR INDICES IERR+1,...,N,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 30 ITERATIONS.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                MACHEP THE VALUE U WHERE U IS THE SMALLEST POSITIVE
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           MACHEP = SPMPAR(1)
!
!                **********
!
IERR = 0
NORM = 0.0
K = 1
!     ********** STORE ROOTS ISOLATED BY BALANC
!                AND COMPUTE MATRIX NORM **********
do 50 I = 1, N
!
   do 40 J = K, N
40 NORM = NORM + ABS(H(I,J))
!
   K = I
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 50
   WR(I) = H(I,I)
   WI(I) = 0.0
50 CONTINUE
!
EN = IGH
T = 0.0
!     ********** SEARCH FOR NEXT EIGENVALUES **********
60 IF (EN .LT. LOW) GO TO 1001
ITS = 0
NA = EN - 1
ENM2 = NA - 1
!     ********** LOOK FOR SINGLE SMALL SUB-DIAGONAL ELEMENT
!                FOR L=EN STEP -1 UNTIL LOW DO -- **********
70 DO LL = LOW, EN
   L = EN + LOW - LL
   IF (L .EQ. LOW) GO TO 100
   S = ABS(H(L-1,L-1)) + ABS(H(L,L))
   IF (S .EQ. 0.0) S = NORM
   IF (ABS(H(L,L-1)) .LE. MACHEP * S) GO TO 100
END DO
!     ********** FORM SHIFT **********
100 X = H(EN,EN)
IF (L .EQ. EN) GO TO 270
Y = H(NA,NA)
W = H(EN,NA) * H(NA,EN)
IF (L .EQ. NA) GO TO 280
IF (ITS .EQ. 30) GO TO 1000
IF (ITS .NE. 10 .AND. ITS .NE. 20) GO TO 130
!     ********** FORM EXCEPTIONAL SHIFT **********
T = T + X
!
do 120 I = LOW, EN
120 H(I,I) = H(I,I) - X
!
S = ABS(H(EN,NA)) + ABS(H(NA,ENM2))
X = 0.75 * S
Y = X
W = -0.4375 * S * S
130 ITS = ITS + 1
!     ********** LOOK FOR TWO CONSECUTIVE SMALL
!                SUB-DIAGONAL ELEMENTS.
!                FOR M=EN-2 STEP -1 UNTIL L DO -- **********
DO MM = L, ENM2
   M = ENM2 + L - MM
   ZZ = H(M,M)
   R = X - ZZ
   S = Y - ZZ
   P = (R * S - W) / H(M+1,M) + H(M,M+1)
   Q = H(M+1,M+1) - ZZ - R - S
   R = H(M+2,M+1)
   S = ABS(P) + ABS(Q) + ABS(R)
   P = P / S
   Q = Q / S
   R = R / S
   IF (M .EQ. L) GO TO 150
   IF (ABS(H(M,M-1)) * (ABS(Q) + ABS(R)) .LE. MACHEP * ABS(P) &
&* (ABS(H(M-1,M-1)) + ABS(ZZ) + ABS(H(M+1,M+1)))) GO TO 150
END DO
!
150 MP2 = M + 2
!
do 160 I = MP2, EN
   H(I,I-2) = 0.0
   IF (I .EQ. MP2) GO TO 160
   H(I,I-3) = 0.0
160 CONTINUE
!     ********** DOUBLE QR STEP INVOLVING ROWS L TO EN AND
!                COLUMNS M TO EN **********
do 260 K = M, NA
   NOTLAS = K .NE. NA
   IF (K .EQ. M) GO TO 170
   P = H(K,K-1)
   Q = H(K+1,K-1)
   R = 0.0
   IF (NOTLAS) R = H(K+2,K-1)
   X = ABS(P) + ABS(Q) + ABS(R)
   IF (X .EQ. 0.0) GO TO 260
   P = P / X
   Q = Q / X
   R = R / X
170 S = SQRT(P*P + Q*Q + R*R)
   IF (P .LT. 0.0) S = -S
   IF (K .EQ. M) GO TO 180
   H(K,K-1) = -S * X
   GO TO 190
180 IF (L .NE. M) H(K,K-1) = -H(K,K-1)
190 P = P + S
   X = P / S
   Y = Q / S
   ZZ = R / S
   Q = Q / P
   R = R / P
!     ********** ROW MODIFICATION **********
   DO J = K, EN
      P = H(K,J) + Q * H(K+1,J)
      IF (.NOT. NOTLAS) GO TO 200
      P = P + R * H(K+2,J)
      H(K+2,J) = H(K+2,J) - P * ZZ
200 H(K+1,J) = H(K+1,J) - P * Y
      H(K,J) = H(K,J) - P * X
   END DO
!
   J = MIN0(EN,K+3)
!     ********** COLUMN MODIFICATION **********
   DO I = L, J
      P = X * H(I,K) + Y * H(I,K+1)
      IF (.NOT. NOTLAS) GO TO 220
      P = P + ZZ * H(I,K+2)
      H(I,K+2) = H(I,K+2) - P * R
220 H(I,K+1) = H(I,K+1) - P * Q
      H(I,K) = H(I,K) - P
   END DO
!
260 CONTINUE
!
GO TO 70
!     ********** ONE ROOT FOUND **********
270 WR(EN) = X + T
WI(EN) = 0.0
EN = NA
GO TO 60
!     ********** TWO ROOTS FOUND **********
280 P = (Y - X) / 2.0
Q = P * P + W
ZZ = SQRT(ABS(Q))
X = X + T
IF (Q .LT. 0.0) GO TO 320
!     ********** REAL PAIR **********
IF (P .LT. 0.0) ZZ = -ZZ
ZZ = P + ZZ
WR(NA) = X + ZZ
WR(EN) = WR(NA)
IF (ZZ .NE. 0.0) WR(EN) = X - W / ZZ
WI(NA) = 0.0
WI(EN) = 0.0
GO TO 330
!     ********** COMPLEX PAIR **********
320 WR(NA) = X + P
WR(EN) = X + P
WI(NA) = ZZ
WI(EN) = -ZZ
330 EN = ENM2
GO TO 60
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 IERR = EN
1001 RETURN
END SUBROUTINE HQR

SUBROUTINE BALBAK(NM,N,LOW,IGH,SCALE,M,Z)
IMPLICIT NONE
INTENT(IN) IGH, LOW, M, N, NM, SCALE
INTENT(INOUT) Z
!
INTEGER I,J,K,M,N,II,NM,IGH,LOW
REAL SCALE(N),Z(NM,M)
REAL S
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE BALBAK,
!     NUM. MATH. 13, 293-304(1969) BY PARLETT AND REINSCH.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 315-326(1971).
!
!     THIS SUBROUTINE FORMS THE EIGENVECTORS OF A REAL GENERAL
!     MATRIX BY BACK TRANSFORMING THOSE OF THE CORRESPONDING
!     BALANCED MATRIX DETERMINED BY  BALANC.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY  BALANC,
!
!        SCALE CONTAINS INFORMATION DETERMINING THE PERMUTATIONS
!          AND SCALING FACTORS USED BY  BALANC,
!
!        M IS THE NUMBER OF COLUMNS OF Z TO BE BACK TRANSFORMED,
!
!        Z CONTAINS THE REAL AND IMAGINARY PARTS OF THE EIGEN-
!          VECTORS TO BE BACK TRANSFORMED IN ITS FIRST M COLUMNS.
!
!     ON OUTPUT-
!
!        Z CONTAINS THE REAL AND IMAGINARY PARTS OF THE
!          TRANSFORMED EIGENVECTORS IN ITS FIRST M COLUMNS.
!
!-----------------------------------------------------------------------
!
IF (M .EQ. 0) GO TO 200
IF (IGH .EQ. LOW) GO TO 120
!
DO I = LOW, IGH
   S = SCALE(I)
!     ********** LEFT HAND EIGENVECTORS ARE BACK TRANSFORMED
!                IF THE FOREGOING STATEMENT IS REPLACED BY
!                S=1.0/SCALE(I). **********
   do 100 J = 1, M
100 Z(I,J) = Z(I,J) * S
!
END DO
!     ********- FOR I=LOW-1 STEP -1 UNTIL 1,
!               IGH+1 STEP 1 UNTIL N DO -- **********
120 do 140 II = 1, N
   I = II
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 140
   IF (I .LT. LOW) I = LOW - II
   K = SCALE(I)
   IF (K .EQ. I) GO TO 140
!
   DO J = 1, M
      S = Z(I,J)
      Z(I,J) = Z(K,J)
      Z(K,J) = S
   END DO
!
140 CONTINUE
!
200 RETURN
END SUBROUTINE BALBAK

SUBROUTINE ELTRAN(NM,N,LOW,IGH,A,INT,Z)
IMPLICIT NONE
INTENT(IN) A, IGH, INT, LOW, N, NM
INTENT(INOUT) Z
!
INTEGER I,J,N,KL,MM,MP,NM,IGH,LOW,MP1
REAL A(NM,IGH),Z(NM,N)
INTEGER INT(IGH)
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE ELMTRANS,
!     NUM. MATH. 16, 181-204(1970) BY PETERS AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 372-395(1971).
!
!     THIS SUBROUTINE ACCUMULATES THE STABILIZED ELEMENTARY
!     SIMILARITY TRANSFORMATIONS USED IN THE REDUCTION OF A
!     REAL GENERAL MATRIX TO UPPER HESSENBERG FORM BY  ELMHES.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE  BALANC.  IF  BALANC  HAS NOT BEEN USED,
!          SET LOW=1, IGH=N,
!
!        A CONTAINS THE MULTIPLIERS WHICH WERE USED IN THE
!          REDUCTION BY  ELMHES  IN ITS LOWER TRIANGLE
!          BELOW THE SUBDIAGONAL,
!
!        INT CONTAINS INFORMATION ON THE ROWS AND COLUMNS
!          INTERCHANGED IN THE REDUCTION BY  ELMHES.
!          ONLY ELEMENTS LOW THROUGH IGH ARE USED.
!
!     ON OUTPUT-
!
!        Z CONTAINS THE TRANSFORMATION MATRIX PRODUCED IN THE
!          REDUCTION BY  ELMHES.
!
!-----------------------------------------------------------------------
!
!     ********** INITIALIZE Z TO IDENTITY MATRIX **********
DO I = 1, N
!
   do 60 J = 1, N
60 Z(I,J) = 0.0
!
   Z(I,I) = 1.0
END DO
!
KL = IGH - LOW - 1
IF (KL .LT. 1) GO TO 200
!     ********** FOR MP=IGH-1 STEP -1 UNTIL LOW+1 DO -- **********
do 140 MM = 1, KL
   MP = IGH - MM
   MP1 = MP + 1
!
   do 100 I = MP1, IGH
100 Z(I,MP) = A(I,MP-1)
!
   I = INT(MP)
   IF (I .EQ. MP) GO TO 140
!
   DO J = MP, IGH
      Z(MP,J) = Z(I,J)
      Z(I,J) = 0.0
   END DO
!
   Z(I,MP) = 1.0
140 CONTINUE
!
200 RETURN
END SUBROUTINE ELTRAN

SUBROUTINE ELTRN0(NM,N,LOW,IGH,A,INT,Z)
IMPLICIT NONE
INTENT(IN) A, IGH, INT, LOW, N, NM
INTENT(INOUT) Z
!
INTEGER I,J,N,KL,MM,MP,NM,IGH,LOW,MP1
REAL A(NM,IGH),Z(NM,N)
REAL INT(IGH)
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE ELMTRANS,
!     NUM. MATH. 16, 181-204(1970) BY PETERS AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 372-395(1971).
!
!     THIS SUBROUTINE ACCUMULATES THE STABILIZED ELEMENTARY
!     SIMILARITY TRANSFORMATIONS USED IN THE REDUCTION OF A
!     REAL GENERAL MATRIX TO UPPER HESSENBERG FORM BY  ELMHS0.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE  BALANC.  IF  BALANC  HAS NOT BEEN USED,
!          SET LOW=1, IGH=N,
!
!        A CONTAINS THE MULTIPLIERS WHICH WERE USED IN THE
!          REDUCTION BY  ELMHS0  IN ITS LOWER TRIANGLE
!          BELOW THE SUBDIAGONAL,
!
!        INT CONTAINS INFORMATION ON THE ROWS AND COLUMNS
!          INTERCHANGED IN THE REDUCTION BY  ELMHS0.
!          ONLY ELEMENTS LOW THROUGH IGH ARE USED.
!
!     ON OUTPUT-
!
!        Z CONTAINS THE TRANSFORMATION MATRIX PRODUCED IN THE
!          REDUCTION BY  ELMHS0.
!
!-----------------------------------------------------------------------
!
!     ********** INITIALIZE Z TO IDENTITY MATRIX **********
DO I = 1, N
!
   do 60 J = 1, N
60 Z(I,J) = 0.0
!
   Z(I,I) = 1.0
END DO
!
KL = IGH - LOW - 1
IF (KL .LT. 1) GO TO 200
!     ********** FOR MP=IGH-1 STEP -1 UNTIL LOW+1 DO -- **********
do 140 MM = 1, KL
   MP = IGH - MM
   MP1 = MP + 1
!
   do 100 I = MP1, IGH
100 Z(I,MP) = A(I,MP-1)
!
   I = INT(MP)
   IF (I .EQ. MP) GO TO 140
!
   DO J = MP, IGH
      Z(MP,J) = Z(I,J)
      Z(I,J) = 0.0
   END DO
!
   Z(I,MP) = 1.0
140 CONTINUE
!
200 RETURN
END SUBROUTINE ELTRN0

SUBROUTINE ORTRAN(NM,N,LOW,IGH,A,ORT,Z)
IMPLICIT NONE
INTENT(IN) A, IGH, LOW, N, NM
INTENT(INOUT) ORT, Z
!
INTEGER I,J,N,KL,MM,MP,NM,IGH,LOW,MP1
REAL A(NM,IGH),ORT(IGH),Z(NM,N)
REAL G
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE ORTRANS,
!     NUM. MATH. 16, 181-204(1970) BY PETERS AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 372-395(1971).
!
!     THIS SUBROUTINE ACCUMULATES THE ORTHOGONAL SIMILARITY
!     TRANSFORMATIONS USED IN THE REDUCTION OF A REAL GENERAL
!     MATRIX TO UPPER HESSENBERG FORM BY  ORTHES.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE  BALANC.  IF  BALANC  HAS NOT BEEN USED,
!          SET LOW=1, IGH=N,
!
!        A CONTAINS INFORMATION ABOUT THE ORTHOGONAL TRANS-
!          FORMATIONS USED IN THE REDUCTION BY  ORTHES
!          IN ITS STRICT LOWER TRIANGLE,
!
!        ORT CONTAINS FURTHER INFORMATION ABOUT THE TRANS-
!          FORMATIONS USED IN THE REDUCTION BY  ORTHES.
!          ONLY ELEMENTS LOW THROUGH IGH ARE USED.
!
!     ON OUTPUT-
!
!        Z CONTAINS THE TRANSFORMATION MATRIX PRODUCED IN THE
!          REDUCTION BY  ORTHES,
!
!        ORT HAS BEEN ALTERED.
!
!-----------------------------------------------------------------------
!
!     ********** INITIALIZE Z TO IDENTITY MATRIX **********
DO I = 1, N
!
   do 60 J = 1, N
60 Z(I,J) = 0.0
!
   Z(I,I) = 1.0
END DO
!
KL = IGH - LOW - 1
IF (KL .LT. 1) GO TO 200
!     ********** FOR MP=IGH-1 STEP -1 UNTIL LOW+1 DO -- **********
do 140 MM = 1, KL
   MP = IGH - MM
   IF (A(MP,MP-1) .EQ. 0.0) GO TO 140
   MP1 = MP + 1
!
   do 100 I = MP1, IGH
100 ORT(I) = A(I,MP-1)
!
   DO J = MP, IGH
      G = 0.0
!
      do 110 I = MP, IGH
110 G = G + ORT(I) * Z(I,J)
!     ********** DIVISOR BELOW IS NEGATIVE OF H FORMED IN ORTHES.
!                DOUBLE DIVISION AVOIDS POSSIBLE UNDERFLOW **********
      G = (G / ORT(MP)) / A(MP,MP-1)
!
      do 120 I = MP, IGH
120 Z(I,J) = Z(I,J) + G * ORT(I)
!
   END DO
!
140 CONTINUE
!
200 RETURN
END SUBROUTINE ORTRAN

SUBROUTINE ORTRN1(N,LOW,IGH,A,NA,Z,NZ,ORT)
IMPLICIT NONE
INTENT(IN) A, IGH, LOW, N, NA, NZ
INTENT(INOUT) ORT, Z
!
INTEGER I,J,N,KL,MM,MP,NA,IGH,LOW,MP1,NZ
REAL A(NA,IGH),ORT(IGH),Z(NZ,N)
REAL G
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE ORTRANS,
!     NUM. MATH. 16, 181-204(1970) BY PETERS AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 372-395(1971).
!
!     THIS SUBROUTINE ACCUMULATES THE ORTHOGONAL SIMILARITY
!     TRANSFORMATIONS USED IN THE REDUCTION OF A REAL GENERAL
!     MATRIX TO UPPER HESSENBERG FORM BY  ORTHES.
!
!     ON INPUT-
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE  BALANC.  IF  BALANC  HAS NOT BEEN USED,
!          SET LOW=1, IGH=N,
!
!        A CONTAINS INFORMATION ABOUT THE ORTHOGONAL TRANS-
!          FORMATIONS USED IN THE REDUCTION BY  ORTHES
!          IN ITS STRICT LOWER TRIANGLE,
!
!        NA MUST BE SET TO THE ROW DIMENSION OF THE 2-DIMENSIONAL
!          ARRAY PARAMETER  A  AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        NZ MUST BE SET TO THE ROW DIMENSION OF THE 2-DIMENSIONAL
!          ARRAY PARAMETER  Z  AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        ORT CONTAINS FURTHER INFORMATION ABOUT THE TRANS-
!          FORMATIONS USED IN THE REDUCTION BY  ORTHES.
!          ONLY ELEMENTS LOW THROUGH IGH ARE USED.
!
!     ON OUTPUT-
!
!        Z CONTAINS THE TRANSFORMATION MATRIX PRODUCED IN THE
!          REDUCTION BY  ORTHES,
!
!        ORT HAS BEEN ALTERED.
!
!-----------------------------------------------------------------------
!
!     ********** INITIALIZE Z TO IDENTITY MATRIX **********
DO I = 1, N
!
   do 60 J = 1, N
60 Z(I,J) = 0.0
!
   Z(I,I) = 1.0
END DO
!
KL = IGH - LOW - 1
IF (KL .LT. 1) GO TO 200
!     ********** FOR MP=IGH-1 STEP -1 UNTIL LOW+1 DO -- **********
do 140 MM = 1, KL
   MP = IGH - MM
   IF (A(MP,MP-1) .EQ. 0.0) GO TO 140
   MP1 = MP + 1
!
   do 100 I = MP1, IGH
100 ORT(I) = A(I,MP-1)
!
   DO J = MP, IGH
      G = 0.0
!
      do 110 I = MP, IGH
110 G = G + ORT(I) * Z(I,J)
!     ********** DIVISOR BELOW IS NEGATIVE OF H FORMED IN ORTHES.
!                DOUBLE DIVISION AVOIDS POSSIBLE UNDERFLOW **********
      G = (G / ORT(MP)) / A(MP,MP-1)
!
      do 120 I = MP, IGH
120 Z(I,J) = Z(I,J) + G * ORT(I)
!
   END DO
!
140 CONTINUE
!
200 RETURN
END SUBROUTINE ORTRN1

SUBROUTINE HQR2(NM,N,LOW,IGH,H,WR,WI,Z,IERR)
IMPLICIT NONE
INTENT(IN) IGH, LOW, N, NM
INTENT(OUT) IERR
INTENT(INOUT) H, WI, WR, Z
!
INTEGER I,J,K,L,M,N,EN,II,JJ,LL,MM,NA,NM,NN, &
&IGH,ITS,LOW,MP2,ENM2,IERR
REAL H(NM,N),WR(N),WI(N),Z(NM,N)
REAL P,Q,R,S,T,W,X,Y,RA,SA,VI,VR,ZZ,NORM,MACHEP,SPMPAR
!     REAL SQRT,ABS
!     INTEGER MIN0
LOGICAL NOTLAS
COMPLEX Z3
!     COMPLEX CMPLX
!     REAL REAL,AIMAG
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE HQR2,
!     NUM. MATH. 16, 181-204(1970) BY PETERS AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 372-395(1971).
!
!     THIS SUBROUTINE FINDS THE EIGENVALUES AND EIGENVECTORS
!     OF A REAL UPPER HESSENBERG MATRIX BY THE QR METHOD.  THE
!     EIGENVECTORS OF A REAL GENERAL MATRIX CAN ALSO BE FOUND
!     IF  ELMHES  AND  ELTRAN  OR  ORTHES  AND  ORTRAN  HAVE
!     BEEN USED TO REDUCE THIS GENERAL MATRIX TO HESSENBERG FORM
!     AND TO ACCUMULATE THE SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE  BALANC.  IF  BALANC  HAS NOT BEEN USED,
!          SET LOW=1, IGH=N,
!
!        H CONTAINS THE UPPER HESSENBERG MATRIX,
!
!        Z CONTAINS THE TRANSFORMATION MATRIX PRODUCED BY  ELTRAN
!          AFTER THE REDUCTION BY  ELMHES, OR BY  ORTRAN  AFTER THE
!          REDUCTION BY  ORTHES, IF PERFORMED.  IF THE EIGENVECTORS
!          OF THE HESSENBERG MATRIX ARE DESIRED, Z MUST CONTAIN THE
!          IDENTITY MATRIX.
!
!     ON OUTPUT-
!
!        H HAS BEEN DESTROYED,
!
!        WR AND WI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE EIGENVALUES.  THE EIGENVALUES
!          ARE UNORDERED EXCEPT THAT COMPLEX CONJUGATE PAIRS
!          OF VALUES APPEAR CONSECUTIVELY WITH THE EIGENVALUE
!          HAVING THE POSITIVE IMAGINARY PART FIRST.  IF AN
!          ERROR EXIT IS MADE, THE EIGENVALUES SHOULD BE CORRECT
!          FOR INDICES IERR+1,...,N,
!
!        Z CONTAINS THE REAL AND IMAGINARY PARTS OF THE EIGENVECTORS.
!          IF THE I-TH EIGENVALUE IS REAL, THE I-TH COLUMN OF Z
!          CONTAINS ITS EIGENVECTOR.  IF THE I-TH EIGENVALUE IS COMPLEX
!          WITH POSITIVE IMAGINARY PART, THE I-TH AND (I+1)-TH
!          COLUMNS OF Z CONTAIN THE REAL AND IMAGINARY PARTS OF ITS
!          EIGENVECTOR.  THE EIGENVECTORS ARE UNNORMALIZED.  IF AN
!          ERROR EXIT IS MADE, NONE OF THE EIGENVECTORS HAS BEEN FOUND,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 30 ITERATIONS.
!
!     ARITHMETIC IS REAL EXCEPT FOR THE REPLACEMENT OF THE ALGOL
!     PROCEDURE CDIV BY COMPLEX DIVISION.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                MACHEP THE VALUE U WHERE U IS THE SMALLEST POSITIVE
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           MACHEP = SPMPAR(1)
!
!                **********
!
IERR = 0
NORM = 0.0
K = 1
!     ********** STORE ROOTS ISOLATED BY BALANC
!                AND COMPUTE MATRIX NORM **********
do 50 I = 1, N
!
   do 40 J = K, N
40 NORM = NORM + ABS(H(I,J))
!
   K = I
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 50
   WR(I) = H(I,I)
   WI(I) = 0.0
50 CONTINUE
!
EN = IGH
T = 0.0
!     ********** SEARCH FOR NEXT EIGENVALUES **********
60 IF (EN .LT. LOW) GO TO 340
ITS = 0
NA = EN - 1
ENM2 = NA - 1
!     ********** LOOK FOR SINGLE SMALL SUB-DIAGONAL ELEMENT
!                FOR L=EN STEP -1 UNTIL LOW DO -- **********
70 DO LL = LOW, EN
   L = EN + LOW - LL
   IF (L .EQ. LOW) GO TO 100
   S = ABS(H(L-1,L-1)) + ABS(H(L,L))
   IF (S .EQ. 0.0) S = NORM
   IF (ABS(H(L,L-1)) .LE. MACHEP * S) GO TO 100
END DO
!     ********** FORM SHIFT **********
100 X = H(EN,EN)
IF (L .EQ. EN) GO TO 270
Y = H(NA,NA)
W = H(EN,NA) * H(NA,EN)
IF (L .EQ. NA) GO TO 280
IF (ITS .EQ. 30) GO TO 1000
IF (ITS .NE. 10 .AND. ITS .NE. 20) GO TO 130
!     ********** FORM EXCEPTIONAL SHIFT **********
T = T + X
!
do 120 I = LOW, EN
120 H(I,I) = H(I,I) - X
!
S = ABS(H(EN,NA)) + ABS(H(NA,ENM2))
X = 0.75 * S
Y = X
W = -0.4375 * S * S
130 ITS = ITS + 1
!     ********** LOOK FOR TWO CONSECUTIVE SMALL
!                SUB-DIAGONAL ELEMENTS.
!                FOR M=EN-2 STEP -1 UNTIL L DO -- **********
DO MM = L, ENM2
   M = ENM2 + L - MM
   ZZ = H(M,M)
   R = X - ZZ
   S = Y - ZZ
   P = (R * S - W) / H(M+1,M) + H(M,M+1)
   Q = H(M+1,M+1) - ZZ - R - S
   R = H(M+2,M+1)
   S = ABS(P) + ABS(Q) + ABS(R)
   P = P / S
   Q = Q / S
   R = R / S
   IF (M .EQ. L) GO TO 150
   IF (ABS(H(M,M-1)) * (ABS(Q) + ABS(R)) .LE. MACHEP * ABS(P) &
&* (ABS(H(M-1,M-1)) + ABS(ZZ) + ABS(H(M+1,M+1)))) GO TO 150
END DO
!
150 MP2 = M + 2
!
do 160 I = MP2, EN
   H(I,I-2) = 0.0
   IF (I .EQ. MP2) GO TO 160
   H(I,I-3) = 0.0
160 CONTINUE
!     ********** DOUBLE QR STEP INVOLVING ROWS L TO EN AND
!                COLUMNS M TO EN **********
do 260 K = M, NA
   NOTLAS = K .NE. NA
   IF (K .EQ. M) GO TO 170
   P = H(K,K-1)
   Q = H(K+1,K-1)
   R = 0.0
   IF (NOTLAS) R = H(K+2,K-1)
   X = ABS(P) + ABS(Q) + ABS(R)
   IF (X .EQ. 0.0) GO TO 260
   P = P / X
   Q = Q / X
   R = R / X
170 S = SQRT(P*P + Q*Q + R*R)
   IF (P .LT. 0.0) S = -S
   IF (K .EQ. M) GO TO 180
   H(K,K-1) = -S * X
   GO TO 190
180 IF (L .NE. M) H(K,K-1) = -H(K,K-1)
190 P = P + S
   X = P / S
   Y = Q / S
   ZZ = R / S
   Q = Q / P
   R = R / P
!     ********** ROW MODIFICATION **********
   DO J = K, N
      P = H(K,J) + Q * H(K+1,J)
      IF (.NOT. NOTLAS) GO TO 200
      P = P + R * H(K+2,J)
      H(K+2,J) = H(K+2,J) - P * ZZ
200 H(K+1,J) = H(K+1,J) - P * Y
      H(K,J) = H(K,J) - P * X
   END DO
!
   J = MIN0(EN,K+3)
!     ********** COLUMN MODIFICATION **********
   DO I = 1, J
      P = X * H(I,K) + Y * H(I,K+1)
      IF (.NOT. NOTLAS) GO TO 220
      P = P + ZZ * H(I,K+2)
      H(I,K+2) = H(I,K+2) - P * R
220 H(I,K+1) = H(I,K+1) - P * Q
      H(I,K) = H(I,K) - P
   END DO
!     ********** ACCUMULATE TRANSFORMATIONS **********
   DO I = LOW, IGH
      P = X * Z(I,K) + Y * Z(I,K+1)
      IF (.NOT. NOTLAS) GO TO 240
      P = P + ZZ * Z(I,K+2)
      Z(I,K+2) = Z(I,K+2) - P * R
240 Z(I,K+1) = Z(I,K+1) - P * Q
      Z(I,K) = Z(I,K) - P
   END DO
!
260 CONTINUE
!
GO TO 70
!     ********** ONE ROOT FOUND **********
270 H(EN,EN) = X + T
WR(EN) = H(EN,EN)
WI(EN) = 0.0
EN = NA
GO TO 60
!     ********** TWO ROOTS FOUND **********
280 P = (Y - X) / 2.0
Q = P * P + W
ZZ = SQRT(ABS(Q))
H(EN,EN) = X + T
X = H(EN,EN)
H(NA,NA) = Y + T
IF (Q .LT. 0.0) GO TO 320
!     ********** REAL PAIR **********
IF (P .LT. 0.0) ZZ = -ZZ
ZZ = P + ZZ
WR(NA) = X + ZZ
WR(EN) = WR(NA)
IF (ZZ .NE. 0.0) WR(EN) = X - W / ZZ
WI(NA) = 0.0
WI(EN) = 0.0
X = H(EN,NA)
S = ABS(X) + ABS(ZZ)
P = X / S
Q = ZZ / S
R = SQRT(P*P+Q*Q)
P = P / R
Q = Q / R
!     ********** ROW MODIFICATION **********
DO J = NA, N
   ZZ = H(NA,J)
   H(NA,J) = Q * ZZ + P * H(EN,J)
   H(EN,J) = Q * H(EN,J) - P * ZZ
END DO
!     ********** COLUMN MODIFICATION **********
DO I = 1, EN
   ZZ = H(I,NA)
   H(I,NA) = Q * ZZ + P * H(I,EN)
   H(I,EN) = Q * H(I,EN) - P * ZZ
END DO
!     ********** ACCUMULATE TRANSFORMATIONS **********
DO I = LOW, IGH
   ZZ = Z(I,NA)
   Z(I,NA) = Q * ZZ + P * Z(I,EN)
   Z(I,EN) = Q * Z(I,EN) - P * ZZ
END DO
!
GO TO 330
!     ********** COMPLEX PAIR **********
320 WR(NA) = X + P
WR(EN) = X + P
WI(NA) = ZZ
WI(EN) = -ZZ
330 EN = ENM2
GO TO 60
!     ********** ALL ROOTS FOUND.  BACKSUBSTITUTE TO FIND
!                VECTORS OF UPPER TRIANGULAR FORM **********
340 IF (NORM .EQ. 0.0) GO TO 1001
!     ********** FOR EN=N STEP -1 UNTIL 1 DO -- **********
do 800 NN = 1, N
   EN = N + 1 - NN
   P = WR(EN)
   Q = WI(EN)
   NA = EN - 1
   IF (Q) 710, 600, 800
!     ********** REAL VECTOR **********
600 M = EN
   H(EN,EN) = 1.0
   IF (NA .EQ. 0) GO TO 800
!     ********** FOR I=EN-1 STEP -1 UNTIL 1 DO -- **********
   do 700 II = 1, NA
      I = EN - II
      W = H(I,I) - P
      R = H(I,EN)
      IF (M .GT. NA) GO TO 620
!
      do 610 J = M, NA
610 R = R + H(I,J) * H(J,EN)
!
620 IF (WI(I) .GE. 0.0) GO TO 630
      ZZ = W
      S = R
      GO TO 700
630 M = I
      IF (WI(I) .NE. 0.0) GO TO 640
      T = W
      IF (W .EQ. 0.0) T = MACHEP * NORM
      H(I,EN) = -R / T
      GO TO 700
!     ********** SOLVE REAL EQUATIONS **********
640 X = H(I,I+1)
      Y = H(I+1,I)
      Q = (WR(I) - P) * (WR(I) - P) + WI(I) * WI(I)
      T = (X * S - ZZ * R) / Q
      H(I,EN) = T
      IF (ABS(X) .LE. ABS(ZZ)) GO TO 650
      H(I+1,EN) = (-R - W * T) / X
      GO TO 700
650 H(I+1,EN) = (-S - Y * T) / ZZ
700 CONTINUE
!     ********** END REAL VECTOR **********
   GO TO 800
!     ********** COMPLEX VECTOR **********
710 M = NA
!     ********** LAST VECTOR COMPONENT CHOSEN IMAGINARY SO THAT
!                EIGENVECTOR MATRIX IS TRIANGULAR **********
   IF (ABS(H(EN,NA)) .LE. ABS(H(NA,EN))) GO TO 720
   H(NA,NA) = Q / H(EN,NA)
   H(NA,EN) = -(H(EN,EN) - P) / H(EN,NA)
   GO TO 730
720 Z3 = CMPLX(0.0,-H(NA,EN)) / CMPLX(H(NA,NA)-P,Q)
   H(NA,NA) = REAL(Z3)
   H(NA,EN) = AIMAG(Z3)
730 H(EN,NA) = 0.0
   H(EN,EN) = 1.0
   ENM2 = NA - 1
   IF (ENM2 .EQ. 0) GO TO 800
!     ********** FOR I=EN-2 STEP -1 UNTIL 1 DO -- **********
   do 790 II = 1, ENM2
      I = NA - II
      W = H(I,I) - P
      RA = 0.0
      SA = H(I,EN)
!
      DO J = M, NA
         RA = RA + H(I,J) * H(J,NA)
         SA = SA + H(I,J) * H(J,EN)
      END DO
!
      IF (WI(I) .GE. 0.0) GO TO 770
      ZZ = W
      R = RA
      S = SA
      GO TO 790
770 M = I
      IF (WI(I) .NE. 0.0) GO TO 780
      Z3 = CMPLX(-RA,-SA) / CMPLX(W,Q)
      H(I,NA) = REAL(Z3)
      H(I,EN) = AIMAG(Z3)
      GO TO 790
!     ********** SOLVE COMPLEX EQUATIONS **********
780 X = H(I,I+1)
      Y = H(I+1,I)
      VR = (WR(I) - P) * (WR(I) - P) + WI(I) * WI(I) - Q * Q
      VI = (WR(I) - P) * 2.0 * Q
      IF (VR .EQ. 0.0 .AND. VI .EQ. 0.0) VR = MACHEP * NORM &
&* (ABS(W) + ABS(Q) + ABS(X) + ABS(Y) + ABS(ZZ))
      Z3 = CMPLX(X*R-ZZ*RA+Q*SA,X*S-ZZ*SA-Q*RA) / CMPLX(VR,VI)
      H(I,NA) = REAL(Z3)
      H(I,EN) = AIMAG(Z3)
      IF (ABS(X) .LE. ABS(ZZ) + ABS(Q)) GO TO 785
      H(I+1,NA) = (-RA - W * H(I,NA) + Q * H(I,EN)) / X
      H(I+1,EN) = (-SA - W * H(I,EN) - Q * H(I,NA)) / X
      GO TO 790
785 Z3 = CMPLX(-R-Y*H(I,NA),-S-Y*H(I,EN)) / CMPLX(ZZ,Q)
      H(I+1,NA) = REAL(Z3)
      H(I+1,EN) = AIMAG(Z3)
790 CONTINUE
!     ********** END COMPLEX VECTOR **********
800 CONTINUE
!     ********** END BACK SUBSTITUTION.
!                VECTORS OF ISOLATED ROOTS **********
do 840 I = 1, N
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 840
!
   do 820 J = I, N
820 Z(I,J) = H(I,J)
!
840 CONTINUE
!     ********** MULTIPLY BY TRANSFORMATION MATRIX TO GIVE
!                VECTORS OF ORIGINAL FULL MATRIX.
!                FOR J=N STEP -1 UNTIL LOW DO -- **********
do 880 JJ = LOW, N
   J = N + LOW - JJ
   M = MIN0(J,IGH)
!
   do 880 I = LOW, IGH
      ZZ = 0.0
!
      do 860 K = LOW, M
860 ZZ = ZZ + Z(I,K) * H(K,J)
!
      Z(I,J) = ZZ
880 CONTINUE
!
GO TO 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 IERR = EN
1001 RETURN
END SUBROUTINE HQR2

SUBROUTINE DEIG (IBAL,A,KA,N,WR,WI,IERR)
IMPLICIT NONE
INTENT(IN) IBAL, KA, N
INTENT(INOUT) A, IERR, WI, WR
INTEGER IBAL, IERR, KA, N
INTEGER IGH, LOW
!-----------------------------------------------------------------------
!                EIGENVALUES OF DOUBLE PRECISION MATRICES
!-----------------------------------------------------------------------
DOUBLE PRECISION A(KA,N), WR(N), WI(N)
!
LOW = 1
IGH = N
IF (IBAL .NE. 0) CALL DBAL (KA,N,A,LOW,IGH,WR)
CALL DORTH (KA,N,LOW,IGH,A,WR)
CALL DHQR (KA,N,LOW,IGH,A,WR,WI,IERR)
RETURN
END SUBROUTINE DEIG

SUBROUTINE DEIGV (IBAL,A,KA,N,WR,WI,ZR,ZI,IERR)
IMPLICIT NONE
INTENT(IN) IBAL, KA, N
INTENT(INOUT) A, IERR, WI, WR, ZI, ZR
INTEGER IBAL, IERR, KA, N
INTEGER IGH, J, K, KP1, LOW
!-----------------------------------------------------------------------
!     EIGENVALUES AND EIGENVECTORS OF DOUBLE PRECISION MATRICES
!-----------------------------------------------------------------------
DOUBLE PRECISION A(KA,N),WR(N),WI(N),ZR(KA,N),ZI(KA,N)
!
LOW = 1
IGH = N
IF (IBAL .NE. 0) CALL DBAL (KA,N,A,LOW,IGH,ZI)
CALL DORTH (KA,N,LOW,IGH,A,WR)
CALL DORTRN (KA,N,LOW,IGH,A,WR,ZR)
CALL DHQR2 (KA,N,LOW,IGH,A,WR,WI,ZR,IERR)
IF (IERR .NE. 0) RETURN
IF (IBAL .NE. 0) CALL DBABK (KA,N,LOW,IGH,ZI,N,ZR)
!
do 30 K = 1,N
   IF (WI(K)) 30,10,20
10 do 11 J = 1,N
11 ZI(J,K) = 0.D0
   GO TO 30
20 KP1 = K + 1
   do 21 J = 1,N
      ZI(J,K) = ZR(J,KP1)
      ZR(J,KP1) = ZR(J,K)
21 ZI(J,KP1) = -ZI(J,K)
30 CONTINUE
RETURN
END SUBROUTINE DEIGV

SUBROUTINE DBAL(NM,N,A,LOW,IGH,SCALE)
IMPLICIT NONE
INTENT(IN) N, NM
INTENT(INOUT) A, IGH, LOW, SCALE
!
INTEGER I,J,K,L,M,N,JJ,NM,IGH,LOW,IEXC
DOUBLE PRECISION A(NM,N),SCALE(N)
DOUBLE PRECISION C,F,G,R,S,B2,RADIX
INTEGER IPMPAR
!     DOUBLE PRECISION DABS
LOGICAL NOCONV
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE BALANCE,
!     NUM. MATH. 13, 293-304(1969) BY PARLETT AND REINSCH.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 315-326(1971).
!
!     DBAL BALANCES A DOUBLE PRECISION REAL MATRIX AND ISOLATES
!     EIGENVALUES WHENEVER POSSIBLE.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        A CONTAINS THE INPUT MATRIX TO BE BALANCED.
!
!     ON OUTPUT-
!
!        A CONTAINS THE BALANCED MATRIX,
!
!        LOW AND IGH ARE TWO INTEGERS SUCH THAT A(I,J)
!          IS EQUAL TO ZERO IF
!           (1) I IS GREATER THAN J AND
!           (2) J=1,...,LOW-1 OR I=IGH+1,...,N,
!
!        SCALE CONTAINS INFORMATION DETERMINING THE
!           PERMUTATIONS AND SCALING FACTORS USED.
!
!     SUPPOSE THAT THE PRINCIPAL SUBMATRIX IN ROWS LOW THROUGH IGH
!     HAS BEEN BALANCED, THAT P(J) DENOTES THE INDEX INTERCHANGED
!     WITH J DURING THE PERMUTATION STEP, AND THAT THE ELEMENTS
!     OF THE DIAGONAL MATRIX USED ARE DENOTED BY D(I,J).  THEN
!        SCALE(J) = P(J),    FOR J = 1,...,LOW-1
!                 = D(J,J),      J = LOW,...,IGH
!                 = P(J)         J = IGH+1,...,N.
!     THE ORDER IN WHICH THE INTERCHANGES ARE MADE IS N TO IGH+1,
!     THEN 1 TO LOW-1.
!
!     NOTE THAT 1 IS RETURNED FOR IGH IF IGH IS ZERO FORMALLY.
!
!     THE ALGOL PROCEDURE EXC CONTAINED IN BALANCE APPEARS IN
!     DBAL IN LINE.  (NOTE THAT THE ALGOL ROLES OF IDENTIFIERS
!     K,L HAVE BEEN REVERSED.)
!
!-----------------------------------------------------------------------
!
!     ********** RADIX IS A MACHINE DEPENDENT PARAMETER SPECIFYING
!                THE BASE OF THE MACHINE FLOATING POINT REPRESENTATION.
!
           RADIX = IPMPAR(4)
!
!                **********
!
B2 = RADIX * RADIX
K = 1
L = N
GO TO 100
!     ********** IN-LINE PROCEDURE FOR ROW AND
!                COLUMN EXCHANGE **********
20 SCALE(M) = J
IF (J .EQ. M) GO TO 50
!
DO I = 1, L
   F = A(I,J)
   A(I,J) = A(I,M)
   A(I,M) = F
END DO
!
DO I = K, N
   F = A(J,I)
   A(J,I) = A(M,I)
   A(M,I) = F
END DO
!
50 GO TO (80,130), IEXC
!     ********** SEARCH FOR ROWS ISOLATING AN EIGENVALUE
!                AND PUSH THEM DOWN **********
80 IF (L .EQ. 1) GO TO 280
L = L - 1
!     ********** FOR J=L STEP -1 UNTIL 1 DO -- **********
100 do 120 JJ = 1, L
   J = L + 1 - JJ
!
   do 110 I = 1, L
      IF (I .EQ. J) GO TO 110
      IF (A(J,I) .NE. 0.D0) GO TO 120
110 CONTINUE
!
   M = L
   IEXC = 1
   GO TO 20
120 CONTINUE
!
GO TO 140
!     ********** SEARCH FOR COLUMNS ISOLATING AN EIGENVALUE
!                AND PUSH THEM LEFT **********
130 K = K + 1
!
140 do 170 J = K, L
!
   do 150 I = K, L
      IF (I .EQ. J) GO TO 150
      IF (A(I,J) .NE. 0.D0) GO TO 170
150 CONTINUE
!
   M = K
   IEXC = 2
   GO TO 20
170 CONTINUE
!     ********** NOW BALANCE THE SUBMATRIX IN ROWS K TO L **********
do 180 I = K, L
180 SCALE(I) = 1.D0
!     ********** ITERATIVE LOOP FOR NORM REDUCTION **********
190 NOCONV = .FALSE.
!
do 270 I = K, L
   C = 0.D0
   R = 0.D0
!
   do 200 J = K, L
      IF (J .EQ. I) GO TO 200
      C = C + DABS(A(J,I))
      R = R + DABS(A(I,J))
200 CONTINUE
!     ********** GUARD AGAINST ZERO C OR R DUE TO UNDERFLOW **********
   IF (C .EQ. 0.D0 .OR. R .EQ. 0.D0) GO TO 270
   G = R / RADIX
   F = 1.D0
   S = C + R
210 IF (C .GE. G) GO TO 220
   F = F * RADIX
   C = C * B2
   GO TO 210
220 G = R * RADIX
230 IF (C .LT. G) GO TO 240
   F = F / RADIX
   C = C / B2
   GO TO 230
!     ********** NOW BALANCE **********
240 IF ((C + R) / F .GE. 0.95D0 * S) GO TO 270
   G = 1.D0 / F
   SCALE(I) = SCALE(I) * F
   NOCONV = .TRUE.
!
   do 250 J = K, N
250 A(I,J) = A(I,J) * G
!
   do 260 J = 1, L
260 A(J,I) = A(J,I) * F
!
270 CONTINUE
!
IF (NOCONV) GO TO 190
!
280 LOW = K
IGH = L
RETURN
END SUBROUTINE DBAL

SUBROUTINE DBALNV (NZ,N,Z,LOW,IGH,SCALE)
IMPLICIT NONE
INTENT(IN) IGH, LOW, N, NZ, SCALE
INTENT(INOUT) Z
INTEGER I,J,K,N,II,NZ,IGH,LOW
DOUBLE PRECISION Z(NZ,N),SCALE(N)
DOUBLE PRECISION S
!-----------------------------------------------------------------------
!        GIVEN A MATRIX A OF ORDER N. DBAL TRANSFORMS A INTO
!     THE MATRIX B BY THE SIMILARITY TRANSFORMATION
!             B = D**(-1)*TRANSPOSE(P)*A*P*D
!     WHERE D IS A DIAGONAL MATRIX AND P A PERMUTATION MATRIX.
!     THE INFORMATION CONCERNING D AND P IS STORED IN IGH, LOW,
!     AND SCALE. THE ORDER IN WHICH THE INTERCHANGES WERE MADE
!     IS N TO IGH + 1, AND THEN 1 TO LOW - 1.
!
!        Z IS A MATRIX OF ORDER N. DBALNV TRANSFORMS Z INTO THE
!     MATRIX W USING THE INVERSE SIMILARITY TRANSFORM
!             W = P*D*Z*D**(-1)*TRANSPOSE(P)
!
!     ON INPUT-
!
!        NZ IS THE ROW DIMENSION OF THE MATRIX Z IN THE CALLING
!          PROGRAM,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY  DBAL,
!
!        SCALE CONTAINS INFORMATION DETERMINING THE PERMUTATIONS
!          AND SCALING FACTORS USED BY  DBAL,
!
!     ON OUTPUT-
!
!        Z CONTAINS THE TRANSFORMED MATRIX W
!
!-----------------------------------------------------------------------
!
IF (IGH .EQ. LOW) GO TO 30
!
DO I = LOW, IGH
S = SCALE(I)
   do 10 J = 1, N
10 Z(I,J) = Z(I,J) * S
END DO
!
DO J = LOW, IGH
S = 1.D0/SCALE(J)
   do 20 I = 1, N
20 Z(I,J) = Z(I,J) * S
END DO
!
!     ********- FOR I=LOW-1 STEP -1 UNTIL 1,
!               IGH+1 STEP 1 UNTIL N DO -- **********
!
30 do 60 II = 1, N
   I = II
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 60
   IF (I .LT. LOW) I = LOW - II
   K = SCALE(I)
   IF (K .EQ. I) GO TO 60
!
   do 40 J = 1, N
      S = Z(I,J)
      Z(I,J) = Z(K,J)
40 Z(K,J) = S
!
   do 50 J = 1, N
      S = Z(J,I)
      Z(J,I) = Z(J,K)
50 Z(J,K) = S
60 CONTINUE
RETURN
END SUBROUTINE DBALNV

SUBROUTINE DORTH(NM,N,LOW,IGH,A,ORT)
IMPLICIT NONE
INTENT(IN) IGH, LOW, N, NM
INTENT(INOUT) A, ORT
!
INTEGER I,J,M,N,II,JJ,LA,MP,NM,IGH,KP1,LOW
DOUBLE PRECISION A(NM,N),ORT(IGH)
DOUBLE PRECISION F,G,H,SCALE
!     DOUBLE PRECISION DSQRT,DABS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE ORTHES,
!     NUM. MATH. 12, 349-368(1968) BY MARTIN AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 339-358(1971).
!
!     GIVEN A REAL GENERAL MATRIX, THIS SUBROUTINE
!     REDUCES A SUBMATRIX SITUATED IN ROWS AND COLUMNS
!     LOW THROUGH IGH TO UPPER HESSENBERG FORM BY
!     ORTHOGONAL SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE DBAL.  IF DBAL HAS NOT BEEN USED THEN
!          SET LOW=1, IGH=N,
!
!        A CONTAINS THE INPUT MATRIX.
!
!     ON OUTPUT-
!
!        A CONTAINS THE HESSENBERG MATRIX.  INFORMATION ABOUT
!          THE ORTHOGONAL TRANSFORMATIONS USED IN THE REDUCTION
!          IS STORED IN THE REMAINING TRIANGLE UNDER THE
!          HESSENBERG MATRIX,
!
!        ORT CONTAINS FURTHER INFORMATION ABOUT THE TRANSFORMATIONS.
!          ONLY ELEMENTS LOW THROUGH IGH ARE USED.
!
!-----------------------------------------------------------------------
!
LA = IGH - 1
KP1 = LOW + 1
IF (LA .LT. KP1) GO TO 200
!
do 180 M = KP1, LA
   H = 0.D0
   ORT(M) = 0.D0
   SCALE = 0.D0
!     ********** SCALE COLUMN (ALGOL TOL THEN NOT NEEDED) **********
   do 90 I = M, IGH
90 SCALE = SCALE + DABS(A(I,M-1))
!
   IF (SCALE .EQ. 0.D0) GO TO 180
   MP = M + IGH
!     ********** FOR I=IGH STEP -1 UNTIL M DO -- **********
   DO II = M, IGH
      I = MP - II
      ORT(I) = A(I,M-1) / SCALE
      H = H + ORT(I) * ORT(I)
   END DO
!
   G = DSQRT(H)
   IF (ORT(M) .GE. 0.D0) G = -G
   H = H - ORT(M) * G
   ORT(M) = ORT(M) - G
!     ********** FORM (I-(U*UT)/H) * A **********
   DO J = M, N
      F = 0.D0
!     ********** FOR I=IGH STEP -1 UNTIL M DO -- **********
      DO II = M, IGH
         I = MP - II
         F = F + ORT(I) * A(I,J)
      END DO
!
      F = F / H
!
      do 120 I = M, IGH
120 A(I,J) = A(I,J) - F * ORT(I)
!
   END DO
!     ********** FORM (I-(U*UT)/H)*A*(I-(U*UT)/H) **********
   DO I = 1, IGH
      F = 0.D0
!     ********** FOR J=IGH STEP -1 UNTIL M DO -- **********
      DO JJ = M, IGH
         J = MP - JJ
         F = F + ORT(J) * A(I,J)
      END DO
!
      F = F / H
!
      do 150 J = M, IGH
150 A(I,J) = A(I,J) - F * ORT(J)
!
   END DO
!
   ORT(M) = SCALE * ORT(M)
   A(M,M-1) = SCALE * G
180 CONTINUE
!
200 RETURN
END SUBROUTINE DORTH

SUBROUTINE DHQR(NM,N,LOW,IGH,H,WR,WI,IERR)
IMPLICIT NONE
INTENT(IN) IGH, LOW, N, NM
INTENT(OUT) IERR
INTENT(INOUT) H, WI, WR
!
INTEGER I,J,K,L,M,N,EN,LL,MM,NA,NM,IGH,ITS,LOW,MP2,ENM2,IERR
DOUBLE PRECISION H(NM,N),WR(N),WI(N)
DOUBLE PRECISION P,Q,R,S,T,W,X,Y,ZZ,NORM,MACHEP,DPMPAR
!     DOUBLE PRECISION DSQRT,DABS
!     INTEGER MIN0
LOGICAL NOTLAS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE HQR,
!     NUM. MATH. 14, 219-231(1970) BY MARTIN, PETERS, AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 359-371(1971).
!
!     DHQR FINDS THE EIGENVALUES OF A DOUBLE PRECISION REAL
!     UPPER HESSENBERG MATRIX BY THE QR METHOD.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE DBAL.  IF DBAL HAS NOT BEEN USED THEN
!          SET LOW=1, IGH=N,
!
!        H CONTAINS THE UPPER HESSENBERG MATRIX.  INFORMATION ABOUT
!          THE TRANSFORMATIONS USED IN THE REDUCTION TO HESSENBERG
!          FORM BY DORTH, IF PERFORMED, IS STORED
!          IN THE REMAINING TRIANGLE UNDER THE HESSENBERG MATRIX.
!
!     ON OUTPUT-
!
!        H HAS BEEN DESTROYED.  THEREFORE, IT MUST BE SAVED
!          BEFORE CALLING  HQR  IF SUBSEQUENT CALCULATION AND
!          BACK TRANSFORMATION OF EIGENVECTORS IS TO BE PERFORMED,
!
!        WR AND WI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE EIGENVALUES.  THE EIGENVALUES
!          ARE UNORDERED EXCEPT THAT COMPLEX CONJUGATE PAIRS
!          OF VALUES APPEAR CONSECUTIVELY WITH THE EIGENVALUE
!          HAVING THE POSITIVE IMAGINARY PART FIRST.  IF AN
!          ERROR EXIT IS MADE, THE EIGENVALUES SHOULD BE CORRECT
!          FOR INDICES IERR+1,...,N,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 50 ITERATIONS.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                MACHEP THE VALUE U WHERE U IS THE SMALLEST POSITIVE
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0
!                IN THE DOUBLE PRECISION ARITHMETIC BEING USED.
!
           MACHEP = DPMPAR(1)
!
!                **********
!
IERR = 0
NORM = 0.D0
K = 1
!     ********** STORE ROOTS ISOLATED BY DBAL
!                AND COMPUTE MATRIX NORM **********
do 50 I = 1, N
!
   do 40 J = K, N
40 NORM = NORM + DABS(H(I,J))
!
   K = I
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 50
   WR(I) = H(I,I)
   WI(I) = 0.D0
50 CONTINUE
!
EN = IGH
T = 0.D0
!     ********** SEARCH FOR NEXT EIGENVALUES **********
60 IF (EN .LT. LOW) GO TO 1001
ITS = 0
NA = EN - 1
ENM2 = NA - 1
!     ********** LOOK FOR SINGLE SMALL SUB-DIAGONAL ELEMENT
!                FOR L=EN STEP -1 UNTIL LOW DO -- **********
70 DO LL = LOW, EN
   L = EN + LOW - LL
   IF (L .EQ. LOW) GO TO 100
   S = DABS(H(L-1,L-1)) + DABS(H(L,L))
   IF (S .EQ. 0.D0) S = NORM
   IF (DABS(H(L,L-1)) .LE. MACHEP * S) GO TO 100
END DO
!     ********** FORM SHIFT **********
100 X = H(EN,EN)
IF (L .EQ. EN) GO TO 270
Y = H(NA,NA)
W = H(EN,NA) * H(NA,EN)
IF (L .EQ. NA) GO TO 280
IF (ITS .EQ. 50) GO TO 1000
IF (ITS .NE. 10 .AND. ITS .NE. 20 .AND. ITS .NE. 30) GO TO 130
!     ********** FORM EXCEPTIONAL SHIFT **********
T = T + X
!
do 120 I = LOW, EN
120 H(I,I) = H(I,I) - X
!
S = DABS(H(EN,NA)) + DABS(H(NA,ENM2))
X = .75D0 * S
Y = X
W = -.4375D0 * S * S
130 ITS = ITS + 1
!     ********** LOOK FOR TWO CONSECUTIVE SMALL
!                SUB-DIAGONAL ELEMENTS.
!                FOR M=EN-2 STEP -1 UNTIL L DO -- **********
DO MM = L, ENM2
   M = ENM2 + L - MM
   ZZ = H(M,M)
   R = X - ZZ
   S = Y - ZZ
   P = (R * S - W) / H(M+1,M) + H(M,M+1)
   Q = H(M+1,M+1) - ZZ - R - S
   R = H(M+2,M+1)
   S = DABS(P) + DABS(Q) + DABS(R)
   P = P / S
   Q = Q / S
   R = R / S
   IF (M .EQ. L) GO TO 150
   IF (DABS(H(M,M-1)) * (DABS(Q) + DABS(R)) .LE. MACHEP * DABS(P) &
&* (DABS(H(M-1,M-1)) + DABS(ZZ) + DABS(H(M+1,M+1)))) GO TO 150
END DO
!
150 MP2 = M + 2
!
do 160 I = MP2, EN
   H(I,I-2) = 0.D0
   IF (I .EQ. MP2) GO TO 160
   H(I,I-3) = 0.D0
160 CONTINUE
!     ********** DOUBLE QR STEP INVOLVING ROWS L TO EN AND
!                COLUMNS M TO EN **********
do 260 K = M, NA
   NOTLAS = K .NE. NA
   IF (K .EQ. M) GO TO 170
   P = H(K,K-1)
   Q = H(K+1,K-1)
   R = 0.D0
   IF (NOTLAS) R = H(K+2,K-1)
   X = DABS(P) + DABS(Q) + DABS(R)
   IF (X .EQ. 0.D0) GO TO 260
   P = P / X
   Q = Q / X
   R = R / X
170 S = DSQRT(P*P + Q*Q + R*R)
   IF (P .LT. 0.D0) S = -S
   IF (K .EQ. M) GO TO 180
   H(K,K-1) = -S * X
   GO TO 190
180 IF (L .NE. M) H(K,K-1) = -H(K,K-1)
190 P = P + S
   X = P / S
   Y = Q / S
   ZZ = R / S
   Q = Q / P
   R = R / P
!     ********** ROW MODIFICATION **********
   DO J = K, EN
      P = H(K,J) + Q * H(K+1,J)
      IF (.NOT. NOTLAS) GO TO 200
      P = P + R * H(K+2,J)
      H(K+2,J) = H(K+2,J) - P * ZZ
200 H(K+1,J) = H(K+1,J) - P * Y
      H(K,J) = H(K,J) - P * X
   END DO
!
   J = MIN0(EN,K+3)
!     ********** COLUMN MODIFICATION **********
   DO I = L, J
      P = X * H(I,K) + Y * H(I,K+1)
      IF (.NOT. NOTLAS) GO TO 220
      P = P + ZZ * H(I,K+2)
      H(I,K+2) = H(I,K+2) - P * R
220 H(I,K+1) = H(I,K+1) - P * Q
      H(I,K) = H(I,K) - P
   END DO
!
260 CONTINUE
!
GO TO 70
!     ********** ONE ROOT FOUND **********
270 WR(EN) = X + T
WI(EN) = 0.D0
EN = NA
GO TO 60
!     ********** TWO ROOTS FOUND **********
280 P = (Y - X) / 2.D0
Q = P * P + W
ZZ = DSQRT(DABS(Q))
X = X + T
IF (Q .LT. 0.D0) GO TO 320
!     ********** REAL PAIR **********
IF (P .LT. 0.D0) ZZ = -ZZ
ZZ = P + ZZ
WR(NA) = X + ZZ
WR(EN) = WR(NA)
IF (ZZ .NE. 0.D0) WR(EN) = X - W / ZZ
WI(NA) = 0.D0
WI(EN) = 0.D0
GO TO 330
!     ********** COMPLEX PAIR **********
320 WR(NA) = X + P
WR(EN) = X + P
WI(NA) = ZZ
WI(EN) = -ZZ
330 EN = ENM2
GO TO 60
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 50 ITERATIONS **********
1000 IERR = EN
1001 RETURN
END SUBROUTINE DHQR

SUBROUTINE DBABK(NM,N,LOW,IGH,SCALE,M,Z)
IMPLICIT NONE
INTENT(IN) IGH, LOW, M, N, NM, SCALE
INTENT(INOUT) Z
!
INTEGER I,J,K,M,N,II,NM,IGH,LOW
DOUBLE PRECISION SCALE(N),Z(NM,M)
DOUBLE PRECISION S
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE BALBAK,
!     NUM. MATH. 13, 293-304(1969) BY PARLETT AND REINSCH.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 315-326(1971).
!
!     THIS SUBROUTINE FORMS THE EIGENVECTORS OF A REAL GENERAL
!     MATRIX BY BACK TRANSFORMING THOSE OF THE CORRESPONDING
!     BALANCED MATRIX DETERMINED BY DBAL.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY DBAL,
!
!        SCALE CONTAINS INFORMATION DETERMINING THE PERMUTATIONS
!          AND SCALING FACTORS USED BY DBAL,
!
!        M IS THE NUMBER OF COLUMNS OF Z TO BE BACK TRANSFORMED,
!
!        Z CONTAINS THE REAL AND IMAGINARY PARTS OF THE EIGEN-
!          VECTORS TO BE BACK TRANSFORMED IN ITS FIRST M COLUMNS.
!
!     ON OUTPUT-
!
!        Z CONTAINS THE REAL AND IMAGINARY PARTS OF THE
!          TRANSFORMED EIGENVECTORS IN ITS FIRST M COLUMNS.
!
!-----------------------------------------------------------------------
!
IF (M .EQ. 0) GO TO 200
IF (IGH .EQ. LOW) GO TO 120
!
DO I = LOW, IGH
   S = SCALE(I)
!     ********** LEFT HAND EIGENVECTORS ARE BACK TRANSFORMED
!                IF THE FOREGOING STATEMENT IS REPLACED BY
!                S=1.0/SCALE(I). **********
   do 100 J = 1, M
100 Z(I,J) = Z(I,J) * S
!
END DO
!     ********- FOR I=LOW-1 STEP -1 UNTIL 1,
!               IGH+1 STEP 1 UNTIL N DO -- **********
120 do 140 II = 1, N
   I = II
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 140
   IF (I .LT. LOW) I = LOW - II
   K = SCALE(I)
   IF (K .EQ. I) GO TO 140
!
   DO J = 1, M
      S = Z(I,J)
      Z(I,J) = Z(K,J)
      Z(K,J) = S
   END DO
!
140 CONTINUE
!
200 RETURN
END SUBROUTINE DBABK

SUBROUTINE DORTRN(NM,N,LOW,IGH,A,ORT,Z)
IMPLICIT NONE
INTENT(IN) A, IGH, LOW, N, NM
INTENT(INOUT) ORT, Z
!
INTEGER I,J,N,KL,MM,MP,NM,IGH,LOW,MP1
DOUBLE PRECISION A(NM,IGH),ORT(IGH),Z(NM,N)
DOUBLE PRECISION G
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE ORTRANS,
!     NUM. MATH. 16, 181-204(1970) BY PETERS AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 372-395(1971).
!
!     THIS SUBROUTINE ACCUMULATES THE ORTHOGONAL SIMILARITY
!     TRANSFORMATIONS USED IN THE REDUCTION OF A REAL DOUBLE
!     PRECISION MATRIX TO UPPER HESSENBERG FORM BY DORTH.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE DBAL.  IF DBAL HAS NOT BEEN USED THEN
!          SET LOW=1, IGH=N,
!
!        A CONTAINS INFORMATION ABOUT THE ORTHOGONAL TRANS-
!          FORMATIONS USED IN THE REDUCTION BY DORTH
!          IN ITS STRICT LOWER TRIANGLE,
!
!        ORT CONTAINS FURTHER INFORMATION ABOUT THE TRANS-
!          FORMATIONS USED IN THE REDUCTION BY DORTH.
!          ONLY ELEMENTS LOW THROUGH IGH ARE USED.
!
!     ON OUTPUT-
!
!        Z CONTAINS THE TRANSFORMATION MATRIX PRODUCED IN THE
!          REDUCTION BY DORTH,
!
!        ORT HAS BEEN ALTERED.
!
!-----------------------------------------------------------------------
!
!     ********** INITIALIZE Z TO IDENTITY MATRIX **********
DO I = 1, N
!
   do 60 J = 1, N
60 Z(I,J) = 0.D0
!
   Z(I,I) = 1.D0
END DO
!
KL = IGH - LOW - 1
IF (KL .LT. 1) GO TO 200
!     ********** FOR MP=IGH-1 STEP -1 UNTIL LOW+1 DO -- **********
do 140 MM = 1, KL
   MP = IGH - MM
   IF (A(MP,MP-1) .EQ. 0.D0) GO TO 140
   MP1 = MP + 1
!
   do 100 I = MP1, IGH
100 ORT(I) = A(I,MP-1)
!
   DO J = MP, IGH
      G = 0.D0
!
      do 110 I = MP, IGH
110 G = G + ORT(I) * Z(I,J)
!     ********** DIVISOR BELOW IS NEGATIVE OF H FORMED IN ORTHES.
!                DOUBLE DIVISION AVOIDS POSSIBLE UNDERFLOW **********
      G = (G / ORT(MP)) / A(MP,MP-1)
!
      do 120 I = MP, IGH
120 Z(I,J) = Z(I,J) + G * ORT(I)
!
   END DO
!
140 CONTINUE
!
200 RETURN
END SUBROUTINE DORTRN

SUBROUTINE DRTRN1(N,LOW,IGH,A,NA,Z,NZ,ORT)
IMPLICIT NONE
INTENT(IN) A, IGH, LOW, N, NA, NZ
INTENT(INOUT) ORT, Z
!
INTEGER I,J,N,KL,MM,MP,NA,IGH,LOW,MP1,NZ
DOUBLE PRECISION A(NA,IGH),ORT(IGH),Z(NZ,N)
DOUBLE PRECISION G
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE ORTRANS,
!     NUM. MATH. 16, 181-204(1970) BY PETERS AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 372-395(1971).
!
!     THIS SUBROUTINE ACCUMULATES THE ORTHOGONAL SIMILARITY
!     TRANSFORMATIONS USED IN THE REDUCTION OF A REAL DOUBLE
!     PRECISION MATRIX TO UPPER HESSENBERG FORM BY DORTH.
!
!     ON INPUT-
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE DBAL.  IF DBAL HAS NOT BEEN USED THEN
!          SET LOW=1, IGH=N,
!
!        A CONTAINS INFORMATION ABOUT THE ORTHOGONAL TRANS-
!          FORMATIONS USED IN THE REDUCTION BY DORTH
!          IN ITS STRICT LOWER TRIANGLE,
!
!        NA MUST BE SET TO THE ROW DIMENSION OF THE 2-DIMENSIONAL
!          ARRAY PARAMETER  A  AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        NZ MUST BE SET TO THE ROW DIMENSION OF THE 2-DIMENSIONAL
!          ARRAY PARAMETER  Z  AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        ORT CONTAINS FURTHER INFORMATION ABOUT THE TRANS-
!          FORMATIONS USED IN THE REDUCTION BY DORTH.
!          ONLY ELEMENTS LOW THROUGH IGH ARE USED.
!
!     ON OUTPUT-
!
!        Z CONTAINS THE TRANSFORMATION MATRIX PRODUCED IN THE
!          REDUCTION BY DORTH,
!
!        ORT HAS BEEN ALTERED.
!
!-----------------------------------------------------------------------
!
!     ********** INITIALIZE Z TO IDENTITY MATRIX **********
DO I = 1, N
!
   do 60 J = 1, N
60 Z(I,J) = 0.D0
!
   Z(I,I) = 1.D0
END DO
!
KL = IGH - LOW - 1
IF (KL .LT. 1) GO TO 200
!     ********** FOR MP=IGH-1 STEP -1 UNTIL LOW+1 DO -- **********
do 140 MM = 1, KL
   MP = IGH - MM
   IF (A(MP,MP-1) .EQ. 0.D0) GO TO 140
   MP1 = MP + 1
!
   do 100 I = MP1, IGH
100 ORT(I) = A(I,MP-1)
!
   DO J = MP, IGH
      G = 0.D0
!
      do 110 I = MP, IGH
110 G = G + ORT(I) * Z(I,J)
!     ********** DIVISOR BELOW IS NEGATIVE OF H FORMED IN ORTHES.
!                DOUBLE DIVISION AVOIDS POSSIBLE UNDERFLOW **********
      G = (G / ORT(MP)) / A(MP,MP-1)
!
      do 120 I = MP, IGH
120 Z(I,J) = Z(I,J) + G * ORT(I)
!
   END DO
!
140 CONTINUE
!
200 RETURN
END SUBROUTINE DRTRN1

SUBROUTINE DHQR2(NM,N,LOW,IGH,H,WR,WI,Z,IERR)
IMPLICIT NONE
INTENT(IN) IGH, LOW, N, NM
INTENT(OUT) IERR
INTENT(INOUT) H, WI, WR, Z
!
INTEGER I,J,K,L,M,N,EN,II,JJ,LL,MM,NA,NM,NN, &
&IGH,ITS,LOW,MP2,ENM2,IERR
DOUBLE PRECISION H(NM,N),WR(N),WI(N),Z(NM,N)
DOUBLE PRECISION A,B,D,P,Q,R,S,T,U,W,X,Y
DOUBLE PRECISION RA,SA,VI,VR,ZZ,NORM,MACHEP
!     INTEGER MIN0
!     DOUBLE PRECISION DSQRT,DABS
DOUBLE PRECISION DPMPAR
LOGICAL NOTLAS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE HQR2,
!     NUM. MATH. 16, 181-204(1970) BY PETERS AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 372-395(1971).
!
!     THIS SUBROUTINE FINDS THE EIGENVALUES AND EIGENVECTORS
!     OF A REAL DOUBLE PRECISION UPPER HESSENBERG MATRIX BY THE
!     QR METHOD.  THE EIGENVECTORS OF A REAL GENERAL MATRIX CAN
!     ALSO BE FOUND IF DORTH AND DORTRN HAVE BEEN USED TO REDUCE
!     THIS GENERAL MATRIX TO HESSENBERG FORM AND TO ACCUMULATE
!     THE SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE DBAL.  IF DBAL HAS NOT BEEN USED THEN
!          SET LOW=1, IGH=N,
!
!        H CONTAINS THE UPPER HESSENBERG MATRIX,
!
!        Z CONTAINS THE TRANSFORMATION MATRIX PRODUCED BY DORTRN
!          AFTER THE REDUCTION BY DORTH, IF PERFORMED. IF THE
!          EIGENVECTORS OF THE HESSENBERG MATRIX ARE DESIRED,
!          Z MUST CONTAIN THE IDENTITY MATRIX.
!
!     ON OUTPUT-
!
!        H HAS BEEN DESTROYED,
!
!        WR AND WI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE EIGENVALUES.  THE EIGENVALUES
!          ARE UNORDERED EXCEPT THAT COMPLEX CONJUGATE PAIRS
!          OF VALUES APPEAR CONSECUTIVELY WITH THE EIGENVALUE
!          HAVING THE POSITIVE IMAGINARY PART FIRST.  IF AN
!          ERROR EXIT IS MADE, THE EIGENVALUES SHOULD BE CORRECT
!          FOR INDICES IERR+1,...,N,
!
!        Z CONTAINS THE REAL AND IMAGINARY PARTS OF THE EIGENVECTORS.
!          IF THE I-TH EIGENVALUE IS REAL, THE I-TH COLUMN OF Z
!          CONTAINS ITS EIGENVECTOR.  IF THE I-TH EIGENVALUE IS COMPLEX
!          WITH POSITIVE IMAGINARY PART, THE I-TH AND (I+1)-TH
!          COLUMNS OF Z CONTAIN THE REAL AND IMAGINARY PARTS OF ITS
!          EIGENVECTOR.  THE EIGENVECTORS ARE UNNORMALIZED.  IF AN
!          ERROR EXIT IS MADE, NONE OF THE EIGENVECTORS HAS BEEN FOUND,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 50 ITERATIONS.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                MACHEP THE VALUE U WHERE U IS THE SMALLEST POSITIVE
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0
!                IN THE DOUBLE PRECISION ARITHMETIC BEING USED.
!
           MACHEP = DPMPAR(1)
!
!                **********
!
IERR = 0
NORM = 0.D0
K = 1
!     ********** STORE ROOTS ISOLATED BY DBAL
!                AND COMPUTE MATRIX NORM **********
do 50 I = 1, N
!
   do 40 J = K, N
40 NORM = NORM + DABS(H(I,J))
!
   K = I
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 50
   WR(I) = H(I,I)
   WI(I) = 0.D0
50 CONTINUE
!
EN = IGH
T = 0.D0
!     ********** SEARCH FOR NEXT EIGENVALUES **********
60 IF (EN .LT. LOW) GO TO 340
ITS = 0
NA = EN - 1
ENM2 = NA - 1
!     ********** LOOK FOR SINGLE SMALL SUB-DIAGONAL ELEMENT
!                FOR L=EN STEP -1 UNTIL LOW DO -- **********
70 DO LL = LOW, EN
   L = EN + LOW - LL
   IF (L .EQ. LOW) GO TO 100
   S = DABS(H(L-1,L-1)) + DABS(H(L,L))
   IF (S .EQ. 0.D0) S = NORM
   IF (DABS(H(L,L-1)) .LE. MACHEP * S) GO TO 100
END DO
!     ********** FORM SHIFT **********
100 X = H(EN,EN)
IF (L .EQ. EN) GO TO 270
Y = H(NA,NA)
W = H(EN,NA) * H(NA,EN)
IF (L .EQ. NA) GO TO 280
IF (ITS .EQ. 50) GO TO 1000
IF (ITS .NE. 10 .AND. ITS .NE. 20 .AND. ITS .NE. 30) GO TO 130
!     ********** FORM EXCEPTIONAL SHIFT **********
T = T + X
!
do 120 I = LOW, EN
120 H(I,I) = H(I,I) - X
!
S = DABS(H(EN,NA)) + DABS(H(NA,ENM2))
X = .75D0 * S
Y = X
W = -.4375D0 * S * S
130 ITS = ITS + 1
!     ********** LOOK FOR TWO CONSECUTIVE SMALL
!                SUB-DIAGONAL ELEMENTS.
!                FOR M=EN-2 STEP -1 UNTIL L DO -- **********
DO MM = L, ENM2
   M = ENM2 + L - MM
   ZZ = H(M,M)
   R = X - ZZ
   S = Y - ZZ
   P = (R * S - W) / H(M+1,M) + H(M,M+1)
   Q = H(M+1,M+1) - ZZ - R - S
   R = H(M+2,M+1)
   S = DABS(P) + DABS(Q) + DABS(R)
   P = P / S
   Q = Q / S
   R = R / S
   IF (M .EQ. L) GO TO 150
   IF (DABS(H(M,M-1)) * (DABS(Q) + DABS(R)) .LE. MACHEP * DABS(P) &
&* (DABS(H(M-1,M-1)) + DABS(ZZ) + DABS(H(M+1,M+1)))) GO TO 150
END DO
!
150 MP2 = M + 2
!
do 160 I = MP2, EN
   H(I,I-2) = 0.D0
   IF (I .EQ. MP2) GO TO 160
   H(I,I-3) = 0.D0
160 CONTINUE
!     ********** DOUBLE QR STEP INVOLVING ROWS L TO EN AND
!                COLUMNS M TO EN **********
do 260 K = M, NA
   NOTLAS = K .NE. NA
   IF (K .EQ. M) GO TO 170
   P = H(K,K-1)
   Q = H(K+1,K-1)
   R = 0.D0
   IF (NOTLAS) R = H(K+2,K-1)
   X = DABS(P) + DABS(Q) + DABS(R)
   IF (X .EQ. 0.D0) GO TO 260
   P = P / X
   Q = Q / X
   R = R / X
170 S = DSQRT(P*P + Q*Q + R*R)
   IF (P .LT. 0.D0) S = -S
   IF (K .EQ. M) GO TO 180
   H(K,K-1) = -S * X
   GO TO 190
180 IF (L .NE. M) H(K,K-1) = -H(K,K-1)
190 P = P + S
   X = P / S
   Y = Q / S
   ZZ = R / S
   Q = Q / P
   R = R / P
!     ********** ROW MODIFICATION **********
   DO J = K, N
      P = H(K,J) + Q * H(K+1,J)
      IF (.NOT. NOTLAS) GO TO 200
      P = P + R * H(K+2,J)
      H(K+2,J) = H(K+2,J) - P * ZZ
200 H(K+1,J) = H(K+1,J) - P * Y
      H(K,J) = H(K,J) - P * X
   END DO
!
   J = MIN0(EN,K+3)
!     ********** COLUMN MODIFICATION **********
   DO I = 1, J
      P = X * H(I,K) + Y * H(I,K+1)
      IF (.NOT. NOTLAS) GO TO 220
      P = P + ZZ * H(I,K+2)
      H(I,K+2) = H(I,K+2) - P * R
220 H(I,K+1) = H(I,K+1) - P * Q
      H(I,K) = H(I,K) - P
   END DO
!     ********** ACCUMULATE TRANSFORMATIONS **********
   DO I = LOW, IGH
      P = X * Z(I,K) + Y * Z(I,K+1)
      IF (.NOT. NOTLAS) GO TO 240
      P = P + ZZ * Z(I,K+2)
      Z(I,K+2) = Z(I,K+2) - P * R
240 Z(I,K+1) = Z(I,K+1) - P * Q
      Z(I,K) = Z(I,K) - P
   END DO
!
260 CONTINUE
!
GO TO 70
!     ********** ONE ROOT FOUND **********
270 H(EN,EN) = X + T
WR(EN) = H(EN,EN)
WI(EN) = 0.D0
EN = NA
GO TO 60
!     ********** TWO ROOTS FOUND **********
280 P = (Y - X) / 2.D0
Q = P * P + W
ZZ = DSQRT(DABS(Q))
H(EN,EN) = X + T
X = H(EN,EN)
H(NA,NA) = Y + T
IF (Q .LT. 0.D0) GO TO 320
!     ********** REAL PAIR **********
IF (P .LT. 0.D0) ZZ = -ZZ
ZZ = P + ZZ
WR(NA) = X + ZZ
WR(EN) = WR(NA)
IF (ZZ .NE. 0.D0) WR(EN) = X - W / ZZ
WI(NA) = 0.D0
WI(EN) = 0.D0
X = H(EN,NA)
S = DABS(X) + DABS(ZZ)
P = X / S
Q = ZZ / S
R = DSQRT(P*P+Q*Q)
P = P / R
Q = Q / R
!     ********** ROW MODIFICATION **********
DO J = NA, N
   ZZ = H(NA,J)
   H(NA,J) = Q * ZZ + P * H(EN,J)
   H(EN,J) = Q * H(EN,J) - P * ZZ
END DO
!     ********** COLUMN MODIFICATION **********
DO I = 1, EN
   ZZ = H(I,NA)
   H(I,NA) = Q * ZZ + P * H(I,EN)
   H(I,EN) = Q * H(I,EN) - P * ZZ
END DO
!     ********** ACCUMULATE TRANSFORMATIONS **********
DO I = LOW, IGH
   ZZ = Z(I,NA)
   Z(I,NA) = Q * ZZ + P * Z(I,EN)
   Z(I,EN) = Q * Z(I,EN) - P * ZZ
END DO
!
GO TO 330
!     ********** COMPLEX PAIR **********
320 WR(NA) = X + P
WR(EN) = X + P
WI(NA) = ZZ
WI(EN) = -ZZ
330 EN = ENM2
GO TO 60
!     ********** ALL ROOTS FOUND.  BACKSUBSTITUTE TO FIND
!                VECTORS OF UPPER TRIANGULAR FORM **********
340 IF (NORM .EQ. 0.D0) GO TO 1001
!     ********** FOR EN=N STEP -1 UNTIL 1 DO -- **********
do 800 NN = 1, N
   EN = N + 1 - NN
   P = WR(EN)
   Q = WI(EN)
   NA = EN - 1
   IF (Q) 710, 600, 800
!     ********** REAL VECTOR **********
600 M = EN
   H(EN,EN) = 1.D0
   IF (NA .EQ. 0) GO TO 800
!     ********** FOR I=EN-1 STEP -1 UNTIL 1 DO -- **********
   do 700 II = 1, NA
      I = EN - II
      W = H(I,I) - P
      R = H(I,EN)
      IF (M .GT. NA) GO TO 620
!
      do 610 J = M, NA
610 R = R + H(I,J) * H(J,EN)
!
620 IF (WI(I) .GE. 0.D0) GO TO 630
      ZZ = W
      S = R
      GO TO 700
630 M = I
      IF (WI(I) .NE. 0.D0) GO TO 640
      T = W
      IF (W .EQ. 0.D0) T = MACHEP * NORM
      H(I,EN) = -R / T
      GO TO 700
!     ********** SOLVE REAL EQUATIONS **********
640 X = H(I,I+1)
      Y = H(I+1,I)
      Q = (WR(I) - P) * (WR(I) - P) + WI(I) * WI(I)
      T = (X * S - ZZ * R) / Q
      H(I,EN) = T
      IF (DABS(X) .LE. DABS(ZZ)) GO TO 650
      H(I+1,EN) = (-R - W * T) / X
      GO TO 700
650 H(I+1,EN) = (-S - Y * T) / ZZ
700 CONTINUE
!     ********** END REAL VECTOR **********
   GO TO 800
!     ********** COMPLEX VECTOR **********
710 M = NA
!     ********** LAST VECTOR COMPONENT CHOSEN IMAGINARY SO THAT
!                EIGENVECTOR MATRIX IS TRIANGULAR **********
   IF (DABS(H(EN,NA)) .LE. DABS(H(NA,EN))) GO TO 720
   H(NA,NA) = Q / H(EN,NA)
   H(NA,EN) = -(H(EN,EN) - P) / H(EN,NA)
   GO TO 730
720 U = H(NA,NA) - P
   B = -H(NA,EN) / (U * U + Q * Q)
   H(NA,NA) = B * Q
   H(NA,EN) = B * U
730 H(EN,NA) = 0.D0
   H(EN,EN) = 1.D0
   ENM2 = NA - 1
   IF (ENM2 .EQ. 0) GO TO 800
!     ********** FOR I=EN-2 STEP -1 UNTIL 1 DO -- **********
   do 790 II = 1, ENM2
      I = NA - II
      W = H(I,I) - P
      RA = 0.D0
      SA = H(I,EN)
!
      DO J = M, NA
         RA = RA + H(I,J) * H(J,NA)
         SA = SA + H(I,J) * H(J,EN)
      END DO
!
      IF (WI(I) .GE. 0.D0) GO TO 770
      ZZ = W
      R = RA
      S = SA
      GO TO 790
770 M = I
      IF (WI(I) .NE. 0.D0) GO TO 780
      D = W * W + Q * Q
      H(I,NA) = -(RA * W + SA * Q) / D
      H(I,EN) = (RA * Q - SA * W) / D
      GO TO 790
!     ********** SOLVE COMPLEX EQUATIONS **********
780 X = H(I,I+1)
      Y = H(I+1,I)
      VR = (WR(I) - P) * (WR(I) - P) + WI(I) * WI(I) - Q * Q
      VI = (WR(I) - P) * 2.D0 * Q
      IF (VR .EQ. 0.D0 .AND. VI .EQ. 0.D0) VR = MACHEP * NORM &
&* (DABS(W) + DABS(Q) + DABS(X) + DABS(Y) + DABS(ZZ))
      A = X * R - ZZ * RA + Q * SA
      B = X * S - ZZ * SA - Q * RA
      D = VR * VR + VI * VI
      H(I,NA) = (A * VR + B * VI) / D
      H(I,EN) = (B * VR - A * VI) / D
      IF (DABS(X) .LE. DABS(ZZ) + DABS(Q)) GO TO 785
      H(I+1,NA) = (-RA - W * H(I,NA) + Q * H(I,EN)) / X
      H(I+1,EN) = (-SA - W * H(I,EN) - Q * H(I,NA)) / X
      GO TO 790
785 A = -R - Y * H(I,NA)
      B = -S - Y * H(I,EN)
      D = ZZ * ZZ + Q * Q
      H(I+1,NA) = (A * ZZ + B * Q) / D
      H(I+1,EN) = (B * ZZ - A * Q) / D
790 CONTINUE
!     ********** END COMPLEX VECTOR **********
800 CONTINUE
!     ********** END BACK SUBSTITUTION.
!                VECTORS OF ISOLATED ROOTS **********
do 840 I = 1, N
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 840
!
   do 820 J = I, N
820 Z(I,J) = H(I,J)
!
840 CONTINUE
!     ********** MULTIPLY BY TRANSFORMATION MATRIX TO GIVE
!                VECTORS OF ORIGINAL FULL MATRIX.
!                FOR J=N STEP -1 UNTIL LOW DO -- **********
do 880 JJ = LOW, N
   J = N + LOW - JJ
   M = MIN0(J,IGH)
!
   do 880 I = LOW, IGH
      ZZ = 0.D0
!
      do 860 K = LOW, M
860 ZZ = ZZ + Z(I,K) * H(K,J)
!
      Z(I,J) = ZZ
880 CONTINUE
!
GO TO 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 50 ITERATIONS **********
1000 IERR = EN
1001 RETURN
END SUBROUTINE DHQR2

SUBROUTINE SEIG (A, KA, N, W, T, IERR)
IMPLICIT NONE
INTENT(IN) KA
INTENT(INOUT) A, IERR, T, W
INTEGER IERR, KA, N
INTEGER L
!-----------------------------------------------------------------------
!               EIGENVALUES OF SYMMETRIC REAL MATRICES
!-----------------------------------------------------------------------
REAL A(*), W(N), T(*)
!
IF (KA .EQ. 0) GO TO 10
   CALL TRED1 (KA, N, A, W, T(N+1), T(1))
   CALL TQLRAT (N, W, T, IERR)
   RETURN
10 L = N*(N + 1)
L = L/2
CALL TRED3 (N, L, A, W, T(N+1), T(1))
CALL TQLRAT (N, W, T, IERR)
RETURN
END SUBROUTINE SEIG

SUBROUTINE SEIG1 (A, KA, N, W, T, IERR)
IMPLICIT NONE
INTENT(IN) KA, N
INTENT(INOUT) A, IERR, T, W
INTEGER IERR, KA, N
INTEGER L
!-----------------------------------------------------------------------
!               EIGENVALUES OF SYMMETRIC REAL MATRICES
!-----------------------------------------------------------------------
REAL A(*), W(N), T(N)
!
IF (KA .EQ. 0) GO TO 10
   CALL TRED1 (KA, N, A, W, T, T)
   CALL IMTQL1 (N, W, T, IERR)
   RETURN
10 L = N*(N + 1)
L = L/2
CALL TRED3 (N, L, A, W, T, T)
CALL IMTQL1 (N, W, T, IERR)
RETURN
END SUBROUTINE SEIG1

SUBROUTINE SEIGV (A, KA, N, W, Z, T, IERR)
IMPLICIT NONE
INTENT(IN) A, KA, N
INTENT(INOUT) IERR, T, W, Z
INTEGER IERR, KA, N
!-----------------------------------------------------------------------
!        EIGENVALUES AND EIGENVECTORS OF SYMMETRIC REAL MATRICES
!-----------------------------------------------------------------------
REAL A(KA,N), W(N), Z(KA,N), T(N)
!
CALL TRED2 (KA, N, A, W, T, Z)
CALL TQL2 (KA, N, W, T, Z, IERR)
RETURN
END SUBROUTINE SEIGV

SUBROUTINE SEIGV1 (A, KA, N, W, Z, T, IERR)
IMPLICIT NONE
INTENT(IN) A, KA, N
INTENT(INOUT) IERR, T, W, Z
INTEGER IERR, KA, N
!-----------------------------------------------------------------------
!        EIGENVALUES AND EIGENVECTORS OF SYMMETRIC REAL MATRICES
!-----------------------------------------------------------------------
REAL A(KA,N), W(N), Z(KA,N), T(N)
!
CALL TRED2 (KA, N, A, W, T, Z)
CALL IMTQL2 (KA, N, W, T, Z, IERR)
RETURN
END SUBROUTINE SEIGV1

SUBROUTINE TRED1(NM,N,A,D,E,E2)
IMPLICIT NONE
INTENT(IN) N, NM
INTENT(INOUT) A, D, E, E2
!
INTEGER I,J,K,L,N,II,NM,JP1
REAL A(NM,N),D(N),E(N),E2(N)
REAL F,G,H,SCALE
!     REAL SQRT,ABS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE TRED1,
!     NUM. MATH. 11, 181-195(1968) BY MARTIN, REINSCH, AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 212-226(1971).
!
!     THIS SUBROUTINE REDUCES A REAL SYMMETRIC MATRIX
!     TO A SYMMETRIC TRIDIAGONAL MATRIX USING
!     ORTHOGONAL SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        A CONTAINS THE REAL SYMMETRIC INPUT MATRIX.  ONLY THE
!          LOWER TRIANGLE OF THE MATRIX NEED BE SUPPLIED.
!
!     ON OUTPUT-
!
!        A CONTAINS INFORMATION ABOUT THE ORTHOGONAL TRANS-
!          FORMATIONS USED IN THE REDUCTION IN ITS STRICT LOWER
!          TRIANGLE.  THE FULL UPPER TRIANGLE OF A IS UNALTERED,
!
!        D CONTAINS THE DIAGONAL ELEMENTS OF THE TRIDIAGONAL MATRIX,
!
!        E CONTAINS THE SUBDIAGONAL ELEMENTS OF THE TRIDIAGONAL
!          MATRIX IN ITS LAST N-1 POSITIONS.  E(1) IS SET TO ZERO,
!
!        E2 CONTAINS THE SQUARES OF THE CORRESPONDING ELEMENTS OF E.
!          E2 MAY COINCIDE WITH E IF THE SQUARES ARE NOT NEEDED.
!
!-----------------------------------------------------------------------
!
do 100 I = 1, N
100 D(I) = A(I,I)
!     ********** FOR I=N STEP -1 UNTIL 1 DO -- **********
DO II = 1, N
   I = N + 1 - II
   L = I - 1
   H = 0.0
   SCALE = 0.0
   IF (L .LT. 1) GO TO 130
!     ********** SCALE ROW (ALGOL TOL THEN NOT NEEDED) **********
   do 120 K = 1, L
120 SCALE = SCALE + ABS(A(I,K))
!
   IF (SCALE .NE. 0.0) GO TO 140
130 E(I) = 0.0
   E2(I) = 0.0
   GO TO 290
!
140 DO K = 1, L
      A(I,K) = A(I,K) / SCALE
      H = H + A(I,K) * A(I,K)
   END DO
!
   E2(I) = SCALE * SCALE * H
   F = A(I,L)
   G = SQRT(H)
   IF (F .GE. 0.0) G = -G
   E(I) = SCALE * G
   H = H - F * G
   A(I,L) = F - G
   IF (L .EQ. 1) GO TO 270
   F = 0.0
!
   DO J = 1, L
      G = 0.0
!     ********** FORM ELEMENT OF A*U **********
      do 180 K = 1, J
180 G = G + A(J,K) * A(I,K)
!
      JP1 = J + 1
      IF (L .LT. JP1) GO TO 220
!
      do 200 K = JP1, L
200 G = G + A(K,J) * A(I,K)
!     ********** FORM ELEMENT OF P **********
220 E(J) = G / H
      F = F + E(J) * A(I,J)
   END DO
!
   H = F / (H + H)
!     ********** FORM REDUCED A **********
   do 260 J = 1, L
      F = A(I,J)
      G = E(J) - H * F
      E(J) = G
!
      do 260 K = 1, J
         A(J,K) = A(J,K) - F * E(K) - G * A(I,K)
260 CONTINUE
!
270 do 280 K = 1, L
280 A(I,K) = SCALE * A(I,K)
!
290 H = D(I)
   D(I) = A(I,I)
   A(I,I) = H
END DO
!
RETURN
!     ********** LAST CARD OF TRED1 **********
END SUBROUTINE TRED1

SUBROUTINE TRED3(N,NV,A,D,E,E2)
IMPLICIT NONE
INTENT(IN) N, NV
INTENT(INOUT) A, D, E, E2
!
INTEGER I,J,K,L,N,II,IZ,JK,NV
REAL A(NV),D(N),E(N),E2(N)
REAL F,G,H,HH,SCALE
!     REAL SQRT,ABS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE TRED3,
!     NUM. MATH. 11, 181-195(1968) BY MARTIN, REINSCH, AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 212-226(1971).
!
!     THIS SUBROUTINE REDUCES A REAL SYMMETRIC MATRIX, STORED AS
!     A ONE-DIMENSIONAL ARRAY, TO A SYMMETRIC TRIDIAGONAL MATRIX
!     USING ORTHOGONAL SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        N IS THE ORDER OF THE MATRIX,
!
!        NV MUST BE SET TO THE DIMENSION OF THE ARRAY PARAMETER A
!          AS DECLARED IN THE CALLING PROGRAM DIMENSION STATEMENT,
!
!        A CONTAINS THE LOWER TRIANGLE OF THE REAL SYMMETRIC
!          INPUT MATRIX, STORED ROW-WISE AS A ONE-DIMENSIONAL
!          ARRAY, IN ITS FIRST N*(N+1)/2 POSITIONS.
!
!     ON OUTPUT-
!
!        A CONTAINS INFORMATION ABOUT THE ORTHOGONAL
!          TRANSFORMATIONS USED IN THE REDUCTION,
!
!        D CONTAINS THE DIAGONAL ELEMENTS OF THE TRIDIAGONAL MATRIX,
!
!        E CONTAINS THE SUBDIAGONAL ELEMENTS OF THE TRIDIAGONAL
!          MATRIX IN ITS LAST N-1 POSITIONS.  E(1) IS SET TO ZERO,
!
!        E2 CONTAINS THE SQUARES OF THE CORRESPONDING ELEMENTS OF E.
!          E2 MAY COINCIDE WITH E IF THE SQUARES ARE NOT NEEDED.
!
!-----------------------------------------------------------------------
!
!     ********** FOR I=N STEP -1 UNTIL 1 DO -- **********
DO II = 1, N
   I = N + 1 - II
   L = I - 1
   IZ = (I * L) / 2
   H = 0.0
   SCALE = 0.0
   IF (L .LT. 1) GO TO 130
!     ********** SCALE ROW (ALGOL TOL THEN NOT NEEDED) **********
   DO K = 1, L
      IZ = IZ + 1
      D(K) = A(IZ)
      SCALE = SCALE + ABS(D(K))
   END DO
!
   IF (SCALE .NE. 0.0) GO TO 140
130 E(I) = 0.0
   E2(I) = 0.0
   GO TO 290
!
140 DO K = 1, L
      D(K) = D(K) / SCALE
      H = H + D(K) * D(K)
   END DO
!
   E2(I) = SCALE * SCALE * H
   F = D(L)
   G = SQRT(H)
   IF (F .GE. 0.0) G = -G
   E(I) = SCALE * G
   H = H - F * G
   D(L) = F - G
   A(IZ) = SCALE * D(L)
   IF (L .EQ. 1) GO TO 290
   F = 0.0
!
   DO J = 1, L
      G = 0.0
      JK = (J * (J-1)) / 2
!     ********** FORM ELEMENT OF A*U **********
      DO K = 1, L
         JK = JK + 1
         IF (K .GT. J) JK = JK + K - 2
         G = G + A(JK) * D(K)
      END DO
!     ********** FORM ELEMENT OF P **********
      E(J) = G / H
      F = F + E(J) * D(J)
   END DO
!
   HH = F / (H + H)
   JK = 0
!     ********** FORM REDUCED A **********
   do 260 J = 1, L
      F = D(J)
      G = E(J) - HH * F
      E(J) = G
!
      do 260 K = 1, J
         JK = JK + 1
         A(JK) = A(JK) - F * E(K) - G * D(K)
260 CONTINUE
!
290 D(I) = A(IZ+1)
   A(IZ+1) = SCALE * SQRT(H)
END DO
!
RETURN
!     ********** LAST CARD OF TRED3 **********
END SUBROUTINE TRED3

SUBROUTINE TQLRAT(N,D,E2,IERR)
IMPLICIT NONE
INTENT(IN) N
INTENT(OUT) IERR
INTENT(INOUT) D, E2
REAL SPMPAR
!
INTEGER I,J,L,M,N,II,L1,MML,IERR
REAL D(N),E2(N)
REAL B,C,F,G,H,P,R,S,MACHEP
!     REAL SQRT,ABS,SPMPAR
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE TQLRAT,
!     ALGORITHM 464, COMM. ACM 16, 689(1973) BY REINSCH.
!
!     THIS SUBROUTINE FINDS THE EIGENVALUES OF A SYMMETRIC
!     TRIDIAGONAL MATRIX BY THE RATIONAL QL METHOD.
!
!     ON INPUT-
!
!        N IS THE ORDER OF THE MATRIX,
!
!        D CONTAINS THE DIAGONAL ELEMENTS OF THE INPUT MATRIX,
!
!        E2 CONTAINS THE SQUARES OF THE SUBDIAGONAL ELEMENTS OF THE
!          INPUT MATRIX IN ITS LAST N-1 POSITIONS.  E2(1) IS ARBITRARY.
!
!      ON OUTPUT-
!
!        D CONTAINS THE EIGENVALUES IN ASCENDING ORDER.  IF AN
!          ERROR EXIT IS MADE, THE EIGENVALUES ARE CORRECT AND
!          ORDERED FOR INDICES 1,2,...IERR-1, BUT MAY NOT BE
!          THE SMALLEST EIGENVALUES,
!
!        E2 HAS BEEN DESTROYED,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 30 ITERATIONS.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                MACHEP THE VALUE U WHERE U IS THE SMALLEST POSITIVE
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           MACHEP = SPMPAR(1)
!
!                **********
!
IERR = 0
IF (N .EQ. 1) GO TO 1001
!
do 100 I = 2, N
100 E2(I-1) = E2(I)
!
F = 0.0
B = 0.0
E2(N) = 0.0
!
DO L = 1, N
   J = 0
   H = MACHEP * (ABS(D(L)) + SQRT(E2(L)))
   IF (B .GT. H) GO TO 105
   B = H
   C = B * B
!     ********** LOOK FOR SMALL SQUARED SUB-DIAGONAL ELEMENT **********
105 DO M = L, N
      IF (E2(M) .LE. C) GO TO 120
!     ********** E2(N) IS ALWAYS ZERO, SO THERE IS NO EXIT
!                THROUGH THE BOTTOM OF THE LOOP **********
   END DO
!
120 IF (M .EQ. L) GO TO 210
130 IF (J .EQ. 30) GO TO 1000
   J = J + 1
!     ********** FORM SHIFT **********
   L1 = L + 1
   S = SQRT(E2(L))
   G = D(L)
   P = (D(L1) - G) / (2.0 * S)
   R = SQRT(P*P+1.0)
   IF (P .LT. 0.0) R = -R
   D(L) = S / (P + R)
   H = G - D(L)
!
   do 140 I = L1, N
140 D(I) = D(I) - H
!
   F = F + H
!     ********** RATIONAL QL TRANSFORMATION **********
   G = D(M)
   IF (G .EQ. 0.0) G = B
   H = G
   S = 0.0
   MML = M - L
!     ********** FOR I=M-1 STEP -1 UNTIL L DO -- **********
   DO II = 1, MML
      I = M - II
      P = G * H
      R = P + E2(I)
      E2(I+1) = S * R
      S = E2(I) / R
      D(I+1) = H + S * (H + D(I))
      G = D(I) - E2(I) / G
      IF (G .EQ. 0.0) G = B
      H = G * P / R
   END DO
!
   E2(L) = S * G
   D(L) = H
!     ********** GUARD AGAINST UNDERFLOW IN CONVERGENCE TEST **********
   IF (H .EQ. 0.0) GO TO 210
   IF (ABS(E2(L)) .LE. ABS(C/H)) GO TO 210
   E2(L) = H * E2(L)
   IF (E2(L) .NE. 0.0) GO TO 130
210 P = D(L) + F
!     ********** ORDER EIGENVALUES **********
   IF (L .EQ. 1) GO TO 250
!     ********** FOR I=L STEP -1 UNTIL 2 DO -- **********
   DO II = 2, L
      I = L + 2 - II
      IF (P .GE. D(I-1)) GO TO 270
      D(I) = D(I-1)
   END DO
!
250 I = 1
270 D(I) = P
END DO
!
GO TO 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 IERR = L
1001 RETURN
!     ********** LAST CARD OF TQLRAT **********
END SUBROUTINE TQLRAT

SUBROUTINE IMTQL1(N,D,E,IERR)
IMPLICIT NONE
INTENT(IN) N
INTENT(OUT) IERR
INTENT(INOUT) D, E
REAL SPMPAR
!
INTEGER I,J,L,M,N,II,MML,IERR
REAL D(N),E(N)
REAL B,C,F,G,P,R,S,MACHEP
!     REAL SQRT,ABS,SPMPAR
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE IMTQL1,
!     NUM. MATH. 12, 377-383(1968) BY MARTIN AND WILKINSON,
!     AS MODIFIED IN NUM. MATH. 15, 450(1970) BY DUBRULLE.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 241-248(1971).
!
!     THIS SUBROUTINE FINDS THE EIGENVALUES OF A SYMMETRIC
!     TRIDIAGONAL MATRIX BY THE IMPLICIT QL METHOD.
!
!     ON INPUT-
!
!        N IS THE ORDER OF THE MATRIX,
!
!        D CONTAINS THE DIAGONAL ELEMENTS OF THE INPUT MATRIX,
!
!        E CONTAINS THE SUBDIAGONAL ELEMENTS OF THE INPUT MATRIX
!          IN ITS LAST N-1 POSITIONS.  E(1) IS ARBITRARY.
!
!      ON OUTPUT-
!
!        D CONTAINS THE EIGENVALUES IN ASCENDING ORDER.  IF AN
!          ERROR EXIT IS MADE, THE EIGENVALUES ARE CORRECT AND
!          ORDERED FOR INDICES 1,2,...IERR-1, BUT MAY NOT BE
!          THE SMALLEST EIGENVALUES,
!
!        E HAS BEEN DESTROYED,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 30 ITERATIONS.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                MACHEP THE VALUE U WHERE U IS THE SMALLEST POSITIVE
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           MACHEP = SPMPAR(1)
!
!                **********
!
IERR = 0
IF (N .EQ. 1) GO TO 1001
!
do 100 I = 2, N
100 E(I-1) = E(I)
!
E(N) = 0.0
!
DO L = 1, N
   J = 0
!     ********** LOOK FOR SMALL SUB-DIAGONAL ELEMENT **********
105 DO M = L, N
      IF (M .EQ. N) GO TO 120
      IF (ABS(E(M)) .LE. MACHEP * (ABS(D(M)) + ABS(D(M+1)))) &
&GO TO 120
   END DO
!
120 P = D(L)
   IF (M .EQ. L) GO TO 215
   IF (J .EQ. 30) GO TO 1000
   J = J + 1
!     ********** FORM SHIFT **********
   G = (D(L+1) - P) / (2.0 * E(L))
   R = SQRT(G*G+1.0)
   IF (G .LT. 0.0) R = -R
   G = D(M) - P + E(L) / (G + R)
   S = 1.0
   C = 1.0
   P = 0.0
   MML = M - L
!     ********** FOR I=M-1 STEP -1 UNTIL L DO -- **********
   DO II = 1, MML
      I = M - II
      F = S * E(I)
      B = C * E(I)
      IF (ABS(F) .LT. ABS(G)) GO TO 150
      C = G / F
      R = SQRT(C*C+1.0)
      E(I+1) = F * R
      S = 1.0 / R
      C = C * S
      GO TO 160
150 S = F / G
      R = SQRT(S*S+1.0)
      E(I+1) = G * R
      C = 1.0 / R
      S = S * C
160 G = D(I+1) - P
      R = (D(I) - G) * S + 2.0 * C * B
      P = S * R
      D(I+1) = G + P
      G = C * R - B
   END DO
!
   D(L) = D(L) - P
   E(L) = G
   E(M) = 0.0
   GO TO 105
!     ********** ORDER EIGENVALUES **********
215 IF (L .EQ. 1) GO TO 250
!     ********** FOR I=L STEP -1 UNTIL 2 DO -- **********
   DO II = 2, L
      I = L + 2 - II
      IF (P .GE. D(I-1)) GO TO 270
      D(I) = D(I-1)
   END DO
!
250 I = 1
270 D(I) = P
END DO
!
GO TO 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 IERR = L
1001 RETURN
!     ********** LAST CARD OF IMTQL1 **********
END SUBROUTINE IMTQL1

SUBROUTINE TRED2(NM,N,A,D,E,Z)
IMPLICIT NONE
INTENT(IN) A, N, NM
INTENT(INOUT) D, E, Z
!
INTEGER I,J,K,L,N,II,NM,JP1
REAL A(NM,N),D(N),E(N),Z(NM,N)
REAL F,G,H,HH,SCALE
!     REAL SQRT,ABS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE TRED2,
!     NUM. MATH. 11, 181-195(1968) BY MARTIN, REINSCH, AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 212-226(1971).
!
!     THIS SUBROUTINE REDUCES A REAL SYMMETRIC MATRIX TO A
!     SYMMETRIC TRIDIAGONAL MATRIX USING AND ACCUMULATING
!     ORTHOGONAL SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        A CONTAINS THE REAL SYMMETRIC INPUT MATRIX.  ONLY THE
!          LOWER TRIANGLE OF THE MATRIX NEED BE SUPPLIED.
!
!     ON OUTPUT-
!
!        D CONTAINS THE DIAGONAL ELEMENTS OF THE TRIDIAGONAL MATRIX,
!
!        E CONTAINS THE SUBDIAGONAL ELEMENTS OF THE TRIDIAGONAL
!          MATRIX IN ITS LAST N-1 POSITIONS.  E(1) IS SET TO ZERO,
!
!        Z CONTAINS THE ORTHOGONAL TRANSFORMATION MATRIX
!          PRODUCED IN THE REDUCTION,
!
!        A AND Z MAY COINCIDE.  IF DISTINCT, A IS UNALTERED.
!
!-----------------------------------------------------------------------
!
do 100 I = 1, N
!
   do 100 J = 1, I
      Z(I,J) = A(I,J)
100 CONTINUE
!
IF (N .EQ. 1) GO TO 320
!     ********** FOR I=N STEP -1 UNTIL 2 DO -- **********
DO II = 2, N
   I = N + 2 - II
   L = I - 1
   H = 0.0
   SCALE = 0.0
   IF (L .LT. 2) GO TO 130
!     ********** SCALE ROW (ALGOL TOL THEN NOT NEEDED) **********
   do 120 K = 1, L
120 SCALE = SCALE + ABS(Z(I,K))
!
   IF (SCALE .NE. 0.0) GO TO 140
130 E(I) = Z(I,L)
   GO TO 290
!
140 DO K = 1, L
      Z(I,K) = Z(I,K) / SCALE
      H = H + Z(I,K) * Z(I,K)
   END DO
!
   F = Z(I,L)
   G = SQRT(H)
   IF (F .GE. 0.0) G = -G
   E(I) = SCALE * G
   H = H - F * G
   Z(I,L) = F - G
   F = 0.0
!
   DO J = 1, L
      Z(J,I) = Z(I,J) / H
      G = 0.0
!     ********** FORM ELEMENT OF A*U **********
      do 180 K = 1, J
180 G = G + Z(J,K) * Z(I,K)
!
      JP1 = J + 1
      IF (L .LT. JP1) GO TO 220
!
      do 200 K = JP1, L
200 G = G + Z(K,J) * Z(I,K)
!     ********** FORM ELEMENT OF P **********
220 E(J) = G / H
      F = F + E(J) * Z(I,J)
   END DO
!
   HH = F / (H + H)
!     ********** FORM REDUCED A **********
   do 260 J = 1, L
      F = Z(I,J)
      G = E(J) - HH * F
      E(J) = G
!
      do 260 K = 1, J
         Z(J,K) = Z(J,K) - F * E(K) - G * Z(I,K)
260 CONTINUE
!
290 D(I) = H
END DO
!
320 D(1) = 0.0
E(1) = 0.0
!     ********** ACCUMULATION OF TRANSFORMATION MATRICES **********
do 500 I = 1, N
   L = I - 1
   IF (D(I) .EQ. 0.0) GO TO 380
!
   do 360 J = 1, L
      G = 0.0
!
      do 340 K = 1, L
340 G = G + Z(I,K) * Z(K,J)
!
      do 360 K = 1, L
         Z(K,J) = Z(K,J) - G * Z(K,I)
360 CONTINUE
!
380 D(I) = Z(I,I)
   Z(I,I) = 1.0
   IF (L .LT. 1) GO TO 500
!
   DO J = 1, L
      Z(I,J) = 0.0
      Z(J,I) = 0.0
   END DO
!
500 CONTINUE
!
RETURN
!     ********** LAST CARD OF TRED2 **********
END SUBROUTINE TRED2

SUBROUTINE TQL2(NM,N,D,E,Z,IERR)
IMPLICIT NONE
INTENT(IN) N, NM
INTENT(OUT) IERR
INTENT(INOUT) D, E, Z
REAL SPMPAR
!
INTEGER I,J,K,L,M,N,II,L1,NM,MML,IERR
REAL D(N),E(N),Z(NM,N)
REAL B,C,F,G,H,P,R,S,MACHEP
!     REAL SQRT,ABS,SPMPAR
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE TQL2,
!     NUM. MATH. 11, 293-306(1968) BY BOWDLER, MARTIN, REINSCH, AND
!     WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 227-240(1971).
!
!     THIS SUBROUTINE FINDS THE EIGENVALUES AND EIGENVECTORS
!     OF A SYMMETRIC TRIDIAGONAL MATRIX BY THE QL METHOD.
!     THE EIGENVECTORS OF A FULL SYMMETRIC MATRIX CAN ALSO
!     BE FOUND IF  TRED2  HAS BEEN USED TO REDUCE THIS
!     FULL MATRIX TO TRIDIAGONAL FORM.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        D CONTAINS THE DIAGONAL ELEMENTS OF THE INPUT MATRIX,
!
!        E CONTAINS THE SUBDIAGONAL ELEMENTS OF THE INPUT MATRIX
!          IN ITS LAST N-1 POSITIONS.  E(1) IS ARBITRARY,
!
!        Z CONTAINS THE TRANSFORMATION MATRIX PRODUCED IN THE
!          REDUCTION BY  TRED2, IF PERFORMED.  IF THE EIGENVECTORS
!          OF THE TRIDIAGONAL MATRIX ARE DESIRED, Z MUST CONTAIN
!          THE IDENTITY MATRIX.
!
!      ON OUTPUT-
!
!        D CONTAINS THE EIGENVALUES IN ASCENDING ORDER.  IF AN
!          ERROR EXIT IS MADE, THE EIGENVALUES ARE CORRECT BUT
!          UNORDERED FOR INDICES 1,2,...,IERR-1,
!
!        E HAS BEEN DESTROYED,
!
!        Z CONTAINS ORTHONORMAL EIGENVECTORS OF THE SYMMETRIC
!          TRIDIAGONAL (OR FULL) MATRIX.  IF AN ERROR EXIT IS MADE,
!          Z CONTAINS THE EIGENVECTORS ASSOCIATED WITH THE STORED
!          EIGENVALUES,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 30 ITERATIONS.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                MACHEP THE VALUE U WHERE U IS THE SMALLEST POSITIVE
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           MACHEP = SPMPAR(1)
!
!                **********
!
IERR = 0
IF (N .EQ. 1) GO TO 1001
!
do 100 I = 2, N
100 E(I-1) = E(I)
!
F = 0.0
B = 0.0
E(N) = 0.0
!
DO L = 1, N
   J = 0
   H = MACHEP * (ABS(D(L)) + ABS(E(L)))
   IF (B .LT. H) B = H
!     ********** LOOK FOR SMALL SUB-DIAGONAL ELEMENT **********
   DO M = L, N
      IF (ABS(E(M)) .LE. B) GO TO 120
!     ********** E(N) IS ALWAYS ZERO, SO THERE IS NO EXIT
!                THROUGH THE BOTTOM OF THE LOOP **********
   END DO
!
120 IF (M .EQ. L) GO TO 220
130 IF (J .EQ. 30) GO TO 1000
   J = J + 1
!     ********** FORM SHIFT **********
   L1 = L + 1
   G = D(L)
   P = (D(L1) - G) / (2.0 * E(L))
   R = SQRT(P*P+1.0)
   IF (P .LT. 0.0) R = -R
   D(L) = E(L) / (P + R)
   H = G - D(L)
!
   do 140 I = L1, N
140 D(I) = D(I) - H
!
   F = F + H
!     ********** QL TRANSFORMATION **********
   P = D(M)
   C = 1.0
   S = 0.0
   MML = M - L
!     ********** FOR I=M-1 STEP -1 UNTIL L DO -- **********
   DO II = 1, MML
      I = M - II
      G = C * E(I)
      H = C * P
      IF (ABS(P) .LT. ABS(E(I))) GO TO 150
      C = E(I) / P
      R = SQRT(C*C+1.0)
      E(I+1) = S * P * R
      S = C / R
      C = 1.0 / R
      GO TO 160
150 C = P / E(I)
      R = SQRT(C*C+1.0)
      E(I+1) = S * E(I) * R
      S = 1.0 / R
      C = C * S
160 P = C * D(I) - S * G
      D(I+1) = H + S * (C * G + S * D(I))
!     ********** FORM VECTOR **********
      DO K = 1, N
         H = Z(K,I+1)
         Z(K,I+1) = S * Z(K,I) + C * H
         Z(K,I) = C * Z(K,I) - S * H
      END DO
!
   END DO
!
   E(L) = S * P
   D(L) = C * P
   IF (ABS(E(L)) .GT. B) GO TO 130
220 D(L) = D(L) + F
END DO
!     ********** ORDER EIGENVALUES AND EIGENVECTORS **********
do 300 II = 2, N
   I = II - 1
   K = I
   P = D(I)
!
   do 260 J = II, N
      IF (D(J) .GE. P) GO TO 260
      K = J
      P = D(J)
260 CONTINUE
!
   IF (K .EQ. I) GO TO 300
   D(K) = D(I)
   D(I) = P
!
   DO J = 1, N
      P = Z(J,I)
      Z(J,I) = Z(J,K)
      Z(J,K) = P
   END DO
!
300 CONTINUE
!
GO TO 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 IERR = L
1001 RETURN
!     ********** LAST CARD OF TQL2 **********
END SUBROUTINE TQL2

